  str_dispatch_book_bookname_14000 = "로사와 M&M의 연락 기록",
  str_dispatch_book_bookname_15000 = "레드 머큐리",
  str_dispatch_book_bookdes_1000 = "이 책은 원래 백야성의 신전이 소장 중이나 내용이 너무 난해하여 공개되지 않았다고 한다. 그러나 100여 년 전 갑자기 행방불명되고부터 수많은 필사본이 나타나면서 세상에 알려졌다.",
  str_dispatch_book_bookdes_2000 = "이 책은 아인족의 고향이었던 비경 동굴이 초기에 어떻게 부흥했는지, 그 후 암귀의 침입을 받아 어떻게 점령된 것인지를 기록한 일부 역사 자료이다. 이 책을 통해서 수백 년 전에 벌어진 참극의 일부분을 엿볼 수 있으며, 오늘날 대륙 세력의 구도를 좀 더 깊이 이해할 수 있다.",
  str_dispatch_book_bookdes_3000 = "무명 용병의 노트. 그 또는 그녀가 열심히 용병으로 일하며 돈을 모아 자신의 용병대를 만들려고 했던 사연이 적혀있다. 작성된 연도는 알 수 없지만 근대임이 틀림없으며, 챕터마다 달로 구분되어 있다. 글씨가 매우 또렷하여 알아보기 쉽고, 그 안에는 낙천적인 기분마저 느껴진다.",
  str_dispatch_book_bookdes_4000 = "어떤 잠꼬대, 어떤 울음소리, 어떤 난리. 먼 옛날로부터 온 알 수 없는 원망과 미래에 대한 기이한 공포가 가득 차 있다. 그러나 이 모든 것이 지루한 이유는 이 책이 조잡한 모방품에 불과하기 때문이다. 아무리 노력해도 이 오래되고, 위대하고, 오래도록 잠들어 있는... 진리의 존재를 설명할 방법은 없다.\n──과연 그럴까?",
  str_dispatch_book_bookdes_5000 = "위대한 미식가이자 여행가인 레디젤 사막의 요리 철인, 암귀 육질 감별사가 바로 나라고! 보아하니 풋내기네. 분명 사막에 막 도착해서 대충대충 살아가고 있는 거구만? 이 조니 아저씨가 쓴 레시피를 주지. 최소한 아사하기 전에 모래를 먹을 일은 없어진다고! 왜냐고? 모래 같은 건 먹으면 밖으로 내보내는 게 곤란하잖아! 하하하, 바보 녀석!",
  str_dispatch_book_bookdes_6000 = "모두들 잘 알지 못하겠지만, 유명한 Ms. 블랑은 백야성의 안내자일 뿐만 아니라 무척 우수한 가이드이자 여행자이다. 그러나 Ms. 블랑은 자신이 인정한 귀한 손님에게만 가이드를 담당한다. 이 책은 Ms. 블랑을 인터뷰 게스트로 초청할 수 있는 영광을 안았고, 그 인터뷰의 내용을 책으로 엮어냈다.\n각 지역 제휴 서점에 예약한 고객에게는 Ms. 블랑의 특별 엽서를 받을 기회가 주어진다. 또한 행운의 독자 10명을 추첨하여 Ms. 블랑의 사인이 들어 있는 엽서를 선물로 증정한다.",
  str_dispatch_book_bookdes_7000 = "《종말의 말씀》은 북방 변경의 여러 고대 문명 유적에서 출토된 고대 문서들을 정리 및 연결하여 만들어진 기록이라고 한다. 연구자들은 원본의 기록이 이상하리만큼 훼손되어 있어 누군가의 고의적 소행이라 추측했다. 다행히 남겨진 서적의 내용은 비교적 온전했으나 묘사된 내용은 종말에 관한 내용으로 확인된다...",
  str_dispatch_book_bookdes_8000 = "「미지의 서」는 일루미나의 초대 연구원장이 일루미나에서 다년간 옛 문명의 과학 기술을 탐색한 결정체와, 현재 전해지지 않는 수많은 실험 원고를 종합하여 저술한 것이라고 전해진다. 그러나 그 연구원장이 도망치면서 「미지의 서」도 함께 실종되었다. 현세에 전해지는 이른바 「미지의 서」 관련 자료라는 것도 원작의 극히 일부분이기 때문에 진위를 가리기가 어렵다.",
  str_dispatch_book_bookdes_9000 = "《용감한 자의 출항》은 움브라톤에서 태어난 소설가가 지은 판타지 모험 소설로 한 소년이 왕국의 함대를 따라 바다에 나가면서 알 수 없는 사건과 다양한 괴물을 만나고, 전설 속의 보물을 찾아내 왕국의 안위를 위협하는 심해의 괴물을 무찌르는 이야기이다. 《용감한 자의 출항》은 많은 편장이 있지만 초판에는 다음 몇 편만이 남아 있었다.",
  str_dispatch_book_bookdes_10000 = "일루미나 연방, 정식 명칭은 「아스트라 일루미나 연방」, 수도는 자난성이다. 이 책은 일루미나 연방 행정 관리국에서 저술한 것으로 일루미나 연방 위원회, 일루미나 연방군, 일루미나 연구소 등 각 부분의 건의를 참고해서 새로이 일루미나에 합류하는 사람들에게 적절한 지도를 하고자 만들어졌다.",
  str_dispatch_book_bookdes_11000 = "하이든이 쓴 《아이다와 콜로서스》는 헤븐즈 밸리에 널리 전해지는 유명한 동화이자 아이테르의 계몽 도서다. 이 책은 아이다라는 아이테르 소녀가 나약한 콜로서스 윈드러너호와 교류하며 협곡을 떠나 세상을 탐험하는 이야기로 둘의 모험을 통해 아이올리아, 백야와 극야, 오로리안과 암귀 등의 개념을 보편화했다.",
  str_dispatch_book_bookdes_12000 = "아스트라 대륙의 유명한 여행가인 미나, 그녀의 여행기는 오로리안들 사이에서 널리 알려져 있다. 그녀의 자서전적인 성향이 짙은 이 여행기에는 어린 시절의 후회스러운 일이 하나 적혀있는데... 골드리버 강가의 마을에 살던 소녀는 백야성에서 온 '기사' 세리오자와 친해졌지만 결국 각자의 길로 떠날 수밖에 없었다. 《여행의 시작》이라는 제목의 이 이야기 속에서는 백야성의 기사단, 루미나틱스의 베일이 하나둘씩 벗겨질 것이다.",
  str_dispatch_book_bookdes_13000 = "북방을 떠도는 이야기로, 그 진위는 아무도 모른다. 북방을 떠도는 한 음유시인이 이 이야기들을 모음집으로 엮어 만들었다. 정체를 알 수 없는 금발의 오로리안과 부모님을 잃은 두 아이는 북방의 마을에서 만나 서로 감싸주고, 도와주며 깊은 정을 나눈다. 또한 이 이야기에서는 북방 오로리안의 일상생활을 들여다볼 수 있다.",
  str_dispatch_book_bookdes_14000 = "이것은 레디젤 사막의 엔지니어 로사와 움브라톤 M&M 중고 부품가게의 연락을 기록해둔 것이나, 적지 않은 내용이 소실되었다. 로사는 값싼 개조 부품을 사기 위해 움브라톤의 부품가게 M&M을 찾았고, 그곳에는 때마침 필요로 하는 물건이 있었다. 이 둘의 협력 관계는 로사가 죽기 전까지 10여 년 동안 계속되었으며, 이 기록을 통해 레디젤 사막과 움브라톤의 일상생활을 살펴볼 수 있다.",
  str_dispatch_book_bookdes_15000 = "이본은 실제 사건과 실존 인물에 허구의 이야기를 교묘하게 섞어 풀어내기로 유명한 소설가로, 대표적인 단편 소설로는 《레드 머큐리》가 있다. 이는 움브라톤 상회의 수장이었던 머큐리 부인의 전설적인 이야기를 다룬 소설로, 여러 번 재판되었는데, 그중에서도 2쇄의 편집자는 독자와 교감하기 위해 이야기 속 인물과 사건을 고증해 후기에 기록했다. 이 소설을 통해 독자들은 수십 년 전 움브라톤의 위상을 엿볼 수 있다.",
