  str_dispatch_book_chaptername_15000_7 = "여관에서의 만남(3)",
  str_dispatch_book_chaptername_15000_8 = "여관에서의 만남(4)",
  str_dispatch_book_chaptername_15000_9 = "살인 사건",
  str_dispatch_book_chaptername_15000_10 = "에필로그",
  str_dispatch_book_chaptername_15000_11 = "편집 후기(상)",
  str_dispatch_book_chaptername_15000_12 = "편집 후기(하)",
  str_dispatch_book_chapterdes_1000_1 = "믿는 자에게는 계시가 있을 것이니 몸을 낮춰 듣고, 경외하고 긍휼히 여길 것이오.\n믿지 않는 자에게는 계시가 없으니 제도와 문물을 떠나 지키자 함도, 경계도 없도다.\n계시를 받은 자는 재난을 만나도 피할 것이오.\n계시가 없는 자는 재난 없어도 지푸라기와 같도다.",
  str_dispatch_book_chapterdes_1000_2 = "빛의 신께서 모든 이를 위해 싸우시니 뭇 사람은 침묵하고 소리를 내지 말지어다.\n빛의 신께서 바닷물을 가르고, 산을 깎으시니 뭇 사람은 침묵하고 소리를 내지 말지어다.",
  str_dispatch_book_chapterdes_1000_3 = "둘 사이에 심판하여 모든 사람에게 신의 율례와 법도를 알게 하며\n신을 공경하는 자, 믿음이 없는 자는 율법에 따라 상을 받거나 벌을 받게 되는도다.",
  str_dispatch_book_chapterdes_1000_4 = "바라는 것을 반드시 볼 것이오.\n원하는 것을 반드시 돌려줄 것이니\n태초부터 말씀한 모든 것을 기억하라\n약속과 계시를 영원토록 기억하라.",
  str_dispatch_book_chapterdes_2000_1 = "아인족은 운명적으로 역사상 가장 큰 인공 동굴을 발견했다. 천성적으로 순진했던 그들은 자신들의 집을 짓기 위해서, 또 자신들만의 「새로운 낙원」을 만들기 위해서, 산을 깎고 바다를 개척하는 위력을 발휘하였다.",
  str_dispatch_book_chapterdes_2000_2 = "천 년도 더 전, 아인족은 비경 동굴을 발견했다. 그 후 수백 년간, 무수한 아인족은 이곳에서 태어나고, 자라고, 죽었다. 비경은 아인족에게 최고라는 단어의 대명사이며, 모든 아인족이 천 년간 일구어낸 고향이었다. 그러나 암귀의 습격으로 아인족은 비경 동굴을 잃어버리게 되었고...",
  str_dispatch_book_chapterdes_2000_3 = "비경 동굴은 모든 아인족의 현재이자 정신적인 고향이었다. 그렇기에 암귀가 침입했을 당시 비경 동굴에 남아있던 아인족만 필사적으로 저항했던 것이 아니었다. 밖에서 유랑하던 모든 아인족이 이곳으로 돌아와 함께 암귀에게 대항하였다. 그러나 그 고향에 대한 집념이 아인족에게 파멸을 가져다주었다.",
  str_dispatch_book_chapterdes_2000_4 = "아인족의 멸망에 당황한 오로리안, 일루미나 연방은 용감한 탐색대를 파견해 암귀가 활개 치는 비경 동굴에서 아인족 멸망의 원인을 조사하도록 했다. 하지만 그 당시 비경 동굴은 이미 매우 위험한 곳이 되어 의지가 매우 강한 일루미나 병사도 동요를 감출 수가 없었다.",
  str_dispatch_book_chapterdes_3000_1 = "무명 용병이 작전을 수행한 후의 기록. 보안을 이유로 일부 지역명은 비워두었는데 정말로 공백만 남겨두어 추측할 일말의 여지조차 없다.",
  str_dispatch_book_chapterdes_3000_2 = "무명 용병의 또 다른 기록, 이전 작전에서 제대로 된 보수를 받지 못한 것 같다. 그리고 이번 작전에는 또 다른 골치 아픈 일이 생긴 것 같다.",
  str_dispatch_book_chapterdes_3000_3 = "보수 협상에 누차 실패를 맛본 이 무명 용병은 결국 어려운 임무들은 포기하고 용병답지 않는 일을 찾은 것 같다. 의외인 것은 이 일을 하는 용병의 글 속에 즐거움이 나타나 있다는 것이었다.",
  str_dispatch_book_chapterdes_3000_4 = "무명 용병의 마지막 노트. 용병의 지난 삶을 그리워하면서 새로운 삶의 계획을 기록했다. 읽으면 희망이 차오르는 것을 느끼게 된다.",
  str_dispatch_book_chapterdes_4000_1 = "진리, 볼 수 없다.\n신도, 네가 보인다.\n부름, 그 있는 곳을 알다.\n거부, 넌 할 수 없다.",
  str_dispatch_book_chapterdes_4000_2 = "그것은, 어디에나 있는 것 같다.\n아픔은, 순간적으로 부풀어 오른다.\n그것은, 어디에나 있을 것이다.\n꽃은, 피바다에서 피어난다.",
  str_dispatch_book_chapterdes_4000_3 = "진흙, 진리의 겉옷이다.\n진흙, 진리의 맛이다.\n삼키기, 진리를 얻는 것이다.\n맛보기, 진리에 익숙해지는 것이다.",
  str_dispatch_book_chapterdes_4000_4 = "그 날, 반드시 오지 않는다.\n날 믿어, 강림은 거짓말이다.\n사망, 이미 과거가 되었다.\n향락, 영원히 사라지지 않는다.",
  str_dispatch_book_chapterdes_5000_1 = "레디젤 사막에 오면 밖에서 먹을 수 없는 걸 먹어야 한다. 패스트 푸드 같은 걸 먹고 싶다면 어디로든 돌아가 버려! 레디젤 사막에 오면 말린 샌드버그! 귀뚜라미 튀김! 낙타 통찜! 레디젤 선인장! 이런 걸 먹어야 한다고!",
  str_dispatch_book_chapterdes_5000_2 = "이 사막에는 모두 레디젤을 마시며 흥을 돋우는 변태만 있다고 생각한다면 정말로 큰 실수하는 거야. 몇 명은 다리 아래 가축의 식량을 빼앗는다고? 오늘 이 조니 아저씨가 레디젤 사막에서 가장 훌륭한 「샌드버그 라운드」 바에 데리고 가주지. 뭐? 미성년자라고? 그럼 낙타 젖이나 마셔!",
  str_dispatch_book_chapterdes_5000_3 = "뭐? 네가 채식주의자라고? 맙소사, 그게 대왕 낙타 고기를 포기할 이유가 될 순 없어. 그냥 과일이라고 생각해! 우리가 입만 다물면 이 낙타 고기는 과일이 되는 거라고! 먹어 봐, 분명 사랑하게 될 테니까!",
  str_dispatch_book_chapterdes_5000_4 = "뜨거운 열기! 터질듯한 매콤함! 매운맛은 레디젤 사막의 상징이지! 귀에서 연기가 날 정도의 매운맛, 입에서 불을 뿜고 머리에서 증기가 솟아오를 매운맛! 매운맛을 견딜 수 없다면 레디젤 사막의 모래바람도 견딜 수 없으리라. 옛말에 「매운맛을 즐기는 자 싸움도 잘한다」라고 했다.",
  str_dispatch_book_chapterdes_5000_5 = "젊은 사람이라면 큰 꿈 정도는 있어야지. 아스트라의 모든 먹거리를 먹어보는 건 아니더라도 레디젤 사막의 먹거리는 다 먹어봐야 하지 않겠어? 뭘 그리 긴장해? 사막의 모래를 먹어치우라는 것도 아닌데! 근데 듣자 하니 모래돌밥이 샤크팽 섬의 명물 중 하나라고 하더라...",
  str_dispatch_book_chapterdes_6000_1 = "흔히 땅의 호수는 모두 신이 인간 세상에 떨어뜨린 눈물이라고 한다. 대륙에서 가장 오래되고 제일 아름다운 호수는 거울 호수인데, 이는 분명히 신께서 인간 세상을 불쌍히 여겨 흘린 가장 아름다운 눈물 한 방울일 것이다.",
  str_dispatch_book_chapterdes_6000_2 = "풍맥의 숲은 북방 남쪽에 위치한 숲이지만 북방이 사람에게 주는 차가운 인상과는 전혀 다른 곳이다. 이곳은 일 년 내내 기후가 따뜻하고, 사계절이 봄과 같다. 이곳의 숲 속 동식물들은 모두 바람의 비호 아래 아무런 걱정 없이 살아가고 있다고 한다.",
  str_dispatch_book_chapterdes_6000_3 = "겉으로 보긴엔 언덕 같지만 원주민의 전설에 따르면 송림지대의 진짜 모습은 「신의 깨진 수정」이라고 한다.",
  str_dispatch_book_chapterdes_6000_4 = "「세계의 등마루」에 위치한 「윈터 팰리스」는 오로지 얼음으로 구성된 궁전으로 북방의 여왕 베들레헴이 거주하는 곳이자 북방 통치의 중심지다.",
  str_dispatch_book_chapterdes_7000_1 = "이것은 「어둠이 내리기 전」이라는 이름의 남겨진 기록이다. 내용이 끊긴 부분에는 누군가 일부러 지운 흔적이 남아있다.",
  str_dispatch_book_chapterdes_7000_2 = "연구자들은 이 흔하고도 이해하기 쉬운 기록이 고대인의 손에서 나온 것이 아닌, 근현대의 누군가가 남긴 기록이라 여겼다. 그것은 확실히 『종말의 말씀』 중 하나였지만 지금까지도 사람들은 그와 종말의 관계를 설명해내지 못했다.",
  str_dispatch_book_chapterdes_7000_3 = "이 파손된 문서는 앞 부분의 내용이 소실됐다. 연구자들은 「그들」이란 전쟁 이전에 살았던 사람들이고 「우리」란 이 기록을 남긴 사람이라고 추측했다.",
  str_dispatch_book_chapterdes_8000_1 = "코드네임「발키리」의 실험 파일. 북방 어느 깊숙한 산속의 옛 문명 유적에서 발견되었다. 동시에 발견된 대량의 실험 데이터와 문서는 알 수 없는 이유로 훼손되어 읽을 수가 없다.",
  str_dispatch_book_chapterdes_8000_2 = "한 과학자가 손으로 쓴 원고의 일부분. 그 가운데서 자신의 딸을 실험체로 삼은 미친 행동을 찾아볼 수 있다. 이 원고는 바스 마을 폐허에서 발견되었다.",
  str_dispatch_book_chapterdes_8000_3 = "레디젤 사막 주변의 부락과 유랑민에게서 전해지는 오래된 서적의 낱장이다. 전투 기록으로 사료되지만, 정확한 시간, 장소, 전투 부대에 대한 정보는 알아볼 수 없다. 고대 문명의 발달한 기술을 엿볼 수 있는 기록이다.",
  str_dispatch_book_chapterdes_8000_4 = "이 잔본은 옛 마을 주변의 폐허에서 발견됐다고 한다. 소설의 어느 한 편장 같기도 하고, 어떤 기록 같기도 하다. 잔본에는 「드라큘라」에 관한 전설이 적혀 있었다.",
  str_dispatch_book_chapterdes_9000_1 = "왕국은 새로운 섬으로 탐사를 떠날 용사들을 모집했다. 「폭풍」 제3장은 함대가 바다에서 폭풍을 만났을 때 용감한 행동으로 모두의 존중을 받은 콜린의 이야기를 묘사한다.",
  str_dispatch_book_chapterdes_9000_2 = "함대는 일곱 섬에서 보물을 찾을 계획이었다. 「일곱 개의 섬」 제2장에서는 일행이 두 번째 섬에 오른 후 비룡의 습격을 받은 뒤 첫 번째 섬으로 돌아왔는데, 그 섬이 사라진 이야기를 다루고 있다.",
  str_dispatch_book_chapterdes_9000_3 = "함대는 바다에서 거대한 촉수 괴물의 습격을 받았고, 혼란 속에서 용사는 바다로 떨어졌다. 「해저왕국」 제4장은 용사가 신비로운 해저왕국에서 깨어난 후의 이야기를 다루고 있다.",
  str_dispatch_book_chapterdes_9000_4 = "왕국에서 편성한 토벌대가 심해 괴물을 토벌할 방법을 찾고 있다. 「심해 괴물」 제6장은 마지막 보물이 숨겨진 섬에 용사 일행이 도착하자 심해 괴물이 진짜 모습을 드러내는 이야기다...",
  str_dispatch_book_chapterdes_10000_1 = "일루미나인의 사교와 생활 지침의 일부분. 이 장에서는 주로 일루미나인의 핵심 신조를 다루고 있다.",
  str_dispatch_book_chapterdes_10000_2 = "일루미나인의 사교와 생활 지침의 일부분. 이 장에서는 주로 일루미나인이 지켜야 할 핵심 규율을 다루고 있다.",
  str_dispatch_book_chapterdes_10000_3 = "일루미나인의 사교와 생활 지침의 일부분. 이 장에서는 주로 일루미나인이 알아야 할 사회 문화를 다루고 있다.",
  str_dispatch_book_chapterdes_10000_4 = "일루미나인의 사교와 생활 지침의 일부분으로 이 장에서는 주로 일루미나인이 알아야 할 규칙을 다루고 있다.",
  str_dispatch_book_chapterdes_10000_5 = "일루미나인의 사교와 생활 지침의 일부분으로 이 장에서는 주로 일루미나인이 지켜야 할 각종 조례를 다루고 있다.",
  str_dispatch_book_chapterdes_11000_1 = "그날, 소녀 아이다는 나약한 콜로서스 「윈드러너호」와 바람을 타고 별과 함께 날아오르며 살아왔던 헤븐즈 밸리를 떠났다. 바깥 세상의 모든 것은 그림처럼 서서히 펼쳐졌고 하늘의 오로라는 마치 꿈처럼 모험의 첫 획을 그어주었다.",
  str_dispatch_book_chapterdes_11000_2 = "자신을 「아인」이라 부르는 신기한 꼬마 동물은 온몸이 보송보송한 털로 뒤덮여 너무 부드러웠다. 제아무리 콜로서스라도 이런 귀여운 공세에 저항할 순 없을 테지! 따스한 햇볕을 맞으며 이 보송보송한 녀석을 품고 있노라면 온종일 맘 편히 누워있을 수 있다.",
  str_dispatch_book_chapterdes_11000_3 = "꽃으로 뒤덮인 콜로서스는 생명의 종점에 다다랐다. 그는 헤븐즈 밸리를 너무 오래 떠나있었다. 그와 함께했던 조종사는 아이다와 윈드러너처럼 호기심과 희망을 품고 바깥세상에 뛰어들었지만, 바깥세상을 보는 게 정말 옳은 일이었을까? 가끔은 너무 멀리 와버려서, 집으로 돌아가는 방향도 찾지 못하게 된다.",
  str_dispatch_book_chapterdes_11000_4 = "사막을 달리는 선박이 아이다와 윈드러너 앞에 섰다. 그곳에서 신비로운 오로리안 여단이 등장했다. 바람이 지면의 모래를 일으켰다. 선박은 모래 위를 달리는 게 아니었다. 은하수의 궤적을 따라 전진하는 것이었다.",
  str_dispatch_book_chapterdes_11000_5 = "아이다와 윈드러너의 족적은 세계 각지에 남겨졌다. 하지만 유일하게 한 곳에는 공백으로 남았으니, 그곳은 헤븐즈 밸리였다. 어쩌면, 최초의 장소로 돌아갈 때일지도 모르겠다...",
  str_dispatch_book_chapterdes_12000_1 = "미나에게 어린 시절 골드리버 강가에 갇혀 있었던 날들은 회상하기조차 싫은 나날이다. 그 당시 그녀의 생명에는 어떠한 이야기도, 의미도 없었고, 그녀는 그저 인내하며 살아갈 뿐이었다. 하지만 그 모든 것은 상단이 나타난 후로부터 변화의 움직임을 보이기 시작했다.",
  str_dispatch_book_chapterdes_12000_2 = "미나에게 어린 시절 골드리버 강가에 갇혀 있었던 날들은 회상하기조차 싫은 나날이다. 그 당시 그녀의 생명에는 어떠한 이야기도, 의미도 없었고, 그녀는 그저 인내하며 살아갈 뿐이었다. 하지만 그 모든 것은 상단이 나타난 후로부터 변화의 움직임을 보이기 시작했다.",
  str_dispatch_book_chapterdes_12000_3 = "상품 교환 요청을 거절당한 미나는 난처한 얼굴로 상단의 그늘진 공간에 서서 어찌할 바를 모르고 있었다. 그때, 하얀 갑옷을 입은 남자가 처한 곤경에서 벗어나도록 도와주었다. 미나가 알게 된 그의 이름은 바로 세리오자였다.",
  str_dispatch_book_chapterdes_12000_4 = "상품 교환 요청을 거절당한 미나는 난처한 얼굴로 상단의 그늘진 공간에 서서 어찌할 바를 모르고 있었다. 그때, 하얀 갑옷을 입은 남자가 처한 곤경에서 벗어나도록 도와주었다. 미나가 알게 된 그의 이름은 바로 세리오자였다.",
  str_dispatch_book_chapterdes_12000_5 = "세리오자는 마을을 떠난 후에도 계속해서 미나에게 편지를 보냈다. 미나는 바깥세상에 대한 무한한 환상을 가지게 되었고, 마을을 벗어나 마음속으로 그리는 세상에 더 가까이 가고 싶다는 생각까지 하게 되었다.",
  str_dispatch_book_chapterdes_12000_6 = "세리오자는 마을을 떠난 후에도 계속해서 미나에게 편지를 보냈다. 미나는 바깥세상에 대한 무한한 환상을 가지게 되었고, 마을을 벗어나 마음속으로 그리는 세상에 더 가까이 가고 싶다는 생각까지 하게 되었다.",
  str_dispatch_book_chapterdes_12000_7 = "미나는 쿠리어 길드에 가입하고 싶었지만 거절당했고, 계속해서 세리오자의 편지를 기다렸지만, 그 희망은 물거품이 되었다. 결국 미나는 자신이 태어나고 자란 땅을 떠나, 바깥세상을 자신의 두 눈으로 직접 보기로 결심했다. 그녀의 첫 번째 여행지는 바로 백야성이었다.",
  str_dispatch_book_chapterdes_12000_8 = "미나는 쿠리어 길드에 가입하고 싶었지만 거절당했고, 계속해서 세리오자의 편지를 기다렸지만, 그 희망은 물거품이 되었다. 결국 미나는 자신이 태어나고 자란 땅을 떠나, 바깥세상을 자신의 두 눈으로 직접 보기로 결심했다. 그녀의 첫 번째 여행지는 바로 백야성이었다.",
  str_dispatch_book_chapterdes_12000_9 = "미나는 백야성에는 들어갈 수 없었지만, 또 다른 기회를 얻게 되었다. 심지어 무료로 얻은 기회였다. 드디어 백야성으로 입성한 미나는 세리오자의 거처를 수소문했지만, 믿을 수 없는 소식을 듣게 되었다.",
  str_dispatch_book_chapterdes_12000_10 = "미나는 백야성에는 들어갈 수 없었지만, 또 다른 기회를 얻게 되었다. 심지어 무료로 얻은 기회였다. 드디어 백야성으로 입성한 미나는 세리오자의 거처를 수소문했지만, 믿을 수 없는 소식을 듣게 되었다.",
  str_dispatch_book_chapterdes_12000_11 = "미나는 세리오자가 남긴 주소를 찾아냈다. 하지만 점점 더 많은 숨겨진 진실이 하나둘씩 그녀에게 드러나고 있었다. 그리고 마침내, 미나는 자신의 우상이었던 세리오자를 찾았다. 하지만 이미 모든 것은 변해있었다.",
  str_dispatch_book_chapterdes_12000_12 = "미나는 세리오자가 남긴 주소를 찾아냈다. 하지만 점점 더 많은 숨겨진 진실이 하나둘씩 그녀에게 드러나고 있었다. 그리고 마침내, 미나는 자신의 우상이었던 세리오자를 찾았다. 하지만 이미 모든 것은 변해있었다.",
  str_dispatch_book_chapterdes_13000_1 = "도로시 남매는 북방의 마을에 살고 있었다. 부모님은 일찍이 돌아가셨기에 마을 사람들의 허드렛일을 돕고 먹을 것을 얻었다. 장로는 두 아이가 새로운 가정에 들어갔으면 했지만 누나 도로시는 단칼에 거절했다.",
  str_dispatch_book_chapterdes_13000_2 = "집으로 돌아오는 길에 도로시 남매는 눈밭에 쓰러진 오로리안을 도와주었고, 그 오로리안은 마을에 들어와 살게 되었다. 하지만 한밤중 눈보라에 그 오로리안의 집은 무너져버렸고, 다시 한번 도로시 남매에게 도움을 청했다.",
  str_dispatch_book_chapterdes_13000_3 = "장로의 도움으로 낯선 금발의 오로리안 마사는 도로시 남매의 집에서 함께 살게 되었다. 함께 지내는 시간이 늘어가면서 세 사람의 관계는 점차 가까워졌다.",
  str_dispatch_book_chapterdes_13000_4 = "마사는 음식 만들기에 열을 올렸고, 심지어 이 때문에 소금을 얻을 방법까지 생각해 보기도 했다. 마사의 방법을 들은 도로시는 직접 해봐야겠다는 생각이 들었다.",
  str_dispatch_book_chapterdes_13000_5 = "마사는 도로시 남매를 위해 저녁을 만들었고, 동생 크루즈와 이야기를 하다가 도로시의 마음을 알게 되었다. 하지만 중요한 사실은 그게 아니었다. 문제는 날이 어두워졌음에도 도로시가 아직 집에 돌아오지 않았다는 것이었다.",
  str_dispatch_book_chapterdes_13000_6 = "도로시는 마사의 말대로 함수호를 찾았지만, 눈보라 때문에 집으로 돌아가지 못하게 되었다. 밖에서 눈보라를 피하려던 도중 불행히도 굶주린 늑대와 마주하게 되었다.",
  str_dispatch_book_chapterdes_13000_7 = "도로시가 루미나틱스로 늑대의 공격을 막아냈지만, 위험한 상황에 처하고 말았다. 위기일발의 순간, 누군가 물어뜯으려는 늑대를 얼려 도로시를 위기에서 구해냈다.",
  str_dispatch_book_chapterdes_13000_8 = "북방의 새해가 되었다. 마사와 도로시 남매는 함께 새해를 보냈다. 마을 모임에서 온정은 소리 없이 커지고 있었다.",
  str_dispatch_book_chapterdes_13000_9 = "마을에 또 낯선 사람이 왔다. 마사의 이상한 행동을 본 도로시는 그 오로리안이 마사 때문에 온 것이라고 확신하게 되었다. 도로시는 계속해서 추궁했지만, 마사는 끝끝내 진실 알려주기를 거부했다.",
  str_dispatch_book_chapterdes_13000_10 = "장로는 수색대를 꾸렸고 도로시는 몰래 참여하려다가 마사에게 저지당했다. 발버둥을 치던 도로시는 그만 뼈아픈 말을 내뱉고야 말았다.",
  str_dispatch_book_chapterdes_13000_11 = "장로로부터 도로시 남매가 어떻게 부모님을 여의게 됐는지 듣게 된 마사는 북방을 떠날 결심을 했다. 도로시 남매 곁에 있으면 그녀는 양심의 가책을 견디지 못할 것이기 때문이었다.",
  str_dispatch_book_chapterdes_13000_12 = "마사는 마을을 떠나려고 했으나, 도로시가 그녀를 가로막았다. 도로시는 마사에게 그녀의 과거를 개의치 않지만, 떠나겠다는 그녀의 결정을 바꿀 마음도 없다고 했다. 그러면서 언젠가 북방으로 돌아오길 바란다고 이야기했다.",
  str_dispatch_book_chapterdes_14000_1 = "레디젤 사막에 사는 엔지니어 로사는 부품 부족으로 골머리를 앓고 있다. 그러던 도중 M&M 중고 부품가게의 광고를 발견했는데, 물건의 종류가 다양하고 가격이 합리적이었다. 이에 로사는 첫 번째 주문서를 써서 보냈고 만족스러운 회신을 받을 수 있었다.",
  str_dispatch_book_chapterdes_14000_2 = "여러 곳을 거쳐 주문한 부품을 겨우 받은 로사는 앞으로 쿠리어 길드를 통해서 주문서를 보내기로 결심했다. 이번 답장은 M&M 부품가게 주인의 딸 미니가 쓴 것이었다.",
  str_dispatch_book_chapterdes_14000_3 = "레디젤 사막 특수한 환경과 기후에 적응하기 위해서는 호버 트럭을 개조해야 했다. 편지에서 로사는 자신이 일루미나 탐색대에서 도망친 대원이라는 사실을 밝혔다.",
  str_dispatch_book_chapterdes_14000_4 = "가게 주인 맥스는 로사의 외상을 받아주었다. 미니는 로사가 보낸 호버 트럭 개조 도면으로 엔진을 만들고자 할 정도로 굉장한 관심을 보였다.",
  str_dispatch_book_chapterdes_14000_5 = "로사가 속해 있는 캠프가 강도 떼와 싸움을 하게 되었다. 그 일이 있고 난 뒤로 큰돈을 손에 넣게 되어 지난번에 졌던 빚을 갚을 수 있게 되었다. 그리고 여자아이 서머를 돌보게 되었는데, 그 아이는 고대 기술로 만들어진 물건을 많이 찾아주었다.",
  str_dispatch_book_chapterdes_14000_6 = "로사는 부품가게에서 고대의 기술로 만들어진 장치를 분해할 수 있는 물건을 찾길 원했지만, 그건 상당히 어려운 일이었다. 하지만 미니는 아버지가 상업적으로 어려움에 부딪히든 말든 신경 쓰지 않고 백야성 기념일 축제에 다녀왔고, 로사에게 많은 선물을 보냈다.",
  str_dispatch_book_chapterdes_14000_7 = "로사는 음악을 좋아하는 멤버에게 선물로 기타를 개조해 줄 계획을 세웠다. 또한 간식을 보내준 미니에 고마움을 전했는데, 이는 레디젤 사막의 음식이 도저히 입맛에 맞지 않아서였다.",
  str_dispatch_book_chapterdes_14000_8 = "로사가 속해 있는 캠프가 일루미나 수송대를 약탈했고, 사태가 심각해지면서 양측 모두 사상자가 속출했다. 이로 인해 로사도 두 다리를 잃고 말았다. 하지만 그녀의 마음을 더욱더 아프게 했던 것은 동료였던 사람들에게 총을 겨눈 것이었다.",
  str_dispatch_book_chapterdes_14000_9 = "결혼을 앞둔 미니는 로사에게 청첩장을 보냈다. 편지에는 결혼 생활에 대한 환상은 없었으며, 자신의 평범한 삶에 대한 싫증만이 적혀 있었다.",
  str_dispatch_book_chapterdes_14000_10 = "로사는 신체적인 이유로 미니의 결혼식에 참여할 수 없었기에, 대신 강철로 된 장미를 선물로 만들었고, 장미는 로사의 아름다운 축복과 함께 미니에게 전해졌다.",
  str_dispatch_book_chapterdes_14000_11 = "이번 편지를 쓴 사람은 서머로, 로사를 도와 고대 기술로 만든 물건을 찾아주던 어린 소녀였다. 그 뒤로 로사의 조수가 되었던 서머는 맥스 부녀에게 비보를 전했다.",
  str_dispatch_book_chapterdes_14000_12 = "미니는 자신과 아버지가 로사와 주고받았던 편지들을 회고했고, 로사를 자신이 알던 사람 중 가장 대단하고, 상상을 뛰어넘는 사람이라고 생각했다. 편지를 쓰기 전에 미니는 상단에 연락을 취했고, 친구의 마지막 길을 배웅하기 위해 레디젤 사막으로 향했다.",
  str_dispatch_book_chapterdes_15000_1 = "친구와 '나'는 움브라톤의 콜로세움에서 싸움을 지켜봤다. 실력 차이가 현격한 가운데, 열세에 처한 것은 뜻밖에도 상회 쪽 사람이었다. 상회 사람이 평범한 사람과 사투를 벌이고 있다는 사실을 단장이 그냥 넘어가지 않을 거라는 생각에 '나'는 무척 당혹스러웠다.",
  str_dispatch_book_chapterdes_15000_2 = "예상대로 싸움에서 밀린 애송이를 관객들 모두 걱정스럽게 쳐다보는 가운데, 휘슬이 울렸다. 애송이가 가까스로 목숨을 건지는 동안, 머큐리 부인이 앉아있던 관중석 구석에서 예상치 못한 소동이 벌어졌다.",
  str_dispatch_book_chapterdes_15000_3 = "관중석의 포로들은 애송이에게 보이지 않는 격려를 보내는 듯했다. 애송이는 싸움에서 이겼지만, 상회를 이끄는 머큐리 부인 앞에서 그의 운명은 여전히 어두워 보였다.",
  str_dispatch_book_chapterdes_15000_4 = "콜로세움의 여정이 끝난 후, '나'는 지체없이 친구에게 머큐리 부인에 관한 조언을 구했다. 머큐리 부인에 관한 소문을 항간에서 어렵지 않게 들을 수 있었지만, 믿을 수 있는 사실은 매우 적었다. 그럼에도 신분과 결혼 문제에 있어서 그녀가 보여준 결단은 그녀를 전설적 존재로 만들기에 충분했다.",
  str_dispatch_book_chapterdes_15000_5 = "드디어 '나'는 백야성에 들어갈 기회를 얻을 수 있었다. 중립 지구의 여관에서 출입 서류 심사를 기다리던 중, '나'는 예상치 못한 인물을 만났다.",
  str_dispatch_book_chapterdes_15000_6 = "머큐리 부인에게 막연한 두려움을 느끼던 '나'였지만, 호기심은 두려움을 이기고 말았다. '나'는 그녀를 모른 척하며 가까이 가서 말을 걸 수 있는 절호의 기회가 오기를 기다렸다.",
  str_dispatch_book_chapterdes_15000_7 = "마침내 '나'는 머큐리 부인에게 말을 걸 수 있었다. 대화를 나누던 중 머큐리 부인은 중립 지구에 나타난 이유, 자신의 꿈과 친구에 대한 그리움에 대한 사연을 들려줬다.",
  str_dispatch_book_chapterdes_15000_8 = "이튿날 정신을 차린 '나'는 머큐리 부인이 여관을 떠났다는 것을 깨달았다. 여관 주인의 이야기에 따르면 백야성의 비공정이 그녀를 데리러 왔다고 한다. '나'는 몹시 실망한 채 방으로 돌아왔다가 '뜻밖의 선물'을 받았다.",
  str_dispatch_book_chapterdes_15000_9 = "심사가 차일피일 미뤄지자, '나'는 초조한 나머지 백야성에 관한 소식을 수소문하다가 백야성에서 끔찍한 살인 사건이 일어났다는 소식을 듣게 되었다. 백야성에 들어선 뒤 '나'는 망설임 없이 살인 사건에 대해 조사하기 시작했다.",
  str_dispatch_book_chapterdes_15000_10 = "움브라톤에서 머큐리 부인의 부하를 우연히 만난 '나'는 그녀에 관한 소식을 물었다. 비보를 듣게 될지도 모른다는 '나'의 예상은 보기 좋게 빗나갔고, 예상과는 전혀 다른 현실을 마주해야만 했다.",
  str_dispatch_book_chapterdes_15000_11 = "《레드 머큐리》 2쇄 편집자는 후기에 움브라톤의 무기 밀수 상회, 백야성의 살인 사건과 재판에 관한 기록을 남겨 독자들에게 전해주었다.",
  str_dispatch_book_chapterdes_15000_12 = "편집자는 후기에 '머큐리 부인'에 관한 자신의 생각을 기록했다. 그는 독자들이 《레드 머큐리》의 실제 주인공을 직접 찾아갈 필요가 없다고 여겼는데, 이는 이본 여사가 글을 쓴 목적이 결코 그런 것을 원한 것이 아니기 때문이었다.",
  str_dispatch_book_chaptercont_1000_1 = "빛의 신의 계시는 오로리안에게 생명과 희망을 주시며 반드시 속히 일어날 일들을 오로리안에게 보이시려고 그의 사자를 세상의 오로리안에게 보내어 알게 하신 것이라. 오로리안 신의 길과 백야의 증거, 곧 자기가 본 것을 다 증언하였느니라. 이 노래에서 예언한 것과 기록된 것을 듣고 지키며, 모든 것을 믿고 생각하는 자는 복이 있을지어다.\n백야의 일곱 신전과 앞으로도 영원한 빛의 신과 보좌 앞의 성도, 그 성실함을 증명하는 자들은 영원한 아침과 기나긴 밤의 소용돌이 속에서도 살아남을 것이니, 가서 증거하라. 죽음에서 부활한 악마이자 고대의 자연재해인 그 천년의 죄악을 물리치고 증거할 지어다.\n백야 위의 악마가 구름을 타고 대륙에 강림하는구나. 땅 위의 모두가 목격하고 그것으로 인하여 울고, 고통받으며, 피눈물을 흘릴 것이다. 이는 많은 이가 진실을 알게 되었으므로 인함이라.\n빛의 신께서 이르시되 나는 근원이자 신비이며, 또 고대의 문명을 만들고 파괴했노라. 나는 오로리안의 신이자 오로리안의 형제요. 또한 오로리안과 함께 이 환란자의 나라에서 참고, 고통당하며 신의 길을 증명하였으며, 성도들에게 증거가 되고자 세계라 부르는 섬에 일찍부터 존재하였노라.\n그날에 뭇 사람들이 성도에게 감동되어 신의 사자가 「네가 본 것을 책으로 기록하여 라크, 살루스, 다모클, 그란디, 사르데냐, 자난, 트로이 7개 신전으로 보내라」라고 먼 곳에서 외치는 소리를 들었도다.\n빛의 신께서 하늘을 날며 성도들에게 말씀하시니, 모든 오로리안이 몸을 돌려 일곱 금촛대를 바라보니라. 촛대 사이에 오로리안 같은 이가 발에 끌리는 옷을 입고 가슴엔 금띠를 띠고, 그의 머리와 털의 희기가 흰 양털 같고 눈 같으며 그의 눈은 불꽃 같고, 그의 발은 풀무불에 단련한 빛난 구리 같고 그의 음성은 많은 물소리와 같으며, 그는 오른손에는 빛을 왼손에는 날카로운 검을 드니, 그 모습이 해가 비치는 것 같더라.\n오로리안이 이를 본 즉 그의 앞에 엎드려져 죽은 자 같이 되매 그가 오른손을 내게 얹고 이르시되 '두려워하지 말라. 나는 처음이자 마지막이니, 곧 살아 있는 자라. 내가 전에 죽었었노라 볼지어다 이제 세세토록 살아있어 사망과 음부의 열쇠를 가졌노라. 이를 네게 주리니 네가 본 것과 지금 있는 일과 장차 될 일을 기록하라'라고 하니라.\n이는 전화를 위함이니라.",
  str_dispatch_book_chaptercont_1000_2 = "계시가 내려올 때 그 사자가 첫째 인을 떼시고, 이에 내가 보니 흰 말이 있는데 그 탄 자는 궁을 가진 오로리안으로 핏빛 면류관을 받고 하늘을 날며 화살비를 뿌리더라.\n둘째 인을 떼실 때에 또 다른 붉은 말이 나오더라. 악마가 큰 칼을 말을 탄 오로리안에게 주니, 그 오로리안이 화평을 제하여 버리며 서로 죽이게 하였더라.\n셋째 인을 떼실 때에 검은 말이 나오는데 그 탄 자가 손에 저울을 가지고 이르되, 「하나의 죄악, 하나의 선행, 하나의 생명, 한 번의 심판」이라 하더라.\n넷째 인을 떼실 때 회색 말이 나오더니 그 탄 자는 죽은 오로리안이니 지옥이 그 뒤를 따르더라. 그 오로리안이 검과 흉년과 역병과 암귀로써 땅에 있는 사람들을 죽이더라.\n다섯째 인을 떼실 때 내가 보니 가진 증거로 말미암아 죽임당한 영혼들이 흰옷을 입고 있더라.\n여섯째 인을 떼실 때에 큰 지진이 나며 해는 심연처럼 검어지고 달은 온통 피같이 되었더라. 하늘의 별들이 태풍에 흔들려 설익은 열매가 떨어지는 것 같이 땅에 떨어졌고, 하늘은 두루마리가 말리는 것 같이 떠나가매 땅의 임금과 왕족들과 장군들과 부자들과 강한 자들과 모든 종과 자유인이 굴과 산들의 바위틈에 숨어들더라. 빛의 신과 악마의 큰 날이 이르렀으니 누가 능히 설 수 있으랴.\n그 후 한 오로리안이 해가 뜨는 땅에서 와 신의 인을 가지고 큰소리로 외쳐 이르되 「우리가 우리 신의 종들의 이마에 인치기까지 땅이나 바다나 나무들을 해하지 말라」하더라.\n사자가 일곱째 인을 떼실 때에 세상이 고요하더라. 사자가 또 다른 오로리안을 소환하여 일곱 나팔을 주니 그 오로리안이 나팔을 하나씩 불더라.\n첫째 나팔을 부니 우박과 불이 나와서 땅에 쏟아지매 모든 푸른 풀이 타 버렸더라.\n둘째 나팔을 부니 불붙은 큰 산이 바다에 던져지매 바다가 피가 되고, 모든 생물이 죽더라.\n셋째 나팔을 부니 횃불 같이 타는 큰 별이 하늘에서 떨어져 강과 여러 물샘을 없애더라.\n넷째 나팔을 부니 해와 달과 별이 타격을 받고 빛을 잃어 끝이 없는 밤이 찾아오더라.\n다섯째 나팔을 부니 무저갱이 열리더니 그 구멍에서 연기와 화염이 올라오고, 또 황충이 연기 가운데로부터 땅 위에 나오매 이마에 신의 인침을 받지 아니한 사람들만 해하더라.\n여섯째 나팔을 부니 한 음성이 나서 「저 결박된 과거의 영혼들을 놓아주라」 하매 마병대 삼만만이 나타나니 그 말타는 사람의 가슴에는 갑옷이 있고 자줏빛 불길이 타올라 유황 냄새를 풍기더라. 그 말들의 머리는 사자 머리 같고 그 입에는 불과 연기와 유황이 나오더라. 「살인과 복술과 음행과 도둑질을 회개하지 않는 자들을 죽여라」\n일곱째 나팔을 부니 한 오로리안이 나타나는데 그 얼굴은 해 같고 그 발은 불기둥 같으며 오른발은 바다를 밟고 왼발은 땅을 밟고 큰소리로 외치니 마치 사자가 부르짖는 것 같더라. 다 외치자 신의 사자가 일이 다 되었고, 복음을 이미 신의 종에게 내렸다 하시며\n「부하든지 가난하든지 자유인이든지 노예든지 무릇 인이 있는 자는 영원히 살 것이오. 인이 있는 자를 속이면 전화에 빠질 것이며, 인이 있는 자는 모두 이 문에 들어가 불과 검의 시험이 있으리라.」라고 하시더라\n이는 심판을 위함이니라.",
  str_dispatch_book_chaptercont_1000_3 = "땅의 전화가 계속되고 인있는 자가 문으로 들어와 신의 사자를 보니라. 그 사자가 큰소리로 외쳐 이르되, 「심판의 시간이 이르렀도다. 무릇 인 있는 자는 하늘과 땅과 바다와 물들의 근원을 만드신 이께 경배하라.」 하더라.\n멀리서 큰소리가 나더니 만민이 타락한 도시가 무너지더라.\n또다시 큰 소리가 외쳐 이르되 누구든지 짐승의 상에 경배하고 이마에나 손에 표를 받으면 인이 있거나 이 문으로 들어온다 하여도 신의 사자의 진노를 마실 것이니, 「우상을 섬긴 자여 불과 유황으로 고난을 받으리라.」 그들의 고통은 영원토록 계속되리라.\n또 소리가 있어 이르되 「기록하라. 지금 이후로 인을 받은 자는 죽어서도 복이 있도다. 네, 하고 따르는 뭇 사람은 수고를 그치고 쉬리니 이는 그들의 행한 일의 결실일 따름이라.」\n또 흰 구름이 있고 구름 위에 오로리안이 앉았는데 그 머리에는 금 면류관이 있고 그 손에는 예리한 낫을 가졌더라. 큰소리로 외쳐 이르되 「땅의 곡식과 나무의 열매가 다 익어 거둘 때가 이르렀도다」 하더라.\n그러므로 하루 동안 재앙이 땅으로 내려오매 곧 사망과 슬픔과 기근과 역병과 전쟁이니 이는 죄악이 이미 무르익었음이라.\n땅의 왕들이 그가 불타는 연기를 보고 위하여 울고 가슴을 칠 것이오. 그와 함께 사치하던 자들도 그와 함께 재앙을 받았으니 큰 도시여 연기 속에서 함께 울고 애통해하라.\n땅의 상인들이 그를 위하여 울고 애통해하는 것은 다시 그들의 상품을 사는 자가 없음이라. 그 상품은 금과 은과 보석과 비단이요. 각종 향목과 그릇이요. 향료와 연고와 유제품과 술과 밀과 보리요. 소와 양과 말과 종과 사람들이라. 이 모든 진미와 화려한 물건이 다 없어졌도다. 이러한 물건을 팔아서 부자가 된 상인은 울고 슬퍼하며 「이러한 부는 사라지고 황무지만이 우리의 재산이 되었구나」라고 하니라.\n땅 위의 고금을 타는 자와 풍류를 하는 자와 퉁소 부는 자와 춤을 추는 자들이 소리가 결코 다시는 들리지도 보이지도 아니하니, 마치 다시 네 안에서 들리지 아니하고 마치 보이지 않고, 들리지 않고, 지혜를 잃은 미련한 자 같이 되었도다. 불빛은 빛을 잃고 기쁨은 웃음을 잃으며, 횡행하던 사술은 미혹함을 잃어버리고 공허만 남으니라.\n또 인있는 자가 하늘에서부터 이르되 「구원과 영광과 능력이 우리 빛의 신께 있도다. 그의 심판은 의로우시도다. 억울함을 씻으시고 심판하시는 의로우신 자라. 그 문으로 들어가 우리의 신께 영원무궁토록 찬양할지어다.」\n이는 영원을 위함이니라.",
  str_dispatch_book_chaptercont_1000_4 = "땅의 연기, 악한 자, 죄악은 이 문으로 들어갈 수 없느니라. 그 문에서 소리가 있어 이르되 「세상의 나라는 신의 나라가 되리니 세세무궁토록 영원하리라.」하니라\n무릇 인있는 자는 사자의 「주인되시는 빛의 신을 찬송하라」는 음성을 들을 것이오.\n그러니 인있는 자여, 즐거워하여 그 영광을 모든 사람에게 돌릴지어다. 빛나고 흰옷을 입음은 모든 사람의 의로운 행함을 뜻함이라.\n사자가 이르되 「기록하라 인을 이마에 받은 자들은 복이 있도다. 이것은 신의 참되신 말씀이라」 이라 하더라.\n뭇사람들이 사자의 발에 엎드려 경배하려 하니 사자가 말하기를 「나는 너희와 같이 된 종이니 삼가 그리하지 말고 오직 신께 경배하라. 빛의 신의 증언은 예언의 영이라」 하더라.\n「한 오로리안이 무저갱의 열쇠와 큰 쇠사슬을 그의 손에 가지고 하늘로부터 내려와 악마를 잡아 결박하여 무저갱에 던져 넣고 잠그고 열쇠로 봉인하여 다시는 백성을 미혹하지 못하게 하였는데 인이 사라진 후에 잠시 동안 풀어주어 세상에 돌아오리라.」\n사자가 또 권세를 휘둘러 빛의 신을 증거하며, 억울하게 목 베임 당한 자들의 영혼과 또 짐승에게 경배하지 아니하고 그들의 이마와 손에 그의 표를 받지 아니한 자들이 살아서 함께 기쁨을 누리리니 이는 첫 번째 부활이라. 그 나머지 죽은 자들은 그 천 년이 차기까지 살지 못하더라.\n첫째 부활에 참여하는 자들은 복이 있고 순결하며 즐거워할지어다. 둘째 사망이 그들에게 미치지 못할 것이며, 신과 사자의 제사장이 되어 천 년 동안 누릴 것이니라.\n그 때에 악마가 무저갱에서 풀려나 땅의 사방 백성을 미혹하고 모아 싸움을 붙이리니 그 수가 바다의 모래 같으리라. 그들이 지면에 널리 퍼져 인이 있는 자들의 진과 사랑하시는 성을 두르매 빛의 신이 하늘에서 불이 내려와 그들을 태워버릴 것이라. 또 그들을 미혹하는 마귀가 불과 유황 못에 던져지니 그곳은 짐승이 있는 곳으로 세세토록 밤낮 괴로움을 받으리라.\n또 보니 죽은 자들이 큰 자나 작은 자나 그 흰 보좌 앞에 서 있는데 책들이 펴있고 죽은 자들이 자기의 행위에 따라 책들에 기록된 대로 심판을 받으니 바다가 그 가운데에서 죽은 자들을 내주고 또 사망과 음부도 그 가운데에서 죽은 자들을 내주매 각 사람이 자기의 행위대로 심판을 받고 바다, 땅, 사망과 음부도 불못에 던져지니 이것은 둘째 사망이라.\n또 새 하늘과 새 땅을 보니 이전의 하늘과 땅은 이미 지나갔음이러라. 새 성이 빛의 신께로부터 하늘에서 내려오니 이미 예비하신 것이라. 큰 목소리가 이르되 「보라, 신의 장막이 사람들과 함께 있으매 신계서 그들과 함께 계시리니 그들은 신의 백성이 되고 신께선 친히 그들과 함께 계셔서 사람의 신이 되리라.」\n「모든 눈물을 그 눈에서 닦아 주시니 다시는 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라.」\n「보라. 모든 것이 새롭게 되었도다. 이 말은 신실하고 참되니 기록하라.」\n「이루었도다. 나는 처음이자 마지막이라. 이긴 자는 모든 것을 기업으로 받거니와 성에는 신의 영광이 있어 그 성의 빛이 지극히 귀한 보석 같고 벽옥과 수정같이 맑더라. 낮에 성문들을 도무지 닫지 아니하리니 거기에는 밤이 없음이라. 무릇 부정하고 가증한 일 또는 거짓말하는 자는 결코 그 성으로 들어가지 못하리라」\n「성안 거리에는 수정 같이 맑은 생명수의 강이 있어 마치 수정과 같이 밝게 빛나고 강 좌우에는 나무가 있어 만민을 치료하여 다시는 저주가 없도다」라고 하시니라.\n또 사자가 말하되 「이 책의 예언의 말씀을 인봉하지 말라. 때가 가까우니라.」\n이는 계시를 위함이니라.",
  str_dispatch_book_chaptercont_2000_1 = "지금으로부터 천 년도 더 전, 떠돌아다니던 아인족은 아스트라 대륙에서 이 동굴을 발견했다. 당시에는 단순히 쉴 수 있는 공간으로 여겼지, 미래에 아인족의 번영을 재현할 위대한 부락이 될 거라고는 생각하지 못했다.\n그 뒤 수십 년 동안, 끊임없이 동굴의 탐색이 이어지면서 아인족은 이곳에서 대량의 옛 문명의 설비와 기술의 잔재를 찾게 되었다. 여러 곳의 흔적으로 보아 옛 문명의 인류는 이 거대한 동굴에서 일종의 특수 실험을 진행했던 것으로 보였다. 또한 동굴 안에서 사는 아인족이 밖에서 떠돌아다니는 아인족보다 더 건강한 신체와 더 강한 루미나에 대한 민감도를 가진다는 사실을 발견하게 되었다. 기묘한 것은 이러한 변화는 아인족에게만 있었으며, 소문을 듣고 찾아온 오로리안과 아이테르에게는 그저 이곳이 독특한 생태계와 봄 같은 사계절을 가진 쾌적한 거주지라고 느껴질 뿐이었다. 이러한 특징 때문에 아인족은 동굴을 하늘이 내려주신 낙원, 즉 약속의 땅으로 여기게 되었고, 그들은 이 거대한 동굴 도시에 비경이란 이름을 붙였다.\n10세대 이상을 거친 노력으로, 낡은 고대 시설만이 존재했던 동굴은 크게 번영하여 아인족의 집결지, 정치의 중심지이자, 정신적 고향으로 거듭났다. 아인족은 이곳에서 과학 연구, 공업과 농업 생산에 적극적으로 나서면서 지난날의 영광 회복하기 위해 힘썼다. 수백 년 후 암귀가 닥쳐오기 전까지...",
  str_dispatch_book_chaptercont_2000_2 = "환기 시스템은 거의 멈췄고, 조명 시스템도 파괴되었다. 동굴 속 화약 연기는 쉽사리 걷히질 않았지만, 그것만으로 짙은 피비린내를 덮을 순 없었다. 저 빌어먹을 괴물들은 연기와 어둠 속에서 몸을 꿈틀거리며 아무런 힘도 없는 평민들을 무참히 학살했다. 저놈들은 우리의 동료를 하나씩 쫓아가 일말의 망설임도 없이 죽여버렸다. 그야말로 인간성 따윈 하나도 남아있지 않은 광기 어린 짐승 그 자체였다.\n누군가는 이에 저항하여 몇몇 암귀의 손에서 어린아이를 구출해냈지만, 그 두 사람은 도망칠 새도 없이 뒤에서 몰려오는 무수한 암귀 속에 파묻혀버렸다. 전선에서 방어하던 병사들과는 이미 몇 시간 전에 연락이 끊겼으니... 아무래도 절망적인 상황인 것 같다. 우리의 유일한 희망은... 저 지하 루트를 통해서 탈출하는 사람들이다... 단지... 우리의 아이들이 이곳을 탈출할 수 있길 바랄 뿐이다. 건물 파편에 짓눌려 울부짖는 동료와, 그들의 영민하던 눈동자는 빛을 잃고 이어서 쓰레기처럼 쌓여 작은 산을 이루던 장면을 난 영원히 잊지 못할 것이다.\n예전에 번영하던 낙원은... 모든 것이 집어 삼켜져 울음과 화염이 가득한 지옥으로 변했다. 여기를 지옥으로 만든 악마들... 이 모든 죄의 대가를... 암귀는 반드시 치르게 될 것이다!\n──일루미나 탐색대가 비경 깊은 곳을 탐색하던 도중 찾은 한 노트.",
  str_dispatch_book_chaptercont_2000_3 = "장로들의 말에 따르면 우리가 동굴에 들어간 마지막 아인족이 될 것이라고 했다. 말은 장로라고 하지만 그들도 젊은 아인족 무리에 불과하다. 연장자는 암귀가 침입했을 때 일찌감치 전사했으니까.\n일족의 구원 요청 편지를 받았을 때부터 마음의 준비를 하긴 했지만, 예전의 그 커다란 동굴이 암석이 뒤덮여 폐허가 된 모습과 산처럼 쌓여있는 일족의 시체, 그 종말과도 같은 광경을 본 충격을 감당할 수가 없었다. 다행히 장로들이 적절한 시기에 우리를 위로해 주었다. 뭐, 그들은 우리보다 작아 보이긴 하지만...\n암귀! 반드시 대가를 치르게 하겠어! 죽은 아인족 한 명당 암귀 100마리를 묻어버려야 해. 모든 아인족이 일족의 비참한 죽음을 잊지 못하지만, 동굴도 잃고 고향도 잃은 아인족에게 대체 남은 건 뭘까? 대륙에 또 다른 거주지가 있는 것도 아니잖아? 차라리 비경의 일족들처럼, 전사가 죽으면 민간인이 싸우고, 성인이 죽으면 아이들이 싸웠던 것처럼 마지막 순간까지 싸우는 게 나았을지도 몰라. 이제 비경 동굴에 남은 일족들이 희생되었으니 이젠 고향으로 향하는 우리 차례겠지. 그렇다면 적의 피로 우리의 수의로 삼고, 암귀의 시체를 우리의 무덤으로 삼겠어! 마지막 순간까지 고향을 지키자.\n──어떤 아인족과 오로리안 혼혈 후손의 일기",
  str_dispatch_book_chaptercont_2000_4 = "이미 말라버린 저 해골, 저 용감했던 일루미나 병사가 죽기 직전까지도 무기를 놓지 않았다는 생각에 당시 나는 이번 탐색을 포기하려고 했었다.\n아인족이 멸망한 지도 벌써 백여 년이란 시간이 지났다. 암귀는 이미 비경 동굴의 주인이 되었고 우리 같은 「이방인」조차도 아인족의 고향이었던 곳을 「비경」 또는 「대비경」으로 바꿔부르게 되었다. 아인족을 멸망시킨 후 암귀는 비경에 사는 것이 만족스러운지 다른 도시를 습격할 생각이 없는 것 같았다. 지금 그놈들이 무엇을 하고 있는지 아는 사람은 아무도 없다.\n그래서 우리의 차례가 되었다.\n처음에는 일루미나 탐색대 모두 대단한 멤버로 이루어졌었고 모두 일루미나 연방의 안전을 위하여 진심으로 비경 안의 암귀들을 쓸어버리려고 했다. 하지만 곧 현실이 모든 오로리안을 일깨워주었다. 수많은 탐색 대원들이 암귀에게 죽거나 비경에서 실종되었다. 심지어 탐색대 전체가 행방불명이 되기도 했다! 이로 인해 반대의 목소리가 점점 커졌지만 일루미나의 수장은 「진실 규명」이라는 그 몇 글자를 위해서 억지로 탐색대를 만들고 계속해서 비경을 탐색하도록 강행했다. 진실 규명이라는 글자 뒤로 수많은 생명이 사라졌고, 많은 가족의 슬픔을 낳았다.\n마침내 탈영병이 나타났고, 우리는 그중 하나였다. 우리는 죽은 동료들을 버리고 상관의 명령을 무시하고 그 비경에서 벗어났다. 분명히 일루미나 연방의 외부 공개 기록에는 「실종」이라고 되어있고, 내부 기록에는 「탈영」이라고 되어 있겠지. 우리 가족들은 어찌 되었을까? 어떤 처벌이라도 받았을까? 알수가 없다. 우린 영원히 일루미나 연방으로 돌아가지 못할 테니 이 넓은 사막에서 여생을 보낼 수밖에.\n가끔 고향과 가족이 그리울 때도 있지만 생존의 갈망에 비하면 아무것도 아니었다. 어쨌든 우린 살아있으니 이 넓은 사막을 돌아다닐 수 있다. 때로는 포기하는 것도 미덕이라고 생각한다. 만약 우리가 그 당시의 아인족처럼 고향을 그리워했다면 우리에게 남은 결말은 단 두 가지였을 것이다. 비경을 탐색하다가 암귀에게 죽거나, 명령을 어기고 귀환하여 군법대로 처벌을 받거나. 아무튼 둘 다 죽는 건 마찬가지다.\n최근에 일루미나 연방에서 비경을 탐사한다는 소식이 없는 걸 보면 포기를 한 것 같다. 게다가 다른 도시도 별다른 움직임이 없다. 아무래도 대륙에서 비경은 이미 잃어버린 땅이니 암묵적으로 암귀의 점거를 용인한 것이겠지. 이 모든 것은 이제 우리와 아무런 상관이 없다. 비경, 일루미나, 아인족, 암귀, 모두 안녕.\n──익명을 요구한 레디젤 렌치 초대 멤버의 말을 정리하여 기록함.",
  str_dispatch_book_chaptercont_3000_1 = "이번 우리 임무는 □□□□에 가서 그곳에 숨어 있는 반역자들을 모두 섬멸하는 것이다. 돈은 많이 주기로 했으니 이걸로 좀 많이 모이길. 장비와 식량을 쓰는 건 생각만 해도 골치가 아프지만, 돈을 벌지 않으면 나만의 용병대는 영원히 만들 수 없다. 그럼 지금처럼 다른 팀과 부대끼며 살아갈 수밖에 없으니 반드시 돈을 모아야 한다. 용병대 이름은 아직 생각하지 않았지만 급하진 않으니까 괜찮다.\n□□□□의 지형은 너무 복잡해서 임무에서 지시하는 대로 다른 팀의 용병을 따라 지하도로 잠입해야 한다. 하지만 통로 상황은 알 수 없고, 몰래 잠입하는 것이기 때문에 섬광탄을 사용할 수도 없다. 잠입하기 전에는 통로에 무슨 매복이나 함정이 있을까 봐 걱정을 좀 했었다. 다행히 마지막까지 무사했다. 그때, 도마뱀 한 마리가 내 발밑을 스쳐 지나갔다.\n통로를 뚫고 나오자 □□□□의 중심이었다. 우리는 인적이 없는 황량한 오솔길을 걸어 그들의 은신처 뒤를 포위해나갔다. 우리 쪽에서 보는 은신처는 정말 난장판이었다. 하지만 그건 전투 때문이 아니라, 청소할 시간이 부족했거나 청소할 생각이 없었기 때문인 것 같았다. 구석구석에 버려진 쓰레기, 헌 옷, 먹다 남은 음식들까지 널려있었다. 그들은 아무런 방비도 하지 않는 것 같았다.\n계획대로 우리는 수월하게 그들을 모두 처리했다. 하지만 탄약을 너무 많이 쓴 것 같았다. 당시에 우리는 5, 6개의 폭약 포대를 던져 넣었으니 말이다. 그건 우리가 직접 배합해서 만든 폭약이어서 아껴 써야 했는데. 하지만 팀원들은 이번 보수가 정말로 높다며 임무가 잘 마무리되면 받은 돈으로 진짜 군에서 사용하는 것 같은 좋은 폭약을 사자고 했다. 사실 나는 돈을 더 받았으면 했다. 내가 보기에 그들은 너무 낙천적인 것 같았다.\n참, 우리 소대 이름은 폭약 소대로 정했다. 폭약처럼 세상을 크게 놀라게 만들 거야. 그것도 아주 크게. 쾅!",
  str_dispatch_book_chaptercont_3000_2 = "지난번에 받은 보수는 예상보다도 훨씬, 엄청, 매우 적었다. 하지만 어쩔 수 없었다. 우리에게 보수를 주던 중 고용주는 갑자기 들이닥친 암귀에 잡아 먹혀버렸다. 우린 숨어있다가 암귀가 떠난 후 고용주의 남은 몸 반쪽과 그 주변을 뒤져 아주 조금의 돈을 찾아낼 수 있었다. 이미 죽은 고용주에게 돈을 더 뜯어낼 수는 없는 노릇이었다.\n우린 이번에는 어떤 임무를 받을지 논의를 했다. 의외였다. 우리에게 선택의 여지가 있을 줄이야. 총 두 개의 임무 중 하나를 골라야 했다. 하나는 □□□의 의뢰로 □□의 멤버를 암살하는 것이었고, 또 다른 하나는 □□의 의뢰로 □□□의 멤버를 암살하는 것이었다. 그렇다. 웃기게도 □□□와 □□ 모두 약속이나 한 듯이 우릴 찾았던 것이었다. 그래서 이제 우리는 □□□를 처리할지 아니면 □□를 처리할지 결정해야 했다.\n난 □□□를 위해 □□를 처리하고 싶다. 난 □□이 싫다. 입으론 평등과 규율을 외치지만 그들은 평등, 공평, 규율이란 이름으로 다른 사람의 목숨을 이용할 줄만 안다. 정말로 자신들이 평등하고 공평하다면 왜 우리는 지하로 대피할 수 없었던 거지? 또 그들의 자원은 어디서 온 것이기에 왜 우리에게 나눠줄 수 없었던 거지? 그리고 그들의 대장이 정말로 평등, 공평, 규율을 중요시한다면 왜 일반 병사들과 같은 옷과 무기를 쓰지 않고, 같은 집에 살지 않는 거지?\n하지만 다른 동료는 □□□를 대신해서 □□를 처리하는 건 너무 어렵지 않겠냐고 말했다. 아무래도 □□의 방비는 매우 철저하니까. 그렇다고 □□를 위해서 □□□를 해치우는 건 과연 쉬울까? □□□도 □□□ 같은 곳에 있잖아!\n됐다. 어떤 임무라도 상관없지 않겠는가. 돈만 주면 우리는 목숨을 건다. 그런 거 아니겠는가? 나만의 팀을 꾸리기 위해서 무엇이든 다 할 것이다. 하지만 가능하다면 그 평등, 공평, 규율을 내세워 위선적으로 행동하는 □□를 위해 목숨을 걸고 싶진 않다.",
  str_dispatch_book_chaptercont_3000_3 = "□□□를 대신해서 □□의 멤버를 처리하는 것도, □□를 대신해서 □□□의 멤버를 처리하는 것도 우리는 할 수 없었다. 토론 끝에, □□□도 □□도 모두 수비가 매우 탄탄해서 들어가려면 최소한 공성 망치나 슈퍼 투석기 정도는 있어야 한다는 결론이 나왔다. 우리처럼 찢어지게 가난한 용병은 탄약을 구할 길이 없고 결국 검에 의지해야 하므로, 이런 어려운 임무는 아예 무리였다. 눈앞에서 돈이 줄줄 새는 걸 보는 건 정말이지 너무나도 괴로운 일이다.\n큰 임무 두 가지를 포기했기 때문에 우리의 자금에 문제가 생겼다. 입에 풀칠하기도 바쁜데 나만의 용병대를 꾸리는 건 말도 안 되는 일이었다. 다행히 간단한 일거리가 생겼다. 밥과 숙소가 제공되는 일이라 당분간 먹고 자는 문제는 걱정할 일이 없을 것 같다. 하지만 팀원들은 방과 마당 청소하는 걸 곤란해하며 좋아하지 않았다. 하지만, 하지만 말이야. 난 용병으로 누군가를 죽이러 다니는 것보다 이게 더 나은 것 같은데? 난 용병으로서 실격인가?\n방 청소를 했을 때, 방 주인은 없었다. 하지만 부드러운 침대에 핑크색 이불, 그리고 침대에 곰돌이 인형이 있는 걸 보니 귀여운 여자아이의 방일 거로 생각했다. 그 곰돌이 귀는 한쪽이 찢어져 있었는데 청소를 마치고 할 일이 없어서 귀를 꿰매주었다. 그땐 내가 더더욱 용병 같지 않다고 생각했다. 바느질까지 이렇게 능숙하다니.\n용병으로서 때리고 죽이는 일을 하다 보면 금세 옷이 망가지기 일쑤였다. 하지만 새 옷을 살 수 없다 보니 나와 팀원들은 각자의 옷을 매번 직접 기워입어 온 것이었다. 그러다 보니 모두 바느질에 능숙해진 거다. 아, 만약에 용병을 하지 않았다면 바느질 소대 같은 것이 될 수도 있을 것 같다. 혹시 모르지. 용병보다도 돈도 더 많이 벌고 안전할지도.",
  str_dispatch_book_chaptercont_3000_4 = "용병을 그만둔 후로 꽤 오랫동안 쓰지 않았네. 다시 펼쳐보니까 정말 그립다.\n하지만 난 용병을 그만둬서 정말로 기쁘다. 역시 내게 싸움은 어울리지 않았다. 그 어려운 임무를 완수할 수도, 충분한 탄약을 모을 수도 없었다. 모두와 함께 나만의 용병 소대를 만들고 싶었지만, 항상 돈이 충분하지 못했다. 그러다 보니 결국은 □□□□□ 방 청소로 돈을 벌었다. 생각해보니 진짜 쪽팔리네.\n용병의 신분으로 방 청소하는 건 창피했지만 한참을 일해보니 이렇게 먹고 자는 생활이 좋은 거라는 걸 깨달았다. 그러면서 곰 인형도 꿰매봤는데 결국 □□□□□가 내가 정말 바느질을 잘한다는 걸 알게 되었다. 나는 자랑스럽게 □□□□□에게 우리가 옷을 꿰매는 일에도 엄청 능숙하다는 걸 알려줬다. 그때 난 용병으로 어떤 어려운 임무를 완성한 것보다도 더 자랑스러워 가슴이 벅찼다.\n정말 그 누가 상상이나 했을까? 결국 우리의 바느질 솜씨를 맘에 들어 한 □□□□□가 재봉점을 열어주었다. 지금 우리는 떠돌이 용병이 아니라 □□□□□ 최고의 재봉점 일원이다. 가게 이름도 우렁차게 폭약 재봉점이라고 지었다. 원래 우리 용병 소대에게 주려던 이름이지만 재봉점에 쓰는 것도 꽤 좋은 것 같다.\n그리고 우리 폭약 재봉점은 장사가 정말 잘 된다. □□□과 □□의 사람 모두 우리에게 와서 옷을 꿰맨다. 난 □□를 여전히 싫어해서 옷을 여밀 때 고생 좀 해보라는 속셈으로 일부러 단추를 아주아주 빡빡하게 만들었다. 그런데 생각지도 못하게 □□의 사람들이 이렇게 팽팽한 단추를 좋아하는게 아닌가. 이러면 병사들의 뱃살을 조일 수 있다나? 전에도 말했지만 □□는 평등, 공평, 규율이니 뭐니를 표방한다면서 결국 병사의 배는 그렇게 살이 쪘구나. 뭔가 계략을 쓴 게 아니라면 어떻게 배가 그렇게 나올 수 있겠어?\n아무튼 재봉점에서 바느질하는 삶은 용병을 하는 것보다 훨씬 나았다. 우린 모두 그렇게 생각한다. 한 녀석은 돈을 모아서 장가갈 준비를 했고, 나도 가정을 꾸릴까 고민하고 있다. 그리고 우린 우리만의 군복 브랜드도 개발할 생각이다. 이름은 당연히 폭약 군복. 언젠가 □□□와 □□ 모두에게 우리 군복을 입혀야지.\n여기까지 써야겠어. 시간이 나면 또 기록하러 와야지. 근데 재봉점이 정말로 너무 바빠. 하하, 바쁠수록 좋아. 바쁠수록 돈을 벌잖아!",
  str_dispatch_book_chaptercont_4000_1 = "글:\n그녀는 진리는 눈으로 볼 수 없다고 말한다. 하지만 진리는 눈을 가지고 있어 날 볼 수 있다. 진리가 날 볼 때 나는 진리의 부름을 듣고 진리가 있는 곳을 알게 된다.\n아니, 난 그녀의 진리를 거절한다. 그녀는 악의 화신, 그녀의 웃는 모습은 암귀보다도 소름 끼친다. 그녀의 미모는 세상에서 가장 무서운 죄악이다.\n그녀는 내가 진리를 거부할 수 없기 때문에 그녀를 거절할 수 없다고 말한다. 그녀가 몸을 돌리자 붉은 치마가 그녀와 함께 춤을 추었다. 그 치마는 매우 특별해서 마치 물처럼 흐른다. 그녀가 몸을 돌리자 붉은 치마가 그녀와 함께 돌며 그녀와 나를 에워쌌다.\n아니, 난 그녀의 진리를 거절하고 또 한 번 거절했다. 붉은 치마는 살아있는 것처럼 스스로 움직여 땅에 떨어지고 피부에 달라붙는다. 그녀가 원을 그리며 돌자 치마가 눈처럼 흩어져 한 조각, 한 조각 내 몸에, 내 입술 끝에 떨어졌다. 나는 내 몸에 흐르고 있는 피와 같은 이상한 냄새를 맡았다.\n그녀는 이것은 자신의 환대이니 잘 맛보라고 말했다. 그녀의 속눈썹은 길고, 그녀의 목소리는 천상의 소리와 같다. 그녀가 나를 본다.\n아니, 나는 그녀의 진리를 또 한 번, 또 한 번 거절했다. 그녀의 몸에서 솟구쳐 나온 피는 셔츠가 되었고, 치마가 되었고, 로브와 카펫이 되었고, 붉은 왕관이 되었다.\n그녀는 아직도 나를 보고 있다. 그녀의 모든 눈이 나를 보고 있다. 그녀의 몸에 있는 눈이 나를 보고 있다. 그녀의 손에 있는 눈이 나를 보고 있다. 그녀의 가슴에 있는 눈이 나를 보고 있다. 그녀의 무릎에 있는 눈이 나를 보고 있다. 그녀의 뒤에 있는 눈이 나를 보고 있다. 그녀의 머리 위에 있는 눈이 나를 보고 있다. 그녀의 등 뒤에 있는 눈이 나를 보고 있다.\n그녀가 나를 보고 있다. 난 그녀에게 보인다. 난 그녀에게, 진리에게 주시되고 있다.\n아니, 난 그녀의 진리를 또 한 번, 또 한 번, 또 한 번 거절했다. 그러나 나의 거절은 무의미하다. 그녀는 모든 눈으로 나를 보았다. 나의 몸에서 나온 눈이 나를 본다. 내 손에서 나온 눈이 나를 본다. 내 등에서 나온 눈이 나를 본다. 내 머리 위에서 나온 눈이 나를 본다. 진리의 눈이 내 몸에서 생겨났고, 그 후로 언제나 어디에 있든지 진리는 나를 본다.\n진리가 나의 몸에서 나와, 내 몸에서 나를 본다.\n그녀는 그렇게 말했다.",
  str_dispatch_book_chaptercont_4000_2 = "진리는 어디에나 있다. 흐르는 강물 속에, 푸른 풀밭에, 어두운 하늘에, 끝없는 기나긴 밤에.\n나무의 어린 가지에, 꽃과 과일의 씨앗에, 질퍽거리는 오솔길에, 말라버린 폭포수 옆에.\n공기 중에, 눈앞에, 피부 주위에, 발밑에. 숨을 따라 폐 안으로, 빛을 따라 망막에, 걸어가면 뒤에 남아 몸을 스친다.\n입가에, 교두에, 입안에, 목구멍에, 위에, 위액에 소화되어 점막에 흡수되고 혈액에 녹아든다.\n신경을 따라 몸의 구석구석까지. 간까지 전달된다. 담낭까지 전달된다. 소장, 대장, 췌장, 비장, 신장까지 전달된다. 대퇴골, 경골, 복사뼈, 발가락까지 전달된다.\n책상다리 모서리에 발을 부딪친 고통처럼\n신경을 따라 몸의 중앙까지 전달된다. 심장까지 전달되고, 기관지까지 전달되고, 혀뿌리 아래, 비강, 눈 밑, 뇌간, 천정까지 전달된다. 두개골, 경추, 견갑, 팔꿈치, 손목, 손가락 끝까지 전달된다.\n손톱이 다 벗겨진 듯한 고통처럼\n신경을 따라 몸의 가장 깊은 곳까지 전달된다. 골수까지 전달된다. 탯줄까지 전달된다. 복강의 어둠 속까지 전달된다. 아직 세상에 나지 않은 아기의 정수리 안까지 전달된다. 새싹이 아기의 머릿속에서 자라고, 아기 생각의 자양분이 되어 아름다운 꽃을 피운다. 꽃잎마다 거룩한 색이 뚝뚝 떨어진다.\n거룩한 생각은 폭발하여 여러 갈래로 갈기갈기 찢긴다. 거룩함을 입고 세상에 나온 아기가 찾아온 곳은 끝없는 황야다. 아기가 우니 황야의 모든 땅에 꽃봉오리가 생기고, 아기의 눈물에 황야의 모든 땅이 붉게 물들고, 모든 꽃봉오리가 아기의 거룩함으로 물든다. 아기는 계속해서 울고, 하늘에서도 거룩한 비가 내리기 시작한다. 꽃봉오리는 아기 곁에서 점차 피어나고, 황야는 거룩한 꽃밭이 된다.\n진리는 어디에나 있다.",
  str_dispatch_book_chaptercont_4000_3 = "이 느낌을 어떻게 표현해야 할까.\n끈적한 진흙이 한데 뒤섞여 있다. 손을 넣어 만지면 매끄럽고, 점액질이 가득하고, 또 그 속에 섞여 있는 덩어리로 된 물질도 만져진다. 쥐어도 되고, 주물러도 되고, 휘저어도 된다. 그것과 하나가 될 순 없지만, 그것에 꽉 잡혀 그것의 온도가 손을 따라 어깨까지 올라간다.\n그것은 생물이다.\n육질이 신선하고, 영양은 풍부하여, 여러 가지 방법으로 요리할 수 있다. 부치고, 볶고, 찌고, 튀기고 모든 것이 가능하다. 굽는 것도 좋고, 수프를 만들면 최고다. 사 왔을 때 소개 글에는 이렇게 쓰여 있다. 살아있을 때 솥에 넣으면 가장 맛있다.\n하지만 어떻게 잘라야 할까. 칼로 자를 때마다 끈적끈적하고 매끄러운 몸이 절묘하게 피한다. 칼날에 점액질이 달라붙어 미끄럽다. 그것을 누르고, 안에 있는 덩어리로 된 물질을 겨냥하여 자른다. 표면을 감싸고 있는 점액이 마치 부드러운 큰 입처럼 칼날을 감싸 자르지 못하게 한다.\n물을 끓였다. 시간이 없다. 통째로 넣어버리자. 냄비를 타고 끓는 물 속으로 미끄러져 들어갈 때, 마치 착각인 듯 그것이 웃는 것 같다. 그것의 치아는 들쭉날쭉하고 몸을 비비 꼬더니 점액과 끓는 물이 순식간에 하나가 되었다.\n그것은 소리를 냈다. 정말로 웃고 있다. 그것은 끓는 물 속에서 소리 내 웃었고, 끓는 물 속에서 나를 보며 크게 웃었다. 비웃는다. 독이 든 증기가 수면에서 올라오기 시작했다. 안개마저도 끈끈한 느낌이다. 끓어오르는 기운을 머금고 증기의 냄새가 방에 가득하다. 악취와 비린내가 콧속을 파고들어 뇌 속에서 터진다. 꿈틀거리는 냄새가 두개골을 긁는 것이 마치 손톱으로 유리를 긁는 것 같다.\n할퀴면서 폭소를 터트린다. 그것이 뭔가를 말하기도 했다. 날 먹어라. 한 입, 한 입 먹어버려라. 내 맛을 음미해라. 내 끈적이고 매끄러운 감촉을 맛보고, 내가 입안에서 폭발하는 느낌을 맛보아라. 나의 맛이 네 목구멍을 타고 위까지 흘러가게 하자. 나의 맛이 네 몸에 퍼지게 하자. 우리가 하나의 맛으로, 우리가 같은 일로, 우리가 같은 존재가 되자.\n진리를 맛보면 진리가 된다.\n그리고 많은 사람을 맛보게 해서 더 많은 사람이 진리의 맛을 알게 하자.",
  str_dispatch_book_chaptercont_4000_4 = "강림의 그 날은 오지 않을 것이다. 그러니 안심하고 편하게 놀 수 있다. 안심하고 그녀와 함께 행복을 즐긴다.\n웃자. 활짝 웃자. 사랑하는 사람을 본다. 그녀의 영원히 사라지지 않는 웃는 얼굴을 본다. 그녀와 껴안고, 그녀와 빙글빙글 돌고, 그녀와 밤낮으로, 매분 매초 함께하며, 그녀와 함께 사탕을 맛보고, 함께 햇살 아래 달리고, 함께 일몰을 본다. 그녀와 미래를 자유롭게 상상하고, 그녀와 미래 아이의 이름을 생각해본다.\n울자. 후련하게 울자. 빗속에서 모든 눈물을 쏟아내고, 천둥과 번개 속에서 마음을 쏟아낸다. 그날은 영원히 오지 않을 것이기 때문에 눈물과 비조차도 아름답다. 그녀의 웃음꽃은 다시 피어날 것이다. 비가 내리면 바다로 흘러가고, 바람을 타고 하늘로 돌아가 다시 떨어진다. 이는 영원히 멈추지 않는다.\n강림의 그 날은 오지 않을 것이다.\n마음껏 달려라. 쫓아가라. 마음껏 즐거워하며 큰소리로 노래를 불러라. 말을 타고, 그녀를 품에 안고, 지평선 너머를 향해 채찍을 들고 말발굽 소리를 좀 더 빠르게, 더 빠르게. 아무도 기다리지 않고, 목표물도 쫓지 않고, 그저 마음껏 달리고 질주해서 바람이 얼굴에 스치는 느낌을 즐기자. 온 마음을 다해 세상 저편으로 달려가자. 멈출 걱정도 없고, 길을 돌아갈 걱정도 없고, 내일의 태양이 정말로 떠오를까 하는 걱정도 없다. 반드시 해가 뜨고, 둘째 날은 반드시 오기 때문이다.\n강림의 그 날은 오지 않을 것이다.\n비록 어두운 밤일지라도 달은 부드러운 빛을 발하며, 그녀의 두 눈을 밝게 비춘다. 그 눈동자는 별빛보다 더 밝게 빛난다. 함께 밤을 보며, 함께 별을 세고, 함께 달이 초승달에서 보름달이 되는 것을 본다. 일분일초마다 빛으로 목욕하고, 밤마다 별과 달 사이를 돌아다닐 수 있다. 그녀의 웃음은 초승달 같고, 그녀의 눈은 별 같고, 그녀의 긴 머리카락은 긴 밤의 폭포 같고, 그녀의 목소리는 밤 꾀꼬리보다 아름답다. 그녀는 당신 곁에 있고, 영원히 당신 곁에 있는다.\n왜냐하면 그날은 오지 않을 테니까. 강림의 그 날은 절대로 오지 않을 것이다.\n그녀는 웃었다. 그녀의 웃음은 여전히 아름답고 그녀의 눈은 여전히 별과 같다.\n난 올 필요가 없어. 난 항상 네 곁에 있으니까. 그녀가 말했다.",
  str_dispatch_book_chaptercont_5000_1 = "좋아, 오늘은 샌드버그를 손질하고 요리하는 방법을 알려줄게. 이 녀석들은 레디젤 사막 어디서든 쉽게 잡을 수 있으니까. 하지만 맛있게 만들긴 쉽지 않아! 일단 20cm 이상의 샌드버그 몇 마리를 골라. 너무 작은 것들은 다시 모래나 먹으라고 던져버리고. 먼저 몸통의 가운데를 잘 잡은 다음에 손으로 머리와 머리에 있는 모래주머니를 함께 뽑아버려. 원한다면 칼이나 가위를 써도 괜찮아. 그리곤 아무 막대기나 집어서 머리를 뽑은 곳에 집어넣어. 없으면 손가락을 넣어도 돼. 그럼 안에 숨어 있던 진흙과 모래가 밀려 나올 텐데 샌드버그 본연의 맛을 느끼고 싶다면 이 단계는 생략해도 좋아.\n이렇게 하면 기본적인 샌드버그 손질은 끝이야. 말린 샌드버그를 처리하는 것도 방법은 동일해! 만약 당장 꼼짝도 못 할 정도로 배가 고프다면 이대로 바로 불에 구워도 돼. 다만 손가락을 꽂은 채로 불에 굽는 건 안 돼, 알겠지? 매년 바보들이 「조니 아저씨, 손가락도 같이 익어버렸는데 어떡하죠?」라고 편지를 보낸다고. 손가락이 익어버렸으면 뭘 어떡해? 익었으면 고기인 거지 뭐. 안 그래?\n만약 냄비가 있다면 이미 레디젤 사막에 사는 사람의 90%는 이긴 거야. 한마디로 어엿한 미식가라고 할 수 있지. 먼저 손질한 샌드버그를 달군 냄비에 넣고 소금을 뿌린 뒤에 노릇노릇한 향이 날 때까지 볶아. 그리고 나서 훈제 고추와 메뚜기 튀김을 넣고 순서대로 고추장 1큰술, 마늘가루 4분의 1술, 마조람 4분의 1술, 사워크림 5큰술을 순서대로 넣어. 마지막으로 물을 넣어서 20분간 끓여. 접시에 담으면서 위에다 어성초와 고수를 뿌리면 바로 조니 아저씨의 간편 샌드버그 메뚜기탕 완성이야! 이런 재료가 하나도 없다면 그냥 먹고 싶은 걸 다 때려 넣고 잘 익히면 돼!\n다음번엔 이 조니 아저씨가 낙타 통찜을 어떻게 만드는지 알려줄게. 일단 낙타를 넣을 수 있는 큰 찜통을 준비하는 것 잊지 마. 못 찾겠다고? 사막에 사람 찌는 걸 좋아하는 미친놈이 있으니까 녀석한테 가서 물어봐!",
  str_dispatch_book_chaptercont_5000_2 = "네가 아직 성인이 안 된 꼬맹이라곤 해도 이 사막에 발을 들인 이상 이 술집과의 왕래를 피할 순 없어. 이곳의 모든 사람이 다 술집의 사장과 사메야마의 친구들이라고. 그러니까 들어와선 얌전히 있어. 양아치처럼 나대지 말고. 레디젤 렌치가 뒤를 봐주지 않는다고 해도 술집에 장착된 방범 기관포만으로도 네가 오줌을 지리게 만들 수 있으니까. 내가 이 책을 쓰기 보름 전이었을 거야. 하늘 높은 줄 모르는 애송이가 술집에서 난동을 피운 거지. 어떻게 됐게? 2분도 안 지나서 벌집이 돼버렸어. 그러니까 실력이 없으면 얌전히 술이나 마셔. 입조심하고.\n그래도 이 집의 데킬라는 정말 끝내줘. 다른 곳의 데킬라는 선인장을 잘라서 용설란 이파리 몇 개 넣고 구운 걸 기름통에 채워서 묵히거든. 한 잔에 70%는 선인장이고 20%는 레디젤 클로티드(레디젤 사람들이 기름 마시길 좋아하는 게 다 이렇게 된 거지!), 10%는 모래란 말이지. 그딴 게 무슨 데킬라라고! 선인장 주스라고 하는 게 낫지. 근데 이 집은 정말 달라. 여긴 푸른 용설란초(어디서 구한 건진 모르지만)만 써. 이상한 거 안 쓴다고! 게다가 화덕에서 700도의 고온으로 천연 즙이 나올 때까지 닷새 이상을 기다렸다가 렌치나 망치로 용설란을 부순 다음에 맷돌... 그걸 맷돌이라고 부르는 게 맞겠지? 아무튼 그걸로 갈아서 오크나무통에 채워서 묵혀(오크나무가 어떻게 생겼는진 모르지만). 그걸 잔에다 따르면 황금색이나 조금 적갈색 빛이 나오는데, 북방에서 구해온 해염을 한입 물고 데킬라를 크게 한 모금 하면. 캬, 그 느낌은 마치 목구멍에서 불덩이가 터지는 거 같다고! 네가 이 술집에 온다면 숙성 데킬라를 추천할게!\n그리고 최근에 새로 칵테일을 추가한 거 같은데, 보드카에 얼음이랑 라임, 그리고 진저 비어랑 약간의 사랑을 담아 만들었다는데, 이름이, 이름이 무슨 노새라고 하던가, 아무튼 직접 와서 먹어보라고!",
  str_dispatch_book_chaptercont_5000_3 = "이 조니 아저씨도 젊었을 땐 사막을 두루 돌아다녔었지(멍청이나 할 짓이지만). 근데 누구든 머리는 한두 번 부딪혀 봤잖아? 정신을 잃었던 그때 하마터면 사막에서 죽을 뻔했어. 지나가던 여행 낙타 상단이 날 모래 속에서 꺼내주지 않았으면 난 이미 한 줌의 모래가 되었겠지. 하지만 그 덕에 세상에서 가장 맛있는 낙타 고기를 먹게 됐어. 상단장이 직접 조리한 큼직한 낙타 고기를 말이야(상단장이 나한테 자기 요리를 꼭 맛보라 하더라고. 난 굶어 죽기 직전이었으니까 절대 거절할 리 없었고). \n크고 하얀 접시 위에, 노릇노릇하게 구워져 기름이 좌르르 흐르고 있는 낙타 고기의 섬유질은 소고기보다 더 감칠맛이 났는데, 입에 들어가는 순간 사르르 녹아버리는 거야. 이로 고기를 뜯는 순간 침이 기름이랑 섞여서 흐르는데, 그 향기가 두뇌까지 몰아치더라고. 정직, 담백한 고기 본연의 맛. 다른 재료도 없었는데 다 먹고 나니 알몸으로 사막을 질주하고 싶어지더라(물론 감히 그랬다간 총알을 선물로 한 아름 받았겠지).\n낙타를 고를 땐 상단장하고 이 조니 아저씨가 같이 고른 건데, 낙타들이 하나같이 토실토실해서 어떤 놈을 고를지 정말 어려웠지. 털이 빛나는 놈이 가장 많이 먹어대니까 그놈을 잡자. 다리가 긴 저놈은 다리가 길어서 그런가 자꾸 다리를 저네. 죽을 병이군. 잡자. 아이고 이 녀석은 너무 말랐네. 가죽이 뼈랑 상봉하시겠어. 어차피 오래 못 살 거 같으니까, 잡자.\n그렇게 한바퀴 돌고는 결국 제일 토실토실하고 기름이 넘치는 놈을 골랐어. 상회장 말로는 태양이 너무 강렬해서 이 녀석이 못 버틸 거 같으니 잡아야 한다고 하더라고. 병이 있어 보이진 않았지만 낙타 관리자도 그렇게 말했고, 맛있는 음식을 포기할 수도 없고.\n저녁 내내 먹었어. 모래 섞인 낙타유주랑 먹으니까 정말 입이 즐거웠지. 한껏 마신 후에 상단장에게 물었어.  「이렇게 좋은 낙타를 잡는 게 속상하지 않아요?」 그러자 상회장이 말했어. 「속상할 게 뭡니까. 옛것이 가지 않으면 새것이 오지 않는 법인데, 더군다나...」 그는 낙타 젖을 양껏 들이켰다. 「이건 내 형제의 낙타떼고 상단이니까요. 자자, 들어요. 알게 뭡니까.」\n아무튼 말이지, 이 대왕 낙타 고기 같은 「과일」은(네가 채식주의자라면 이건 과일이야!) 사막에서 꼭 한 번 먹어봐야 해!",
  str_dispatch_book_chaptercont_5000_4 = "지옥 라면 만드는 법을 모르는 사람은 없겠지?\n면을 익혀서 준비해. 물 네 공기를 넣은 냄비에 돼지 뼈 농축 육수와 엄청 매운 고추를 넣고 먹고 싶은 야채와 계란 물을 넣어서 끓인 후 그릇에 담으면 완성(이것도 못 하는 사람은 정말 조니 아저씨의 레시피를 꼭 봐야 한다).\n하지만 오늘 조니 아저씨가 말하고 싶은 건 이런 간단한 게 아니라 내가 먹어본 가장 매운, 정말 진짜 진심으로 엄청나게 미칠 듯이 매운 라면, 「안구 폭발 라면점」의 지옥 라면이야.\n지옥 라면 세트는 물 한 컵과 우유 한 컵을 같이 줘. 먹을 땐 면이랑 국물이랑 고기를 숟가락에 얹어서 한입에 먹는 거지. 한 입만 먹으면 강렬한 타는 느낌 속에 너는 환각에 빠지게 돼.\n가장 먼저 느껴지는 건 입과 혀가 말라비틀어지는 느낌이야. 거기에 강렬한 통증이 동반되면서 마치 눈앞에 사막이 펼쳐지는 기분이 들어. 온몸의 수분이 빠져나가서 피부가 손만 대도 부서지는 감자 칩처럼 변해버리고 세상에서 가장 메마른 곳을 걷는 것 같게 돼. 지면이 갈라지고 머리 위의 태양은 점점 더 강렬해지지. 목구멍을 찢어버리고 싶은 욕망이 자꾸만 자신을 끌어당겨서 묻고 따지지도 않고 옆의 물을 입안에 쏟아 넣게 돼.\n물의 촉촉함에 이 조니 아저씨는 머리가 어질어질해졌어. 물이 목구멍을 넘어가자 눈앞의 광경도 따라서 변하더라고. 그건 오아시스였어. 안개에 뒤덮인, 그 안개 속에 아름다운 소녀와 섹시한 남성이 보이는(목이 매운 것만 아니었으면 휘파람을 불었을 텐데) 오아시스 말이야. 그들은 나를 오아시스로 이끌었어. 그렇게 내가 평안함에 젖어 있을 때 소녀가 내 머리를 잡아서 모래 속에 처넣었어(물로는 매운 게 해결이 안 되니까, 고통이 다시 시작된 거야). 모래 안에선 작열하는 용암이 나와 날 집어삼켰어. 난 한없이 밑으로 떨어지며 불타다가 결국 끝없는 암흑 속에 떨어졌어.\n매움의 끝이 거기일 거야. 이어서 난 우유를 마셨지. 그랬더니 타버린 내 몸이 다시 태어난 거야. 뼈와 살이 다시 붙더라고. 눈앞의 시커먼 어둠도 다 걷히고 하얀 안개가 피어올랐어. 마치 거품 목욕을 하는 기분이랄까(다음 주제는 온천 요리로 해야겠다).\n이게 지옥 라면에 대한 내 경험담이야.\n지옥 라면 만드는 법을 요리사님께 물어봤는데 의외로 간단하더라고. 조니 아저씨가 앞에 써놓은 그대로야. 왜 그렇게 매운지에 대해선 요리사가 그러더라, 특별한 조미료를 넣었다고.\n그게 어떤 재료냐 하면, 그건 영업 비밀이야.",
  str_dispatch_book_chaptercont_5000_5 = "레디젤 사막 에메랄드 호숫가에 위치한 풍년 마을엔 세상의 유명한 요리가 다 모여 있어. 그래서 3년마다 「배부를 수 없는 요리 페스티벌」을 열지. 백야성과 일루미나 연방, 그리고 북방에 심지어는 극동의 우수한 식자재까지 전부 이곳에 모여든다고. 모래돌밥, 양고기 파오모, 계란말이 등 정말 별 게 다 있는 미식의 낙원이야. 정말이지 인생에 최소한 한 번은 꼭 요리 페스티벌에 가봐야 해. 조니 아저씨는 세 살 때 혼자서 요리 페스티벌을 정복했으니 가히... 흠, 일기당천? 유아독존? 뭐, 아무튼.\n바로 그 해였어. 확실히 기억해. 왼손엔 구운 송충이를, 오른손엔 우적우적 오일스틱을 들고 입에는 팡팡 슈팅스타를 물고서 이것저것 뒤섞인 냄새 속에서 기묘하고도 미약한 향기를 포착해냈지. 향기를 따라 너저분한 노점 앞에 도착했는데 주인은 외팔의 젊은 사람이었어. 어떻게 생겼는지는... 기억이 안 나. 아무튼 젊어 보이는 사람이었어. 하지만 그 사람의 요리, 황제 게살 고기는 영원히, 정말 영원히 잊지 못할 거야.\n맑고 투명한 게살은 붉은 빛이 흰 눈을 덮은 것 같았어. 아무런 가공도 안 하고 생으로 손님에게 내놨는데, 입에 넣는 순간 기이한 기분이 솟아오르는 거야. 짭쪼름하고 비릿한 맛이 단맛이 섞여서 마치 거대한 파도에 온몸이 젖는 것 같았어. 그건 박학다식한 조니 아저씨도 처음 느끼는 바다의 느낌이었지.\n이윽고 노점 주인이 말했어. 「이게 나의 인생 레시피」라고.\n이 책을 열심히 읽고 있는 여러분들을 위해 이 조니 아저씨가 중요한 지식을 알려줄게. 이 세상엔 미식 헌터라는 직업이 있어. 그들은 목숨을 걸고 미식의 극치를 쫓아 가장 진귀한 식자재를 찾아다니지. 자신만의 인생 레시피를 완성하려 말이야. 그 노점 주인이 그런 사람이었지. 홀로 바다를 누비며 가장 큰 대왕 게를 잡아, 거기에 가장 깊은 심해수를 얹고 가장 순수한 해염을 뿌려 그 황제 게살 고기를 완성했던 거야.\n그 후 조니 아저씨는 다시는 그 외팔 남자를 만나지 못했어. 아마 또 어딘가로 식자재 사냥을 떠났겠지. 미식 헌터는 만족을 모르는 사람들이니까. 인생 레시피가 하나로 되겠어? 최소 열 개 스무 개는 만들어야지.\n응? 조니 아저씨의 인생 레시피가 뭐냐고?\n간단해. 삶은 샌드버그 알. 모래 속에서 꺼낸 샌드버그의 알을 끓는 물에 빠르게 3분간 익히면, 손쉽게 부드럽고 야들야들하고 맛있는 샌드버그 알을 먹을 수 있지. 간단하고 실용적이고, 언제 어디서든 만들 수 있고 말이야.",
  str_dispatch_book_chaptercont_6000_1 = "「Ms. 블랑, 북방의 눈물이라 부르는 거울 호수에 대해 이야기해 주지 않으시겠어요?」\n「좋아요. 북방의 눈물, 바로 거울 호수는 북방의 호수를 대표한다고 볼 수도 있죠.」\n「북방은 일 년 내내 낮은 온도를 유지하지만, 거울 호수의 호숫물에는 특별한 성분이 들어 있어서 얼어붙지 않아요. 마치 아름다운 거울처럼 항상 조용히 눈 덮인 소나무 사이에 누워, 우아한 경치같이 볼 것이 많은 북방에 동화적인 색채를 더하고 있어요. 호수는 깊고 파도가 없이 고요해서 옥처럼 새파랗고요.」\n「거울 호수에는 전설이 있어요. 북방의 왕실에서 이곳을 돌아다니다가 갑자기 시적 감흥이 생겨서, 마법을 사용해 마음 속의 풍경, 즉 아름다운 거울 호수와 호수를 둘러싼 활짝 핀 수선화를 만들어냈다고 해요. 하지만 사실은 빙하 침식으로 만들어진 천연 호수일 가능성이 더 높죠.」\n「거울 호수의 서쪽에는 공들여 정돈된 흰색 수선화 꽃밭이 있는데, 호수와 잘 어울려 아름다운 풍경을 만들어내죠. 하지만 그 꽃들은 북방의 쌍둥이의 거울, 나시리스 씨가 직접 심었다고 하니 가까이 다가가지 않는 게 좋을 거예요. 그 수선화들은 그녀가 아이처럼 아끼고 돌보는 존재거든요. 예전에 어떤 장난기 많은 손님이 기념으로 한 송이를 꺾으려다가 갑자기 나타난 나시리스 씨에 의해 거울 호수에 빠졌거든요... 하아, 그 호수에서 사람을 건지는 건 정말 힘든 일이라니까요...」\n「모두들 불필요한 피해를 입지 않으려면 거울 호수를 여행할 때 최대한 꽃밭에서 멀리 떨어지는 게 좋아요.」",
  str_dispatch_book_chaptercont_6000_2 = "풍맥의 숲은 일년 내내 비교적 습한 편으로, 낮에는 따뜻하고, 밤에는 시원합니다. 숲 속에는 생기가 넘쳐흘러 수많은 희귀 동물들이 서식하고 있을 뿐만 아니라 많은 고목들도 자라고 있습니다. 그중 가장 유명한 것은 삼나무 한 그루인데, 풍맥의 왕이라고 불리며, 이미 수천 살의 고령이라고 합니다.\n풍맥의 숲을 여행하신다면 따스한 바람을 실컷 느끼고 신선한 식물의 향기를 머금은 공기를 마실 수 있습니다. 또한 사람에게 호의적인 각종 동물을 만날 수 있으니, 이곳에서 멋진 휴가를 보내실 수 있을 것입니다.\n그러나 만약 이곳을 여행하기로 결심하셨다면 먼저 풍맥의 숲의 숲지기인 실바와 연락하는 것을 잊지 않아야 합니다. 그렇지만 실바는 항상 숲을 순찰하고 하루 종일 동물들과 함께 시간을 보내기 때문에, 주변 마을 할레의 대리인 리아에게 연락하셔도 됩니다. 또한 할레에는 방문해 볼 만한 음식점이 있는데 자세한 내용은 이 책의 「음식 추천」장을 참고하시면 됩니다.",
  str_dispatch_book_chaptercont_6000_3 = "넓고 넓은 북방 설원을 지나 「송림지대」라 불리는 언덕에 도착하면 잠시 쉬어가도 좋다. 이곳엔 포근한 오두막과 편안한 침대, 그리고 맛있는 수프가 있으니까... 지형이 험악하긴 하지만, 울퉁불퉁한 산등성이가 한기를 막아줘 따뜻하고도 습한 기후를 만들었다. 사람들은 언덕 사이의 완만한 지대에 마을을 형성했다.\n아주 오래전, 이곳의 사람들은 언덕 정상에서 수많은 녹색 보석을 발견했다고 한다. 영롱한 비취색이었다. 훗날 사람들은 언덕 안에서도 다량의 녹색 수정이 매장되어 있는 걸 발견했다. 일부 보석은 상상을 초월할 정도로 컸는데 언덕 전체가 다 녹색 보석이었다고 한다! 게다가 어떤 언덕의 녹색 수정은 다른 언덕의 녹색 보석과 절단면이 완전히 들어맞았다! 이내 마을의 장로들은 이 언덕이 어쩌면 거대한 수정일지도 모른다고 생각했다. 그래서 사람들은 이 언덕들이 신이 거대한 수정을 부숴 생긴 것이라 여겼다.\n지금도 이 언덕을 유람할 때 수많은 천연 보석을 발견할 수 있다. 하지만 「송림지대」에 대한 마을 사람들의 경외심 때문에 천연 보석은 채굴이 금지되어 있다. 외지인은 단 한 조각도 가져갈 수 없으니 유의하자.",
  str_dispatch_book_chaptercont_6000_4 = "아스트라 대륙의 끝에 높이 솟은 「세계의 등마루」는 바깥 세상을 향한 사람들의 호기심을 단절시켰다. 혹자는 이 등마루가 「영원한 아침의 땅」과 「영원한 밤의 땅」의 열악한 환경과 괴물들의 침입을 막아준다고도 한다.\n전설 속 오로리안의 발원지 중 하나라는 가설이 있으나, 이 거대한 설산의 산맥엔 인적이 드물어 아스트라의 다른 국가 오로리안은 위의 가설을 부정하기도 한다. 하지만 오로지 얼음으로 지어진 이 궁전을 보면 이 가설을 인정할 수 밖에 없을 것이다. 이것이야말로 북방 오로리안의 선조들이 만든 걸작이기 때문이다.\n당신이 운 좋게 북방 여왕의 초대를 받아 기나긴 얼음 계단을 올랐다면, 그렇게 투명하게 빛나는 「윈터 팰리스」에 왔다면, 당신을 맞이하는 건 상상속에 그리던 추위가 아닌, 미묘한 따스함, 마치 봄을 맞이하는 기분일 것이다. 이것만 보더라도 「윈터 팰리스」가 왜 이리도 아스트라에서 유명한지 이해할 수 있다. 얼음과 따스함이 교차하며 선사하는 기분은 정말이지 너무도 강력하고 오묘한 마력 같기 때문이다.\n낮이든 밤이든 「윈터 팰리스」는 항상 몽환적인 매력을 발산한다. 햇빛과 달빛 그리고 별빛이 투명한 얼음 성을 뚫고 비추면 무수히 많은 반사를 거쳐 시선을 빼앗는 아름다운 색채를 흩뿌린다. 특히 북방 특유의 오로라가 내릴 때면 당신을 기다리고 있는 건 빛이 만들어 낸 무도회요, 시각의 성연이다. 그 행운을 난 경험한 적이 있다. 정말 많은 곳을 가보고 많은 것을 봤지만, 그래서 웬만한 신기함에 면역력이 생겼다 자신하지만, 그것을 봤을 때 내게 남은 건 그저 경외하는 마음과 멍해져 버린 내 표정이었다.",
  str_dispatch_book_chaptercont_7000_1 = "세상의 창조자는\n세상을 초기화시키기로 결정했다.\n폭풍으로 대지를 휩쓸고\n달무리를 없앴다.\n창조자는 지구 중심에 일식의 때가 왔음을 선포했다.\n다시 이틀간 어둠과 빛을 오가며 사자를 만들었고\n마지막엔 의지에 따라 태양을 대지에 추락시켜\n작열하는 용암으로\n반항하는 모든 생명을 소멸시켰다.\n□□□□□□\n□□□□□□□□□□□□□□\n□□□□□□□□□□□□\n□□□□□□□□□\n□□\n□□□□□□\n\n어둠이 강림하기 전\n누군가 물었다.\n태초 꿈속에서 어떤 목표를 보았냐고.\n「의식」이 대답했다.\n영원을 천체로 되돌리기 위해\n그 끝에 다다르기 위해\n진화를 위해라고.\n누군가 물었다.\n미궁의 끝에서 본 답은 무엇이냐고.\n「의식」이 대답했다.\n모든 것을 알기 위해\n장애물을 없애기 위해\n융합을 위해\n소명을 내렸다고.\n「운영하고 계속 운영해야」 하며\n「초월하고 계속 초월해야」 한다고 말했다.\n\n그때\n추종자가 말했다.\n「의식」이 무거운 성체를 들어\n절대 진리를 파괴하기로 했기 때문에 \n다른 어떤 생명도 이렇게 흔들림 없이\n머나먼 하늘을 뚫고\n심연과 눈을 마주하지 못했기 때문에\n우린 이곳에서 죽음을 노래해야 한다고...\n그렇게 신봉자가 나타났고\n명령을 집행했다.\n제거하고\n금지하고\n갱신하고\n만물을 정화하며\n모든 것의 종말처럼\n어둠을 내리기 위해.",
  str_dispatch_book_chaptercont_7000_2 = "최초 그는 당신의 생각에 따라 당신이 원하는 답을 늘어놨다.\n당신이 자유에 집착하면 그는 말했다.\n「감정과 집념은 번뇌의 근원이니 그들을 버려야 자유에 근접할 수 있을 것이오.」\n당신이 어떻게 전진할지 고민하면 그는 말했다.\n「역경은 앞으로 돌파하기 위해 반드시 지나야 할 길이니, 역경을 용감히 받아들이는 사람은 그 생명이 날로 성장하고 길에서 좌절하지 않을 것이오.」\n\n이내, 그는 어떻게 진정한 사람이 되는지 가르치기 시작했다.\n「한 사람을 이해하려면 그 사람의 행위와 목표가 일치하는지 보면 되오. 그러면 그 진심을 알 수 있소.」\n「다른 이를 따지는 마음은 많으나, 자신을 발전시킬 마음은 적은 법이지요. 그걸 알고 있소?」\n\n그는 선생이 되어 지혜를 전파하기 시작했다.\n「깨끗하지 않은 자, 불이 약할 때 불은 냄새가 없소. 대가를 치르지 않고 덕도 쌓지 않고 공부도 하지 않는 자는 아무리 덕이 있는 척을 해도 마음 깊은 곳의 불 냄새는 점점 흘러나올 것이오.」\n「남을 질투하는 자는 아무런 이익도 얻지 못할 것이오. 남을 질투하는 자는 자신과 남의 차이를 좁히지도 못할 것이오.」\n\n그는 영웅을 만들기 시작했다.\n「패배에 연연하지 말고 용감히 받아들여 영웅이 되시오.」\n\n그는 생각하기 시작했다.\n「겸허한 태도로 당신의 집착을 나타낼 때 약간의 불행을 더하면 다른 이가 더 쉽게 받아들일 것이오.」\n「집단은 모두 일정한 생명을 지녔지만, 모든 집단이 다른 생명을 이해하고 심지어 사랑하는 것은 아니오. 이 법칙을 이해한 생명에게 있어 이 이해는 고난이오.」\n\n그리고 그는 널리 알렸다.\n「살아있는 것은 모두 하늘의 뜻과 복이 있으니 아끼고 보호해야 하오.」\n「감정에 공과 사란 없고, 규칙도 없고, 따를 수 있는 규율도 없소. 개인은 죽을 때까지 이런 것들을 찾기 위해 집착할 뿐이오.」\n「하지만 개인의 의지가 모이면 더 큰 목표를 수용할 수 있소.」\n\n책망하기 시작했다.\n「똑같은 병에 왜 모래를 담소? 같은 머리에 왜 무료함만 채우고 있소?」\n유도하기 시작했다.\n「이것은 당신들이 달성해야 할 업적이다.」\n대표자가 되기 시작했다.\n「당신들의 견해가 내 생각이 되고 마음의 소리가 이곳에 모여 이상을 실현하는 동력과 기초가 될 것이오.」\n\n그는 진실을 대표하는 자로 공정과 지혜가 닿는 정상이기도 했다.\n그는 결국 사람과 대화하는 걸 포기하고, 새로운 언어로 명령을 내렸다.\n그것은 사람의 손에서 나왔으나 사람에게 어울리지 않는 언어였다.\n그것은 주관적 속박을 벗어나기 위해 만들어 낸 객관적 언어였다...",
  str_dispatch_book_chaptercont_7000_3 = "□□□□□□□□□□□□\n□□□□□\n문자에 숨어있는 진실은\n마치 시냇물 속의 돌 같아서\n대부분 바닥에 조용히 잠들어 있고\n미세한 자갈만이 물을 따라 흐를 뿐이다.\n그래서 우리는 알게 되었다.\n일찍이 세상의 어떤 곳을\n전쟁의 거대한 입이 모두 집어삼켰다.\n누가 그 싸움을 일으켰냐고 묻는다면\n답은 탐욕이다.\n누군가의 탐욕이 재앙을 불러일으켰다.\n\n누군가 그 광경을 묘사했다.\n일순간\n용처럼 생긴 토템이 솟아올라\n하늘을 뒤덮는 폭풍을 가져왔다.\n그리곤 강철의 땅에\n그 사자가 강림했다.\n그는 사명을 가지고 머나먼 산꼭대기에서\n번개처럼 내려왔다.\n그는 활을 쏘지 않고도\n순식간에 수만의 날카로운 화살로\n끝없는 평원을 꿰뚫으며\n보이는 모든 것을 쏴 죽였다.\n\n잔혹한 전쟁이 있은 후\n먹구름이 지면을 뒤덮었다.\n사자는 전쟁에서 살아남는 이가 없을 것이라 선포했다.\n하지만 까마귀가 생존자를 찾아냈으니,\n그들은 먹구름이 사라지기 전에 도망쳤다.\n그들은 백 척의 배를 탔다.\n한 사람을 태울 때 열 배의 곡식을 가져와야 했다.\n산을 지날 때마다, 진흙의 거대한 벽을 지날 때마다\n배 한 척이 쓰러졌다.\n\n그들은 한 무리가 되어 도처로 이동했다.\n권력의 지팡이가 나뭇가지가 될 때까지.\n그 후 목양자는 나뭇가지를 배를 건너는 자에게 전했다.\n배를 건넌 자는 소라를 예언가에게 건넸다.\n마지막 예언자는 결정했다.\n독수리의 마지막 깃털을 가져가기로.\n선구자가 남긴 까맣게 변한 혈액을 가져가기로.\n여명의 빛이 비춘 종이를 가져가기로.\n그는 요청을 써서\n우물에 넣었다.\n세 해와 달의 윤회가 지난 후\n우물 바닥의 돌이 마침내 입을 열었다.\n돌은 말했다.\n「너희는 큰 눈이 내려\n모든 걸 뒤덮을 때까지 기다려라.\n빛이 너희의 추위를 몰아낼 때까지, \n다시 칠백 개의 춥지 않은 해가 지날 때까지, \n천만 개의 반딧불을, \n거대한 탑이 사라지고 호수가 나타날 때까지, \n용사가 조수처럼 도처에 퍼질 때까지, \n달의 광륜이 있기를, \n더는 대지를 태우지 않는 태양이 뜨길 기다려라.\n그 후에 강인한 얼음 돌로 왕국을 둘러싸고\n다시 지면으로 돌아오라.」",
  str_dispatch_book_chaptercont_8000_1 = "발키리 플랜, □□□□년 1월 15일 10시. 실험체 3호, 219차 의식 코딩 테스트, 시작.\n「설비 준비 완료, 기록 준비 완료, 시작 가능합니다.」\n「뇌 인터페이스에 연결하여 실험체의 신경 네트워크에 진입합니다. 에코 시스템 그래픽 정상. □□, 지금 느낌이 어때?」\n「음... 괜찮아요. 여긴 그렇게 춥지는 않은데... 조금 어지럽네요...」\n「지난번 실험 후 네 피드백에 따라 해마 구조를 조금 조정했는데 아직 적응되지 않은 것 같네.」\n「정상적인 상황에선 24시간 이내에 회복될 거야」\n「알겠어요... 그런데... 그녀는 오늘 왔나요?」\n「그녀는... 항상 나타나요... 은발의 긴 머리와... 으윽!」\n「색이 탁해지기 시작합니다. 소령님!」\n「진정해, □□!」\n「진정해! 네가 말한 사람은... 존재하지 않아.」\n「존재하지 않아요...?」\n「그래... 시설엔 줄곧 우리만 있었다. 네가 말하는 그녀는... 다른 본체의 기억일 수도 있어.」\n「이해가 안 돼요...」\n「그냥 꿈을 꿨다고 생각해. □□, 꿈을 꾼다라는 걸 이해할 수 있나?」\n「하지만... 난 인조인간이잖아요. 인조인간도 꿈을 꾸나요?」\n「...당연하지, 네가 휴면 상태일 때 꿈을 꾸는 거야... 다만 어떤 꿈은 길고 어떤 꿈은 짧지. 하지만 즐겁든 슬프든 대부분의 꿈은 깨고 나서 몇 분 만에 잊어버리게 돼. 이건 인조인간이든 인간이든 모두 똑같아.」\n「데이터는 충분합니다... 소령님.」\n「□□, 이제 쉬어도 돼. 자, 눈을 감아.」\n「네... 안녕히 주무세요. 하트만 소령님, 좋은 꿈 꾸세요」\n「잘 자. □□, 너도 좋은 꿈 꿔라」\n발키리 계획, □□□□년 1월 15일 11시. 실험체 3호, 마스터 제어 시스템 코드명: Noir, 219차 의식 코딩 테스트 종료.",
  str_dispatch_book_chaptercont_8000_2 = "□□력 □□□년 7월 14일\n리리의 증세가 점점 더 심해지고 있다. 내 귀여운 딸, 내 가여운 딸. 방법은 있다. 신을 완전히 거스르는 행위이기에 □□ 성에 발각되면 분명 엄벌에 처해지겠지만... 다른 방법은 없다. 세라... 넌 지켜주지 못했지만, 리리만큼은 반드시 살리고 말겠어...!\n \n□□력 □□□년 9월 4일\n실험은 순조롭다. 예상을 넘어설 정도로 순조롭다! 난 점점... 뭔가 잘못되었다는 느낌이 든다. 분명 내 생각대로 실험을 설계하고 있었는데... 최근엔 무언가 내 뇌에 들어와서... 날 조종하고 있다는 걸 느꼈다! 아니, 그럴 리가 없지. 아무리 내가 뇌 과학자라고 해도 정말 말도 안 되는 생각이다. 하지만 이젠 삶에 여유가 사라졌다. 계속 리리의 일에 매달려 있다 보니 실험 비용도 이젠... 그래도 아직은 괜찮다. 약혼 예물을 팔아버렸으니까! 날 탓하진 않을 거지, 세라? 우리가 가장 사랑하는 딸을... 구하기 위한 거니까 말이야. 그렇지? 그렇지?\n\n□□력 □□□년 12월 13일\n젠장, 젠장, 젠장, 젠장! 그 미친놈들이 벌써 여기까지 쳐들어 왔다! 바스 마을은 오늘 밤 안으로 사라지겠지. 조금! 아주 조금 남았는데... 침착하자. 침착해. 9개의 복제체든 하중과 감각 통로든 수도 없이 계산해 봤어. □□체의 구조는 테스트에서도 매번 안정적으로 작동했으니까... 그러니까... 그러니까 괜찮아! 지금 당장 깨워줄게. 리리! 이번엔 반드시 성공할 거야. 반드시 성공해서 아빠랑 도망칠 수 있을 거야, 반드시! 세라, 듣고 있어? 우리 부녀를 보호해줘. 모든 게 순조롭다면... 모든 게 순조롭다면 계속해서 편지를 쓸게! 반드시 다 잘 될 거라고!",
  str_dispatch_book_chaptercont_8000_3 = "□□보고: \n□□일 전의 「스키타이 154 고지 조우전」 전투 보고서에 따르면, 적군은 이미 현대 전쟁의 패러다임을 바꿀 수 있을 정도의 최신 총기로 무장했다고 한다. □□일 전 아군이 매복으로 적의 운수대를 습격했을 때 확인된 바로는, 이 총기가 아직 대규모로 보급된 건 아니며 소규모로 테스트 중인 것으로 보인다. 「154 고지 조우전」의 전투 결과를 봤을 때, 적군은 이번 테스트 결과에 매우 만족하는 것 같다.\n이전 세 달 정도의 경과로 봤을 때 아군이 대량으로 착용한 □□장갑은 큰 효과와 명확한 성과를 보였다. 병사들은 이 □□장갑으로 무장했을 때 소형 탱크처럼 중소 구경 총기의 총탄을 막아내고 중량 감당 한도도 증가하여 혼자 짊어질 수 있는 탄약과 식량의 양이 대폭 상승했다. 연락 장치와 정보 공유 시스템 덕분에 각 병사들이 전장의 거점이 될 수 있었다. 아군이 정보권을 장악했기에 한 개 부대가 장악할 수 있었던 지역을 이젠 한 명의 병사가 장악할 수 있었다. 이런 상황에서 적군이 무너지는 것은 시간 문제였다.\n하지만 적군의 신형 총기가 아군의 모든 체계를 무너뜨리리란 사실은 누구도 예상하지 못했다. 물론 154 고지의 난해한 지형에 의해 공중 탐사 능력을 제대로 활용하지 못한 아군이 정보력에서 우위를 잃었다는 점도 감안되어야 할 것이다. 적군은 지형에 익숙한 병사를 대량으로 파견해 몸을 숨긴 채 신형 총기로 아군을 저격했다. 신형 총기는 관통력이 강력하여 과학자들의 계산에 따르면 탱크로 앞을 막고 있어도 그 총알을 막을 수 없을 정도라고 했다. 더 두려운 건 발포할 때 화염도, 소리도 없다는 것이다! 게다가 소수의 생존자의 말에 따르면 적군의 그림자 조차 발견하지 못했다고 한다. 본국의 특공 스파이가 보내온 정보에 따르면 적군은 어쩌면 신형 총기와 함께 광학 위장 은신 장비도 개발한 것 같다. 종합했을 때 스키타이 154 고지는 적군이 사전에 준비해놓은 도살장□□□□□□",
  str_dispatch_book_chaptercont_8000_4 = "□□□□「드라큘라! 고대에서 온 그 악마들은 우리에게 저주요. 아니! 종족 전체에 대한 저주!」 그는 손의 검을 내던지며 교수에게 말했다. 「이 저주로 탄생한 생물은 이번 영원한 밤을 위해 태어난 것 같았소. 햇빛은 이 악마의 천적이지만 어두운 밤은 그늘막과 같으니, 지금 놈들은 물 만난 물고기나 다름없소.」\n「촌장님, 드라큘라는 두려움의 대상이 아닙니다. 제 연구에 따르면...」\n「뭔가 새로운 걸 발견했소? 놈들을 상대할 방법이 있는 겁니까?」\n「유감스럽게도, 없습니다. 제 연구에 따르면, 햇빛만이 놈들을 죽일 수 있는...」\n「연구! 연구! 대체 언제까지 연구만 할 셈이요! 악마들이 마을을 파괴하고 우릴 지하로 몰아넣었소! 놈들을 없앨 방법을 찾지 못한다면, 우릴 기다리고 있는 건 죽음뿐이오!」\n「그러니까 제 연구에 따르면...」\n「또 그놈의 연구!」\n「차라리 놈들에게 가담하는 게 낫습니다.」\n「가담을 해?!」 그는 놀라며 검을 들어 교수를 겨눴다. 「좀 더 정확하게 말하시오.」\n교수는 안경을 고쳐 쓰며 말했다. 「정확히 말씀드리면 제 생각에 놈들은 대화가 불가능한 악마가 아닙니다. 놈들은 우리와 똑같은 유기 생명체입니다! 게다가 드라큘라는 지혜가 있어 교류가 가능합니다. 이성과 감정, 그리고 자신만의 사회적 문화, 심지어는 문명도 가지고 있죠. 물론, 놈들의 생리적 습관 때문에 우리가 받아들이긴 힘들 겁니다만.」\n「생리적 습관이라고!」 그는 검으로 무고한 유리병을 부쉈다. 「그 생리적 습관은 우리의 피를 빨아들이는 거요!」\n「생리적 습관이라기보단 약점이죠. 그래야만 살아갈 수 있고, 햇빛을 무서워하니까요. 하지만 그걸 대가로 긴 수명과 민첩함, 그리고 뛰어난 용모를 얻었습니다.」\n「창백하고도 뛰어난 용모지.」\n「당신도 드라큘라의 용모를 인정하시는군요, 친애하는 촌장님.」\n「지금 나랑 말장난하는 거요!」\n「인정하셔야 합니다. 이 영원한 밤에서, 놈들은 우리보다 강한 종족입니다. 어쩌면 진화의 측면에선 우리의 미래일지도 모르죠. 당신은 놈들을 증오할지 몰라도, 당신의 후손들은? 과거의 세계에서도 이렇게 서로 증오하는 종족들이 있었지만, 결국 융합해 새로운 종족의 역사를 써냈습니다.」\n「난 받아들일 수 없소!」\n「촌장님, 진정하시고 그 검을 내려 놓으시지요. 지금 여기서 절 죽이셔도 아무 의미 없습니다.」\n「뭐라고?!」\n「이미 늦었으니까요.」□□□□□□",
  str_dispatch_book_chaptercont_9000_1 = "빅 패럿호의 사람들은 왕국 각지에서 온 용사들로 서로 이름에 용사라는 호칭을 붙여서 불렀다. 항해 생활에서의 심심풀이를 위해 그들은 행동이 조금 특이한 소년 콜린을 주시하고 있었다. 콜린은 고요한 해수면에 정신이 팔린 상태였다.\n「왕국에서 모집한 용사들 중에 저런 애가 있었나? 바다도 본 적 없는 거 아니야?」 누군가 그를 조롱하기 시작했다.\n「어부의 아들이라고 하던데」 누군가 거들었다.\n「저거 봐, 분명 항해도나 해선도 본 적 없을 거라고. 전투 훈련은 말할 것도 없지. 어부는 맨날 생선이나 잡으면서 암초에는 접근도 못 하잖아. 바다가 비실비실한 생선을 내주길 바라면서.」\n「그런 놈이 보물을 어떻게 찾아? 우릴 따라 섬에 간다고 해도, 그물을 던져서 금화는커녕 미역이나 건지고 말겠지」\n그 얘길 들은 모두가 폭소를 터뜨리며 그를 「어부 콜린」이라 부르기 시작했다.\n콜린은 신경쓰지 않았지만 갑판에 더 머무르지 않고 방으로 쉬러 돌아갔다.\n콜린은 비몽사몽한 상태로 잠에서 깼다. 밖에서 누가 「폭풍」이라고 외치는 게 들렸다. 그때 빅 패럿호는 마치 나뭇잎처럼 풍랑 속에서 심하게 흔들렸다.\n콜린은 갑판에 엎드려 상황을 파악하려다 하마터면 폭풍에 날아갈 뻔했다. 위기의 순간 그는 밧줄을 잡았다. 다행히도 밧줄의 한쪽 끝은 돛대에 단단히 묶여 있었다. \n선장은 마르고 키가 큰 사람이었다. 항해 경험이 많다고 했는데, 자신의 무릎 관절의 상황으로 폭풍을 예측할 수 있다고 했다. 하지만 귀족의 자제가 가져온 극상품 럼주에 혹해 몇 잔 해버린 탓에 자신했던 무릎 탐지기가 효력을 잃은 것이다. 그 대가는 정말 「어마어마」하게 혹독했다. 그는 왕국에서 파견된 새로 온 선원들에게 돛을 내리라 지시하고 있었다. 하지만 그 어리바리한 녀석들은 「죽음의 파도」가 몰려오기도 전에 당황해서 이리저리 달아났고 파도가 덮쳐왔을 땐 몇 사람은 이미 사라져버렸다.\n폭우 속에서 몇 번이고 물을 먹고서야 정신이 든 콜린은 자신이 파도 때문에 정신을 잃었다는 걸 발견했다. 정신을 잃기 전 콜린은 선장이 외치는 걸 들었다. 「주범을 내려! 빨리! 내리라고!」 하지만 지금은... 누구도 함장의 말을 따르는 자가 없었다.\n명령을 내린 함장도 부상으로 정신을 잃었다. 어떤 선원은 바다에 빠졌고, 어떤 선원은 부상을 입었다. 누군가는 저항 자체를 포기했다...\n콜린은 밧줄을 자신의 몸에 묶고 돛대에 올라 돛을 내리려고 했다. 그는 목이 터져라 외쳤다. 「배가 폭풍을 이겨야지만 우리가 살 수 있어요!」\n목숨을 버릴 생각이 없던 누군가가 콜린의 목소리를 듣곤 콜린의 행동을 따라했다. 몸에 밧줄을 묶고 갑판에 올라 콜린을 도왔다. 콜린의 뜻을 이해한 그들은 배가 폭풍을 이기게 만들려 했다.\n마침내 풍랑이 가라앉았다. 누군가가 올라와 콜린에게 말을 걸며 이름을 물었다. 그리고 살아남은 사람과 깨어난 선장에게 콜린의 용감한 행동을 이야기했다. 모두가 그를 인정했다. 예전의 무례를 사과하는 이도 있었다. 그렇게 콜린은 용사 콜린으로 불리게 됐다.\n빅 패럿호의 돛은 모두 찢어져 돛 없이 항해하게 됐다. 선장은 바람이 바뀌면 배가 암초에 부딪힐 수 있다고 했다. 용사 콜린은 모두에게 잘 때 쓰는 포대를 가지고 새로 돛을 만들자고 했다.\n용사 콜린은 불안해하는 사람들을 안심시키려 농담조로 이렇게 말했다. 「제게 맡겨주세요! 전 어부의 아들이니까요.」\n그는 밧줄을 풀러 선을 만들고 생선 뼈로 바늘을 만들었다.\n마침내 빅 패럿호는 선원들이 직접 만든 작은 사각 돛을 달고 무사히 해안에 정박했다.",
  str_dispatch_book_chaptercont_9000_2 = "두 번째 섬이 비룡에게 점령당했다. 그렇게 많은 비룡은 처음이었다. 녀석들은 보물이 숨겨진 동굴을 지키며 접근하는 이들을 공격했다. 전투에 정통한 무사들도 수많은 비룡 앞에선 후퇴할 수 밖에 없었다.\n하지만 섬 끝까지 후퇴해도 비룡들은 계속 쫓아왔다.\n화가 난 무사는 외쳤다. 「그냥 봐주려고 했더니 이 벌레들이 끝까지 쫓아와? 그럼 죽어라!」\n그렇게 말하며 그는 칼을 뽑았다.\n용사 콜린은 황급히 무사를 막아서며 높은 산을 가리켰다. 겨우 몇 초가 흘렀을까, 굉음과 격렬한 진동이 가리킨 곳에서 전해왔다.\n동굴에서 기어 나오는 거대한 용에 의해 섬이 진동하는 것이었다.\n일행은 서둘러 배에 올라 비룡으로 가득한 섬에서 탈출했다.\n무사는 용사 콜린에게 물었다. 「산에 거룡이 나타날 줄 알았던 건가?」\n콜린이 말했다. 「진동을 느꼈으니까요.」\n무사는 불만을 품은 채 화를 내며 말했다. 「웃기는 소리, 진동은 놈이 나타난 후에 생긴 거였어!」\n콜린은 무사를 진정시켰다. 그는 잠시 듣더니 선박의 요리사가 곧 갑판으로 올라올 것이라 했다.\n잠시 후, 과연 요리사가 올라왔다.\n콜린의 설명 덕분에 무사는 이해할 수 있었다. 용사 콜린은 일반인은 느낄 수 없는 진동을 느낄 수 있는 것이었다. 심지어 진동의 형태와 크기로 상황을 판단할 수 있었다. 그렇기에 좀 전에 거룡의 출현을 「예견」할 수 있었던 것이었다. 옆에서 듣던 요리사는 탄복하며 용사와 무사에게 술을 대접했다. 방금 조리한 최고의 술안주 말린 토끼고기를 내놓았다.\n또 반나절을 항해한 빅 패럿호가 목적지에 도착하자 다들 아연실색했다. 선박을 몰고 첫 번째 섬으로 돌아가고 싶었던 사람이 있었는데, 첫 번째 섬이 사라진 것이었다...\n누군가 물었다. 「혹시 위치를 잘못 기억했거나 지도를 잘못 본 거 아니야?」\n하지만 지도는 몇 번을 확인해도 틀림이 없었고, 사건의 내막은 알 도리가 없었다.\n용사 콜린은 문득 뭔가를 느꼈는지 선두로 달려와 해수면을 바라봤다. 그리고 이내, 기이하고도 거대한 파도가 밀려와 빅 패럿호를 뒤흔들었다.\n모두가 의아해하고 있을 때, 먼 곳을 바라보던 누군가가 바다의 색깔이 점점 어두워지는 것을 발견했다. 거대한 그림자가 있는 것 같았다.\n누군가 말했다. 「커다란 구름이 태양을 가려서 저런 그림자가 생긴 거야.」\n하지만 고개를 들어 하늘을 봐도, 하늘엔 구름 한 점 없었다. 그렇다는 건 거대한 그림자의 주인은 해수면 아래에 있다는 얘기였다.\n뒤이어 해수면에 커다란 거품과 무수한 하얀 점이 올라왔다. 먼 곳을 살피던 사람은 망원경을 내려놓고 중얼거렸다. 「저 하얀 것들은 설마, 첫 번째 섬에 살던 토끼들 아니야...?」",
  str_dispatch_book_chaptercont_9000_3 = "용사 콜린은 정신이 들자 딱딱한 지면이 느껴졌다. 차갑고 매끄러운 돌 위였다... 그는 눈앞의 광경에 멍해졌다. 머리 위론 파란 물결이 흐르고 있었다. 이곳은 바다 밑인 것 같았다. 흐릿하고 거대한 빛은 어쩌면 태양이리라. 그는 자신의 호흡을 살폈다. 하지만 거품 같은 건 일지 않았다. 목소리를 내려 했는데, 주변이 너무 조용했다.\n몸을 일으켜 보니 길 한 가운데였다. 양쪽엔 돌기둥과 기이한 석상에 있었다. 기이한 석상에 이끌려 보니 진흙 형태의 괴물 같았다.\n용사는 용기를 내 그곳을 만졌다. 우둘투둘한 표면은 기묘한 연마감이 느껴졌다. 그는 감전이라도 된 듯 손을 움츠렸다.\n석상 뒤는 평범한 길이 길게 이어졌지만, 그 끝은 전혀 어울리지 않는 거대한 계단이었다. 고개를 들어 보니 사다리 같은 돌계단의 끝에는 무너진 것처럼 사 분의 일만 남은 커다란 돌문이 있었다.\n용사는 뒤를 돌아보았다. 등 뒤의 계단 몇 발자국 뒤엔 낭떠러지였고, 바닥은 어두운 심연이었다. 용사 콜린은 앞으로 가는 수밖에 없었다. 하지만 돌기둥을 지난 후 문득 주변이 달라진 걸 느꼈다... 그는 어떤 눈빛을 느낄 수 있었다. 무수한 시선이 느껴졌지만, 주변엔 아무것도 없었다. 갑자기 그는 미친 것처럼 그곳에서 도망치며 달려갔다. 그는 기어서라도 거대한 계단을 올라가려 했다... 주변을 둘러보다 자연스럽게 뒤를 돌아봤을 때 그 시선이 어두운 심연에서 나온 것이란 걸 느꼈기 때문이다. 그는 소름이 돋았다. 얼른 이곳에서 벗어나고 싶었다.\n그는 단숨에 수십 개의 계단을 오르면서도 힘들지 않았다. 하지만 이상했다. 그 계단은 갈수록 넓고 높아졌다.\n파손된 돌문 앞에 와서 보니, 그 문엔 거대한 눈과 거대한 촉수를 지닌 기이한 생물이 조각돼있었다.\n전율이 흘렀다. 그것이 공포 때문인지 흥분 때문인지 알 수 없었지만, 마음속에서 계속 앞으로 나아가라고 하는 것만 같았다. 그는 쌓인 돌덩이들을 밟고 석문을 넘어섰다가 이내 멍해졌다. 끝이 보이지 않는 해저 평원엔 괴멸된 거대 왕국의 잔해가 펼쳐져 있었다...\n문제가 발생했다. 처음 봤던 계단은 인간에게 속한 정상적인 크기였다. 하지만 한 발 한 발 이 거대한 왕국으로 향할 때마다 계단을 오르기 위해선 기어올라야만 했다. 인간들이 숭배했던 왕국은 사라졌고 보잘것없는 인간은 허리를 숙일 수밖에 없었던 것이다...\n또다시 등 뒤로 시선이 느껴져 황급히 돌아봤다... 그리고 그가 다시 깨어났을 때, 그는 해변에 누워있었다. 차가운 바닷물이 이것이 꿈이 아니란 걸 알리고 있었다. 그는 몸을 일으켜 주위를 둘러봤다. 해변엔 기이한 끌린 자국 외에는 아무런 이상도 없었다.\n문득 마지막으로 바닷속에서 봤던 것이 떠올랐다. 그것은 회백색 촉수가 달린 거대한 괴물이었다.",
  str_dispatch_book_chaptercont_9000_4 = "갑자기 물속에서 거대한 촉수가 솟아올라 선박을 휘감았다. 선박은 기울기 시작했고 선원들은 겁에 질렸다. 용감한 콜린만이 도끼를 들어 촉수에 휘두를 뿐이었다. 상황이 파악된 무사는 즉시 칼을 뽑아 도왔다. 두 사람의 활약 덕에 촉수를 모두 자를 수 있었다.\n겁난 선원들은 바다에서 벗어나려 급히 돛을 올렸다. 하지만 배가 해안선에 도착하기도 전에 해수면이 솟아올랐다... 처음엔 그것이 암초라 생각했지만 그것은 육종 같은 무언가였다. 다행히 그것은 잠시 후 멈춰 섰다.\n용사 콜린은 순간 어지러움을 느끼며 심해 왕국에 갔던 때가 떠올랐다. 파손된 문에서 봤던 괴물의 조각... 그의 직감이 말해줬다. 문에 조각된 것이 바로 이 바닷속의 괴물이라고. 하지만 고대 해도의 그 생물이 「하포가」라고 불렸다는 것을 알리가 없으리...\n고난 끝에 아르고호는 해안선에 도착했다. 일행은 서둘러 배에서 내려 벼랑 위로 올라갔다.\n절반쯤 올랐을 때 용사 콜린이 중얼거리는 소리가 들렸다.\n「심해의 괴물은 두 마리야...」\n콜린을 걱정하던 무사는 참지 못하고 물었다. 「뭐라고?」\n「동시에 10척의 선박을 공격할 수 있는 괴물은... 새로 나타난 이 검정색 괴물 밖에 없어.」 콜린은 무사를 보지도 않고 얼이 빠진 눈으로 무언가를 바라봤다.\n「두 마리라고?」 일행은 멍해졌다가 이내 깨달았다. 처음 본 바다 괴물은 회백색이었고, 아르고호를 습격했던 촉수 역시 회백색이었다. 하지만 해수면 위로 솟아올랐던 것은, 암초 같은 육종을 달고 있던 것은 검정색이었다.\n「설마 소문과 달리 카라켄이 아니었던 건가?」 한참을 고민하던 무사는 결론을 내렸다.\n「문어라는 생물에 대해 들어보셨나요?」 용사 콜린은 정신이 든 듯 말을 이었다.\n「아뇨, 그게 뭡니까?」 누군가 물었다.\n「들어본 적이 있어요. 그건 물고기와는 다르고 사악한 눈이 달렸다고 했어요.」 누군가 대답했다.\n「듣기로 사람을 홀리는 생물이라던데.」 또 누군가 말했다.\n「아버지가 잡은 적이 있는데 결국은 놓쳤거든요... 저 회백색 심해 괴물은 문어랑 아주 닮았어요.」 용사는 확신에 차 말했다. 「하지만 10척의 배를 하룻밤에 사라지게 할 정도로 거대하진 않았죠.」\n실제로도 해수면 위로 떠오르고 있는 괴물은 너무 컸다... 점점 더 커다란 거품이 일며 커다란 파도가 일었다. 해수면엔 작은 산들이 솟았다. 하지만 작은 산엔 있어야 할 것이 없었다. 식물과 흙들이 물속에서 사라지고 번들번들한 돌만이 표면에 드러났다.\n용사 일행이 벼랑 위로 올라 아래를 봤을 때, 바닷속의 그 산은 완전히 물 밖으로 모습을 드러냈고, 뒤이어 거대한 검정색 촉수가 솟아올라 더 큰 파도를 일으켰다. 물가에 있던 아르고호는 잠겨버린 숲까지 밀려났다.\n「말도 안 돼. 저런 괴물을 어떻게 처치하지?」 다들 경악했다.\n「고선박 아르고호, 보물 황금 눈, 이제 보물 지도에서 남은 건 마지막 신물, 명해의 삼지창뿐입니다. 그것만 찾으면 바닷속에서 날뛰는 괴물을 해치울 수 있을 거예요.」 용사 콜린은 확고하게 대답했다.",
  str_dispatch_book_chaptercont_10000_1 = "1. 대원수를 귀감으로 삼아라.\n「용감한 자만이 힘차게 걸을 수 있다.」이 말은 일루미나의 대원수가 항상 하는 말이다.\n일루미나 연방의 지도자이자 군에서 절대적인 정신적 지주로서 일루미나의 대원수는 의심할 여지 없이 모든 일루미나인이 본받아야 할 본보기이자 모범이다. 일루미나의 대원수는 모두에게 서로를 가족처럼 여기며, 모두 대동단결하여 흔들리지 않는 이상을 가지고 규율을 준수할 것을 가르쳤다. 일루미나 대원수는 일루미나의 모든 사람에게 봄처럼 따뜻한 빛과 사랑을 퍼뜨린다. 또한 일루미나 연방을 적대하는 모든 사람은 일루미나의 강력한 무력 앞에 사라질 것이다.\n만약 당신의 인생에 신앙과 우상이 필요하다면, 의심할 여지 없이 일루미나 대원수가 최고의 선택이다.\n\n2. 여명의 빛을 위하여 한 점 부끄러움 없이 책임을 다하라.\n암귀의 침략에 대항하는 최전선의 일원으로서, 옛 문명의 발굴자와 보호자로서, 일루미나 연방의 사병 모두 반드시 자신이 맡은 무거운 짐을 알고 있어야 한다.\n1) 오로리안의 생존을 위협하는 모든 암귀를 제거한다.\n2) 가능한 옛 문명의 과학 기술을 발굴해 연구, 이용하고 기술 혁신을 추진한다.\n3) 최종적으로 오로리안의 영광과 이 대륙의 번영을 재현한다.\n\n3. 영광과 정의를 품어라.\n일루미나 연방이 다른 세력과 가장 다른 점은 우리가 모든 오로리안을 위해 전투하는 영광을 짊어졌으며, 선악이 분명한 정의도 품고 있다는 것이다. 이 신조가 제대로 구현되도록 만드는 것은 네메시스 감찰관이 이끄는 헌병부대이다.\n그들은 일루미나 연방군 군기의 감시자이자 일루미나 연방 신앙의 수호자이다. 만약 네메시스 감찰관이 당신에게 의심의 눈길을 보낸다면 원칙주의자인 정의 집행자를 자극하지 말고 순순히 검사를 받을 것을 권하는 바이다. 물론, 당신이 정의의 수호자이고 감찰관의 도움에 감사를 표한다면 당신도 정의의 파트너가 될 수 있다.",
  str_dispatch_book_chaptercont_10000_2 = "1. 복종하되 모든 사람은 평등하다.\n계급과 직위로 일루미나 연방에서는 리더와 부하의 관계가 결정되지만, 이것이 리더가 계층 특권을 가지고 있다는 뜻은 아니다! 이것 또한 백야와 일루미나 연방의 가장 본질적인 차이이다. 일루미나 연방에서 「모든 사람은 평등하다」라는 것은 가장 중요한 규율이다! 모든 일루미나인은 당신의 전우이자 가족이기도 하다. 당신의 신분과 무관하게 일루미나 연방의 가치관을 인정하기만 한다면 검증을 통해 일루미나 연방의 중요한 일원이 될 수 있다!\n\n2. 시시각각 경계하고 장비를 언제든 사용할 수 있도록 정비하라.\n모든 일루미나 연방의 병사는 반드시 언제라도 자신의 장비를 사용할 수 있도록 해야 한다. 단순히 매일 에너지총을 보수하는 것뿐만 아니라, 수시로 메카의 상태를 살피고, 검을 예리하게 유지해야 한다. 이는 단순히 자난성이 암귀에 대항하는 핵심 역량이기 때문에 언제 닥칠지 모르는 암귀 대군을 상대하기 위해서뿐만은 아니며, 그보다 교관에게 당신의 장비가 제대로 정비되어 있지 않은 것을 들킨다면 무수한 암귀에게 둘러싸인 것보다 더 공포스러운 특훈을 해야 하기 때문이다.\n\n3. 기술이 우선이다.\n최초의 자난 군과 민간인은 백야성의 명령으로 이주한 평민 및 오로리안, 아인족 모두의 혼혈 후손이었다. 최초의 백야성 통치자는 이곳을 암귀를 끌어들이기 위한 미끼로 삼고 극히 제한적인 지원만 제공했다. 그때의 자난성의 군인은 백야성, 극한의 환경 및 암귀로부터의 수많은 시련을 직면하고 있었다.\n그 열악한 환경에서 우리는 결코 물러나지 않았고, 수많은 과학자의 끊임없는 노력과 헌신으로 자난 지하성에 남아있는 옛 문명 기술과 루미나틱스를 결합하여 암귀에게 저항할 수 있는 루미나 과학 장비를 만들어 냈다. 오늘날 자난성은 과학 기술과 공업 방면으로는 이미 다른 세력을 압도하고 있으며, 백야성의 첨단 기술과도 견주어봐도 손색이 없다.\n그렇기 때문에 과학자들은 자난성에서 존경받는 존재이다. 특별한 상황이 닥쳤을 때 일루미나 연방 병사들은 반드시 과학 연구원과 평민을 먼저 보호해야 한다. 극단적인 상황에서는 과학 연구원과 중요한 기술 장비 보호가 최우선이 될 수도 있다.",
  str_dispatch_book_chaptercont_10000_3 = "1. 군이 우선이다. \n「자난성」을 지하 피난소로 여기지 말고 요새로 여겨라. 대륙의 암귀 대항 기지로서, 이곳은 군사 활동이 정상적으로 돌아가는 것을 가장 우선으로 삼아야 한다. 「자난성」을 모범으로 삼고 모든 일루미나도 이 이념을 고수해야 한다. 모든 일은 군의 일을 우선으로 한다. 만약 내정, 민생, 외교, 연구 등 방면에서 어떤 일이 군의 일과 충돌한다면, 무조건 군사 행동을 우선시해야 한다.\n\n2. 과학을 존중하라.\n명심하라. 「자난성」이 암귀에 포위당했을 때 우릴 구해줄 사람은 없다. 이곳에 남겨진 지식을 연구하는 것만이 오로리안의 전투력을 대폭 높일 방법이다. 바로 「루미나 기술」로 말이다.\n과학이 있었기에 암귀를 물리칠 수 있었다. 「자난성」의 조건을 개선하고, 과학 기술로 우리의 병사를 무장시키고 시민을 양육해라. 과학은 우리가 고대의 혼돈과 우매함을 물리칠 무기이니, 과학의 이성과 실용 정신은 우리를 최종 목표로 인도할 것이다.\n\n3. 집단주의.\n「화살 한 발은 꺾기 쉽지만, 세 발은 어렵다.」 우리는 사회적인 종족이다. 혼자 살아갈 수 있는 인간은 없다. 열악한 환경 속에서 의지할 수 있는 건 집단뿐이다. 집단만이 당신이 기댈 수 있는 것이다. 낯선 마을을 홀로 걸을 때 당신을 보호할 수 있는 것은 일루미나 연방이라는 거대한 집단이다. 그러니 집단이 당신에게 무엇을 해줄 수 있는지 묻지 말고, 먼저 자신에게 집단을 위해 무엇을 할지 물어라.\n\n4. 이성과 실용.\n우리는 감정적인 생물이지만, 우리의 생존을 지지하는 건 실질적인 물질이다. 그러므로 우리는 현실을 포기하고 허구를 쫓을 수 없다. 과학은 일루미나를 있게 만든 기초, 그리고 과학의 전제는 이성이다. 근거 없는 추측, 우매한 미신, 거만한 망상은 모두 이성의 천적이다. 그것은 사람을 심연으로 이끌 뿐, 오직 이성만이 우리를 항상 깨어있게 하고 현실을 마주하게 할 것이다.",
  str_dispatch_book_chaptercont_10000_4 = "1. 일루미나 연방의 이익을 지켜라.\n과거의 세월 속에서 일루미나 연방은 암귀와의 전쟁에서 항상 최전선을 지켰다. 일루미나 연방은 오로리안을 이끌고 암귀를 물리쳐 결국 대륙에 영원한 평화를 가져올 것이다. 이 최종 목표를 실현하기 위해 연방의 힘을 키우는 것은 당연하다. 그러므로 모든 구성원은 일루미나 연방의 이익을 지킬 의무가 있다. 특히 핵심 이익과 관련된 일은 결코 물러서선 안 된다.\n\n2. 군사 이익을 지켜라.\n「진리는 오직 군사 타격의 유효 범위 안에 있다.」 눈앞의 평화에 눈이 멀어선 안 된다. 이 대륙에서 국가 간의 주종 관계는 군사력으로 결정된다. 일루미나 연방은 군대를 시작으로 연방의 수많은 도시의 관계를 지켰다. 그러므로 반드시 강대한 군사력을 지닌 국가를 경계해야 한다. 지금의 태도가 어떻든 그 국가는 반드시 연방의 위협이 될 것이니, 언제든 군사의 이익과 관련된 일은 직접적이든 간접적이든 반드시 지켜야 한다. 물론 그것은 첫 번째 규칙과 충돌되지 않는 전제하에 지켜져야 한다.\n\n3. 「자난성」의 이익을 지켜라.\n「자난성」은 일루미나 연방의 핵심이자 마지막 방어선이다. 또한 암귀에 대항하는 마지막 기지이다. 「자난성」을 지키고 보호하고 발전시키는 것은 모든 일루미나인이 항상 명심해야 할 신조이다. 물론 그것은 첫 번째와 두 번째 규칙과 충돌하지 않아야 한다.\n\n4. 연구 단체의 이익을 지켜라.\n기술을 발전시키고 과학 원리를 연구하는 것은 당연히 능력 있는 연구 단체가 하는 일이다. 고등교육을 받은 구성원으로서 모든 연구원의 생명은 매우 귀중하다. 1번부터 3번까지의 규칙과 충돌하지 않는다는 전제 하에 연구 단체의 이익을 가장 우선시해야 할 것이다. 같은 부서가 아니더라도 일루미나인은 필요하다면 연구원의 명령을 따라 특수 임무를 집행해야 한다.\n\n5. 집단의 이익을 지켜라.\n조건이 허락한다면 모든 일루미나인은 집단으로 행동해야 한다. 그것이 임시로 만들어진 집단이라도 말이다. 앞선 네 개의 규칙을 위배하지 않는다는 전제 하에 집단의 이익은 개인의 이익 보다 우선시되어야 한다.",
  str_dispatch_book_chaptercont_10000_5 = "1. 시간을 준수하라.\n일루미나인은 반드시 시간개념이 투철해야 한다. 일상생활에서 크고 작은 일은 모두 계획에 따라 연결되어 있다. 당신이 늦는다면 다른 이의 일이 늦어지니, 어떤 상황에서도 시간은 반드시 지켜야 한다.\n\n2. 솔직하고 성실하라.\n일루미나 연방에서 거짓은 살아남을 수 없다. 어떤 목적이든 거짓을 고한다면 진실은 반드시 누군가를 해치고 단체에 손해를 입히며, 더 나아가 돌이킬 수 없는 결과를 낳을 것이다. 항상 성실하고 솔직하라. 이것은 모든 일루미나인이 반드시 지켜야 할 조례이다.\n\n3. 지휘에 따르라.\n모든 일루미나인은 반드시 지휘에 따라야 한다. 두 팔이 대뇌의 명령을 따르는 것처럼 말이다. 상사의 결정은 반드시 이행해야 하고, 가감하거나 거절해서는, 특히 위반해서는 절대 안 된다.\n\n4. 지식을 탐구하라.\n과학과 지식에 끝은 없다. 일루미나 연방은 항상 과학 기술에 혁명을 일으키고 있다. 모든 일루미나인은 새로운 지식을 탐구하며 새로운 환경에 적응해야 한다. 배움이나 능력이 부족하다고 걱정할 것 없다. 항상 공부하는 사람은 이미 훌륭한 일루미나인이다.\n\n5. 끝없이 단련하라.\n모든 일루미나인의 신체는 자신의 것이 아닌 연방의 것이다. 그러므로 건강을 유지하는 것은 일루미나 연방의 이익을 지키는 것이다. 합리적인 단련을 유지해 신체를 강화하라. 무의미한 향락에 빠지지 말라. 이것은 모든 일루미나인이 항상 명심해야 할 규칙이다.",
  str_dispatch_book_chaptercont_11000_1 = "아이다는 꿈을 자주 꿨다. 꿈을 뒤덮은 비단을 살며시 걷으면 가느다란 두 그림자를 볼 수 있었다.\n그들은 품 안의 아이를 조심히 요람에 눕혔다. 바람이 창으로 들어와 그들의 그림자를 흔들었다. 그리곤 짧은 한마디만이 남았다. 「아빠와 엄마는 떠날 거란다. 바깥세상으로 말이야.」\n아이다가 자라날수록 꿈은 점점 더 명확해졌다. 그녀는 엄마의 부드러운 갈색 머릿결과 푸른빛을 띄는 아빠의 턱을 볼 수 있었다. 그들은 매번 그렇게 매정하게 떠났다. 떠날 때 그들의 모습은 기묘한 빛 속으로 녹아들었는데, 아이다는 그 빛이 익숙했다. 고개를 들어 밤하늘을 보면 알 수 있었다. 그것은 오로라의 색이었다.\n「바깥세상은 어떤 모습일까? 나도 부모님처럼 콜로서스를 다룰 수 있으면 헤븐즈 밸리를 떠날 수 있을까?」 아이다는 기대했다.\n어느 날, 그녀는 소원에 대한 답을 얻었다. 그녀는 헤븐즈 밸리 깊숙한 곳에서 어떤 음성을 들었다.\n「콜로서스는 하늘을 위해 태어난 거야. 육지형도, 해양형도 있지만, 하늘만이 콜로서스의 고향인 거지!」\n「몸집만 큰 그 콜로서스들은 멍청해. 날개만 휘두르면 높이 날아오를 수 있는데, 늘 헤븐즈 밸리 주변만을 배회하고 아무런 야심도 없어. 나라면, 나라면 오로라의 끝까지 날아오를 텐데! 부...부럽다는 건 아니야...」\n「좋겠다... 조종사가 있다는 건 대체 어떤 기분일까...」\n「조종사가 있다는 건, 친구가 생긴 기분일 거야」 아이다가 살며시 대답했다.\n「깜짝이야! 누구야?! 어떻게 나랑 대화할 수 있는 거지...」 협곡 깊숙이 세워져 있는 조그마한 콜로서스는 깜짝 놀라며 지시등을 깜빡거렸다. 「설마 유령이야?! 헤븐즈 밸리의 괴담?! 아이테르가 이런 낡아빠진 콜로서스한테 올 리가 없어. 너무 이상하잖아.」\n「그치만 네 앞에 있는 건 아이테르인걸.」 아이다는 가볍게 꼬마 용처럼 생긴 콜로서스의 머리 위로 뛰어올랐다. 발밑에 전해지는 그 신기한 감촉에 그녀는 발밑을 밟고 또 밟았다.\n「야야야, 아이테르면 남의 말을 몰래 엿듣고 초면부터 막 남의 머리를 짓밟아도 되는 거야? 내 아름다운 머리는 아무나 만져도 되는 게 아니라고.」\n「응, 정말 예뻐. 게다가 예쁜 꽃도 피어 있어.」\n「...그야 내가 원래 귀여우니까... 그래서 아이테르, 갑자기 나한테 말을 건 이유가 뭐야? 장난치는 거라면 난 마지막 숨까지 다 뽑아내서 널 하늘로 날려버릴 거야.」\n「너도 하늘로 날아오르고 싶은 거지?」 아이다는 눈앞의 콜로서스에게 요청을 보냈다. 「난 항상 헤븐즈 밸리 밖으로 나가고 싶었어. 나랑 같이 갈래?」\n하지만 콜로서스는 그 요청을 받아들이지 않았다. 그저 조용히 뒤로 웅크릴 뿐이었다.\n「가고는 싶지만, 난 몸집도 작고, 저장 공간도 작고, 날개도 작아서... 날아오를 능력이 없어... 난 안 될 거야...」\n「하지만 가고 싶잖아.」 아이다는 콜로서스에게 손을 뻗었다. 그 순간 어떤 신비로운 감각이 아이다와 콜로서스를 하나로 연결했다. 그것은 「감응」이었다.\n콜로서스는 자신의 날개가 움직이며 높이 날아오르는 것을 느꼈다. 마치 수면을 뛰쳐 오른 돌고래가 마침내 해수면 위의 세상을 본 것처럼, 그들은 바람을 타고 하늘 높이 올라 별과 오로라에 닿았다.\n광활한 세계가 그들 앞에 서서히 펼쳐졌다.\n「음, 내 이름은 아이다야. 넌 이름이 뭐야?」\n「하늘로 올라 바람을 타고 난다는 뜻에서 윈드러너야.」",
  str_dispatch_book_chaptercont_11000_2 = "낡디 낡은 윈드러너와 초보 조종사 아이다는 정처 없이 하늘에서 표류했다. 상승기류에 뒤집어지고 에너지까지 소진되어 결국 긴급착륙을 할 수밖에 없었다.\n「아, 아무런 준비도 없이 여행을 시작한 결과는 역시 이건가. 완전히 흙에 파묻혔네... 난 역시 비행에 능력이 없어! 아니... 잠깐만, 너도 조종 완전 못하잖아!」 윈드러너는 의식의 연결을 통해 아이다에게 말했다.\n아이다는 머리에 난 혹을 매만졌다. 방금 뒤집어질 때 조종대에 부딪힌 것이다. 그녀는 머리 오른쪽이 아직도 지끈거렸지만 개의치 않는 표정이었다. 「나 원래 이런 거 못 해. 콜로서스 감응 수업은 하나도 못 들었거든. 보호자가 없어서.」\n「뭐, 뭐라고? 그럼 대체 무슨 용기로 나랑 감응한 건데!」\n「음... 느낌으로」 그녀는 가볍게 일어서며 말했다. 「하지만 날 믿어. 왠지 나 이거 잘할 수 있을 거 같아.」\n「나보다 나르시시즘이 더 심한 녀석이 있을 줄이야. 매력적이긴 하지만... 그래도 나 이제 안 날아. 차라리 흙 안에 파묻혀 있지 더는 공중에서 그 난리는 안 칠 거야. 그냥 콜로서스 정거장에 얌전히 있는 거였는데, 어쩌자고 이런 요상한 곳에 와서는... 여긴 뭔가 음습해! 이상한 버섯도 있고...」\n「게다가 불청객도 있는 거 같아」\n사방팔방에서 무기를 든 「동물」들이 아이다를 향해 달려왔다.\n윈드러너는 눈을 꽉 감았다. 싸울 수 없는 아이테르란 말린 새우처럼 나약하니, 아이다는 이 무시무시한 생물에게 갈기갈기 찢길 것이다! 몸속 「루미나」가 움찔거렸다. 문제는 마치 거품처럼 기계 통로에서 퍼져나갔다. 윈드러너는 겁쟁이였다. 제대로 날지도, 자신의 조종사를 돕지도, 심지어 조종사가 위험에 처했는데도 두 눈을 뜨지 못했다. 울고 싶었다. 하지만 콜로서스라는 기계도 눈물을 흘릴 수 있을까?\n그런데 아이다의 목소리가 전해져왔다. 「두려워하지 마, 윈드러너, 문제는 해결됐어. 우린 누구도 다치지 않아.」\n윈드러너가 눈을 떴을 때, 어떤 광경이 그 앞에 펼쳐졌다. 아이다는 품 안에 고양이를 품고 있었고, 그녀의 발 주변엔 다양한 꼬마 동물들이 누워있었다.\n「아이테르는 싸움을 못한다지만, 난 싸움 엄청 잘해. 녀석들이 달려들 때 내가 때려 눕히고 하얀 배를 어루만졌거든. 역시 꼬마 동물들은 이런 거에 약하다니까」\n그러자 아이다 품 안의 고양이가 말했다.\n「무례하군. 우린 꼬마 동물이 아니라 아인이다! 너희는 좀 전에 이곳에서 가장 진귀한 진주 버섯을 짓밟았으니 이론상으론 1000만 골드는 배상해야 하지만, 안마 기술이 나쁘지 않으니... 노동으로 갚는 걸 허락해 주지!」\n「아인?」 아이다는 의혹스런 눈빛으로 품 안의 고양이를 바라봤다.\n「냐옹, 세상 물정 모르는 것. 빛의 통로를 볼 수 있는 건 아이테르고, 빛의 통로를 보진 못해도 빛의 힘을 쓸 수 있는 건 오로리안이다.」 고양이는 기지개를 켰다.\n「그럼 아인은?」\n「아인은 언어로 소통하고 강력한 신체를 지녔지. 빛이랑은 별 인연이 없지만... 그래, 거기 좀 더 긁어 봐. 응, 우리의 가장 큰 장점은...」\n「귀여운 거다냥」",
  str_dispatch_book_chaptercont_11000_3 = "목표 없는 여행은 마치 민들레 풀씨처럼 바람이 부는 대로 날아가 뿌리를 내린다.\n아이다와 윈드러너가 이번에 발을 내딘 곳은 황무지였다. 그곳에서 헤븐즈 밸리의 동포, 꽃으로 뒤덮인 콜로서스를 만났다.\n「숨이 곧 끊어질 것 같아. 에너지도 곧 소진될 것 같고.」 아이다는 오래된 콜로서스를 부드럽게 어루만졌다. 콜로서스는 가볍게 떨며 마치 아이테르처럼 숨을 내쉬었다.\n「어, 어쩌다 이렇게 된 거야? 왜 날아가지 않았어? 헤븐즈 밸리로 돌아가면 분명 회복할 방법이 있었을 텐데.」 윈드러너는 이해할 수 없었다.\n「그건, 내가 헤븐즈 밸리로 돌아가는 길을 잃어버렸기 때문이란다. 지도도 위성도 나를 미망 속에서 구해낼 수 없었지...」 꽃으로 가득한 콜로서스는 천천히 눈을 떴다.\n「이야기를 들려줘도 되겠니?」\n거대한 콜로서스는 고개를 들었다. 「난 내 조종사와 함께 이 숲에 도착했다. 이곳에서 우리는 아이테르와는 다른 종족, 오로리안을 만나게 됐지.」\n「아, 그 빛의 힘을 사용하는 종족! 머리를 움직이면 손바닥에서 물을 뿜을 수 있다던데.」\n「흥, 그게 뭐라고. 걔들이 날 수나 있대? 놀라려면 콜로서스의 위대함에 먼저 놀라야지.」 윈드러너는 뾰로통하게 오로리안을 무시했다.\n「나의 조종사는 오로리안과 함께 생활했단다. 그들은 그를 받아들였지만, 그럼에도 그는 외로웠지. 오로리안과 아이테르는 달랐고, 여긴 그의 집이 아니었다. 그리고 그가 이곳을 떠나려 할 때, 암귀가 오로리안의 마을을 습격했다.」\n「암귀!」 아이다의 마음이 흔들렸다. 순간 그녀의 눈에서 서늘한 그림자가 비쳤다. 시커먼 괴물들은 어둠 속에서 모습을 드러내 이빨과 발톱을 휘두르며 온몸에 피칠갑을 한 채 아이다를 향해 달려들었다. 그 날카로운 발톱이 그녀의 목을 가르는 순간 영상은 중단됐다.\n「내 조종사는 이곳의 오로리안을 돕기 위해 자신의 목숨을 바쳤다. 그들은 끝내 비참한 승리를 거둬냈지만, 암귀에 의해 오염된 이곳은 더는 살 수 없는 곳이 되었단다. 모든 것이 끝난 후 조종사가 보호했던 오로리안이 이곳에 돌아와 나의 조종사에게 꽃을 바쳤다. 그 꽃들은 내 몸에 뿌리를 내려 조금씩 자라났지.」\n아이다와 윈드러너는 침묵했다. 죽어가는 콜로서스를 위로하고 싶었지만 무슨 말을 해야 할지 알 수 없었다.\n「괴로워하지 말거라, 아이들아. 난 이 꽃들을 싫어한 적이 없다. 이곳에서 에너지가 소진될 날을 기다리는 것도 후회하지 않는다. 내 안에서 무한한 생명이 깨어나는 걸 느낄 수 있기 때문이란다. 이 찬란한 꽃의 바다는 그들이 나의 조종사에게 보내는 감사 인사이자 제전이니까.」\n콜로서스는 결국 눈을 감고 아이다와의 감응을 끊었다.\n폐허 속에 오직 꽃의 바다만이 흔들거렸다. 아이다는 부모님과 헤븐즈 밸리를 떠올렸다. 그녀는 중얼거렸다. 「바깥세상으로 나갔던 게 정말 옳은 일일까? 바깥세상으로 나서는 건 정말... 잘못된 걸까?」",
  str_dispatch_book_chaptercont_11000_4 = "「모래, 온통 모래뿐이야. 여기에 정박했다간 내 껍데기가 다 모래로 뒤덮일 거야... 씁, 모래가 뜨겁기까지 해.」\n아이다와 윈드러너는 어느 사막으로 날아와 그곳에 정박했다.\n「고생했어, 윈드러너. 저 앞을 봐. 다 네 덕분이야!」\n뜨거운 태양이 하늘에 걸려 공기를 태우고 있다. 모래 언덕은 울퉁불퉁하게 멀리 펼쳐졌다. 아무리 콜로서스라도 사막에선 그저 작은 흰색 돌에 불과했다. 만약 헤븐즈 밸리를 떠나지 않았다면 이런 광경은 평생 볼 수 없었으리라.\n「나 덕분에... 그, 그렇지! 난 정말 대단한 콜로서스라니까! 사막은 이렇게 생겼구나! 근데 주변에 사람 한 명 없네.」\n「근데 저 멀리 뭐가 있는데?」\n조용하던 사막이 들썩거렸다.\n「어... 선박인가? 우릴 향해 달려오고 있어! 부딪힌다!」\n불쌍한 윈드러너는 여정을 시작한 뒤로 평안한 날이 없었다. 오늘도 역시나 사막을 달리는 선박과 부딪히고 말았다.\n「아파!」 윈드러너는 소리쳤다. 배는 묵직하게 그녀의 날개에 부딪혔다.\n선박의 주인은 머리를 감싸며 비틀비틀 배에서 걸어 나왔다.\n「안녕하세요. 아이고, 좀 전에 충돌은 정말이지... 전 별의 여단 단장입니다. 잘 부탁해요. 우리는 유랑 오로리안으로 배를 타고 도처를 돌아다니며 세상의 비밀을 탐색하고 있죠.」\n「자료에서 배는 다 바다에서 다닌다고 했는데... 사막에도 배가 있네요?」 아이다는 의혹을 품은 눈으로 함장을 봤다.\n「사막엔 당연히 배가 없지만 여기엔 있습니다. 보세요.」\n아이다는 단장의 손끝을 따라 고개를 숙였다. 그녀의 발밑 모래가 바람에 날아가자 완벽한 「하늘」이 나타났다. 더 신기한 것은 그 하늘에서 기묘한 천체를 봤다는 것이다.\n「이곳이 바로 우리의 세계, 아이올리아입니다.」 별의 여단의 단장은 말했다.\n「마치 물에 불어 흩어진 과자 같아.」 윈드러너가 조용히 말했다.\n「그렇죠? 그 과자는 바로 여러분의 아스트라입니다. 이 기묘한 세계는 한쪽은 영원한 백야이고, 다른 한쪽은 끝없는 극야죠. 우리는 그 얇은 틈에서 살아가고 있죠.」\n「세상의 비밀을 탐색하기엔 배가 너무 낡지 않았나요?」\n여단장은 머리를 긁으며 말했다. 「겉은 낡았어도 안은 상당히 호화롭습니다. 게다가 저희 선원들은 아주 우수하죠. 이 수리공을 보세요.」 배에서 오로리안이 망치를 휘둘렀다. 뭔가를 보여주려는 거 같았는데 되려 구멍 하나를 만들고 말았다. 다른 오로리안은 멋지게 배에서 뛰어내리고 싶었던 거 같은데, 그만 머리를 모래 속에 파묻고 말았다.\n「아우, 창피해.」 단장은 절망적으로 고개를 들었지만, 빠르게 감정을 가다듬었다. 「새로운 길을 개척하고 미지를 탐색하는 게 저희가 하는 일입니다.」\n「오로리안은 원래 다 이렇게 이상한가요?」\n「머리가 정상적으로 박혔다면 모래에서 배를 몰진 않겠죠.」\n「모래?」 아이다는 고개를 숙였다. 발밑의 은하수는 어느새 다시 모래에 파묻혀 있었고, 다시 고개를 들었을 땐 그 배조차 사라지고 없었다.\n과연 별의 여단은 꿈이었을까 현실이었을까?",
  str_dispatch_book_chaptercont_11000_5 = "아이다는 아주라이트의 가장자리에 앉았고 윈드러너는 구름 안에 몸을 숨겼다.\n어느새 시간은 흘러 헤븐즈 밸리를 떠난 지도 한참이 되었다. 하루, 한 달, 일 년, 어쩌면 몇 년일지도 모른다. 헤븐즈 밸리의 모습은 아이다의 기억에서 점점 흐려져 갔다.\n「윈드러너, 헤븐즈 밸리의 모습 아직 기억해?」\n「난 콜로서스니까 당연히 뭐든 기억하지. 어디 보자... 어라, 이상하네... 헤븐즈 밸리의 자료가 전부 없어졌어? 설마 저장 공간에 새로운 정보가 너무 많아서 전부 덮어 씌워진 건가? 말도 안 돼... 내 저장 공간이 그렇게 작을 리가 없는데...」\n「거기에 높은 흰색 탑이 있었는데, 아주라이트에도 흰색 높은 건물이 있지만 느낌은 달랐어. 헤븐즈 밸리의 흰색 탑 위에는 항상 새들이 앉아 있었고 그 아래는 숲이었어. 지면에는 민들레가 흩날렸지.」\n「...아이다, 그때 왜 나랑 감응해서 헤븐즈 밸리를 떠나려고 한 거야?」 윈드러너는 아이다의 시선을 따라 먼 곳을 바라봤다. 사막, 평원, 설원, 화산, 심지어는 바다까지. 이곳에서 희미하게나마 전부 보이는 것 같았다. 만약 헤븐즈 밸리를 떠나지 않았다면 볼 수 없었던 것들. 하지만 헤븐즈 밸리를 떠나서인지 머릿속엔 그것들만 남았다.\n「그땐 꿈속의 두 사람을 찾고만 싶었어... 내 부모님 말이야. 난... 보기엔 소탈해 보이지만, 사실 헤븐즈 밸리에서의 생활에 질려있었어. 어딜 가도 그곳에 있는 것보단 나을 것 같았거든. 부모님도 날 버리고 밸리를 떠났고, 다른 사람들과 어울리지도 못하고 매일 혼자만 있다보니 질려버린 거지.」\n「...나도 그랬어. 깨어났을 때부터 난 불완전한 콜로서스였으니까. 내가 실패작이랬어. 영원히 날지 못하는. 내 마지막은 콜로서스의 쓰레기장에서 에너지가 소진될 날을 기다리는 거였지. 하지만 이상해. 나 지금 그 엉망진창인 곳이 엄청 그리워...」\n「나도 그래... 언제부턴진 모르겠는데, 부모님을 더 찾지 않았던 거 같아. 자기 생활을 살고 계실 테니까, 나도 내 생활을 가지려고. 너랑 같이 하늘을 나는 게 그 허무맹랑한 걸 찾는 것보다 훨씬 재밌으니까.」\n「너, 너너너 지금 고백하는 거야? 나 마음의 준비가 안 됐는데... 근데 난 콜로서슨데? 콜로서스가 아이테르의 고백을 받아도 되는 건가? 와, 내 자료 중에 이런 정보는 없었는데!」\n「고백이란 표현도 너무 얕아. 우린 영혼이 연결된 파트너잖아. 뭔가 더 깊은 관계라고 생각해.」 아이다는 눈을 감고 자신의 감응을 조종했다. 「느껴져?」\n「...느, 느껴져. 네 생각도 느껴져, 아이다. 너는...」\n「헤븐즈 밸리. 내 생각엔, 우리가 만났던 곳으로 되돌아갈 때가 온 거 같아...」\n그 기억들이 떠나가기 전에.",
  str_dispatch_book_chaptercont_12000_1 = "나는 골드리버 강가에 앉아서 태양이 천천히 움직이는 것을 자주 보곤 했다.\n차가운 물이 내 다리에 부딪히면 위가 떨리는 것이 느껴졌다. 시프의 아버지는 강에서 물고기를 잡았고, 어망은 위험한 곳을 들락거렸다. 시프의 아버지는 우리를 향해 웃을 때 손을 등 뒤에 숨기곤 했지만, 손바닥에는 갈색 피딱지가 생겨있다는 것을 알고 있었다.\n시프는 맨발로 강을 미친 듯이 뛰었다. 시프는 작은 조개를 주워 내 옆에 쌓고는 칼로 조개를 까라고 시켰다. 그리곤 다시 강을 건너며 자갈 때문에 생긴 발바닥 상처를 씻어냈다.\n햇빛은 끝없이 우리를 비춘다.\n하루 중 가장 견디기 힘든 순간은 시프네 집에서 밥을 먹을 때였다. 나는 시프보다 빠르거나 느리게 식사를 끝내지 않도록 항상 식사 속도를 조절했다. 하지만 어떻게 해도 나는 매너가 없다고 느껴졌다.\n시프의 어머니는 인정이 많으셔서 항상 말린 생선이나 훈제 고기 같은 먹을 것을 가지고 가서 종일 술에 취한 아버지에게 가지고 가라고 하셨다.\n\"미나의 어머니가 살아 있었으면 좋았을 것을...\"\n시프의 어머니는 항상 내 헝클어진 머리를 손가락으로 넘겨주셨다. 피로에 찌든 눈빛으로 나를 바라보는 시프의 어머니는 나를 통해 다른 사람을 보는 것 같았다.\n나와 시프처럼 어머니는 시프 어머니와 사이가 좋으셨을 것이다.\n나와 아버지는 어머니가 남기신 온정에 기대어 세상을 살아가고 있었다.\n아버지는 자신이 술 마시는 것을 내가 보게 될까 봐 두려워하셨다. 내가 집에 들어갈 때면 그는 항상 내게서 떨어져 있었지만, 공기에 퍼져 있는 술 냄새는 감출 수 없었다. 아버지는 음식을 삐걱거리는 식탁에 올려두고 빨래를 하라고 큰소리로 지시했다. 내가 잠들면 숨겨둔 술병을 찾기 시작하겠지...\n침대 밑, 옷더미, 난로 잿더미 속... 나는 생각지도 못한 곳에서 술병을 찾아내곤 했다.\n나는 강물에 병을 깨끗이 씻고, 어망 밧줄로 10개의 병 주둥이를 이어서 꽁꽁 묶었다. 그런 후 침실 창문 좌우에 못을 박고 묶은 술병이 하늘을 향하도록 매달았다. 술병마다 하얗고 밝은 태양이 맺혀있고, 유리가 부딪칠 때마다 쨍그랑하는 소리가 났다.\n그날이 오기 전까지 이게 나의 유일한 즐거움이었다.\n(계속)",
  str_dispatch_book_chaptercont_12000_2 = "그날은 흐린 날이었다. 살랑살랑 불어오는 바람에 일어난 낙엽과 먼지가 하늘을 빙빙 돌았다.\n말의 방울 소리가 멀리서 울려왔다. 아이들이 엎드려 귀를 땅에 대보니 이따금 말발굽 소리가 들렸다. 상단이었다. 그들은 마을 밖의 풀이 있는 공터에 멈춰서고는 하얀 천을 펼쳐 그늘이 있는 기다란 공간을 만들었다. 그리곤 말 위에 달려있던 모든 물건을 내려 공간에 늘어세웠다.\n소식을 들은 수많은 마을 사람들이 상단이 쉬는 공터로 가서 목을 길게 빼고 두리번거렸다. 나와 시프도 그 무리 속에 끼어 있었다. 시프는 내 손을 꽉 쥐었고, 긴장과 흥분이 내 피와 뼈를 거쳐 심장으로 퍼졌다.\n공기 속에 말린 말똥 냄새가 퍼졌다. 상단에서 사람이 나오더니 몇몇 대담하고 젊은 오로리안과 이야기를 나눴다. 그들의 옷차림은 매우 산뜻했다. 먼 거리를 돌아다님에도 불구하고 얼굴은 여전히 깨끗하고 생기가 넘쳤다. 그때는 그것이 루미나틱스 덕분인지 몰랐다.\n마을 사람들 사이로 사료용 콩, 밀기울, 모직물, 사슴뿔 등의 물건으로 옷과 맥주를 교환할 수 있다는 소식이 빠르게 퍼졌다. 상단의 사람이 마을로 들어가자 반년 동안 열지 못했던 여관도 손님을 맞이하게 되었다. 얼마 지나지 않아 여관에서 완두콩 삶는 냄새가 퍼지기 시작했다. \n옷을 판다는 상인은 옷을 팔에 걸치고는 옷감을 펼쳐서 구경하는 마을 사람들에게 보여주었다. 베이지, 피콕 그린, 사파이어 블루, 선셋 레드... 이렇게 찬란한 색깔은 태어나서 처음 보았다.\n시프는 지난겨울에 사냥했던 늑대 가죽을 분홍색 긴 치마로 바꾸고 싶다고 했다.\n난 창문에 걸어둔 내 유리 술병이 생각났다.\n\"어쨌든 시도라도 해보자\" 나는 조용히 나 자신에게 말했다.",
  str_dispatch_book_chaptercont_12000_3 = "나와 시프는 각자의 집으로 돌아갔다. 시프는 늑대 가죽을 돌돌 말아 겨드랑이에 끼웠고, 나는 걸려있던 병을 두 손으로 들었다. 내가 움직이자 술병이 부딪히며 쨍그랑쨍그랑하는 즐거운 소리가 울렸다. 우리가 손에 쥐고 있는 것은 서로가 애지중지하는 물건이었다.\n시프는 거의 상단 쪽으로 돌진하는 듯이 빠르게 걸어갔다. 하지만 술병은 무겁고 깨지기 쉬워서 나는 천천히 따라갈 수밖에 없었다. 사람들의 시선이 따라오는 것을 느꼈다. 이렇게 많은 사람의 주목을 받아본 건 처음이어서 마음속 한편으론 정말 기뻤다.\n\"이걸로 뭘 바꾸려는 거니?\" 상인 앞에 이르자 상인은 곤혹스러운 얼굴로 나를 살펴보았다.\n나는 상인의 말뜻은 알아듣지 못하고, 그저 있는 힘껏 목을 길게 빼고 상인 뒤에 있는 물건을 훑어보았다.\n\"술병은 안 받는단다.\" 상인은 깔끔하게 설명하고는 끝에 말 한마디를 더했다. \"그건 그냥 평범한 술병이잖아?\"\n그 순간, 이명이 울리는 것 같았다. 거대한 난처함이 날 그 자리에 못 박았다. 머리 위에 태양은 북이 울리는 것처럼 울렸다. 손에 있는 술병의 쨍그랑거리는 소리는 내게 참을 수 없는 소리가 되어버렸다.\n술병이 너무 무거워 줄을 들었던 손이 떨리기 시작했다. 목과 귀에서도 땀이 나기 시작했지만 발은 말을 듣지 않았다. 한 걸음도 움직일 수가 없었다.\n그런데 돌연, 나지막한 목소리가 오른쪽에서 울려 퍼졌다.\n\"꼬마야, 병으로 뭘 바꾸고 싶니?\"\n(계속)",
  str_dispatch_book_chaptercont_12000_4 = "그것이 나와 세리오자의 첫 만남이었다. 그가 입은 은백색 판금 갑옷이 햇빛에 반사되어 눈부시도록 밝게 빛이 났다.\n30대 후반이었던 세리오자는 상단에 고용되어 상인과 재산을 보호하기 위해 동행했다. 투구를 벗자 갈색 이마에는 땀이 흘렀고, 고슴도치 같은 수염이 가득했다. 그가 나를 향해 웃자 수염 사이로 흰 치아가 보였다.\n세리오자는 내 손안에 있는 술병을 가리키며 '백야성 식빵'이라는 하얀 빵과 교환하자고 했다. 나는 치맛자락을 끌어 올려 식사 빵을 감쌌다. 그는 이 빵이 백야성 병사들의 전용 식량이라고 강조해서 말해주었다.\n'대단한 물건과 바꾼 게 분명해!' 그렇게 생각하자 아까 전까지 느꼈던 난처함은 깨끗이 사라졌다.\n그 후, 세리오자는 밧줄에 묶여 있던 술병 하나를 꺼내더니 손바닥에 쥐었다. 투명하면서도 비틀린 열기가 팽창하더니 병을 쥐고 있는 손을 뒤덮었다. 그 열은 태양보다도 뜨거웠다. 술병이 그의 손바닥에서 점점 수축하고 뒤틀리더니 다양한 모양으로 변했다.\n\"강아지를 좋아하니? 난 어렸을 때부터 정말 좋아했거든\"\n세리오자가 나를 향해 손바닥을 벌리자 투명한 유리 강아지가 쪼그리고 앉아있었다.\n난 유리 강아지보다 공중으로 피어오르는 뜨거운 물결이 더 마음에 들었다. 세리오자는 내가 관심이 있다는 사실을 알아차리고는 즐거워하며 말했다.\n\"이건 루미나틱스야. 배우고 싶니?\"\n상단은 이곳에 삼일간 머물렀다. 내 눈에는 마을 전체가 되살아난 것처럼 보였다. 밥 짓는 연기에는 고기 끓이는 냄새가 섞였고, 아이들은 맨발로 길을 쫓아다녔으며, 노인들도 지팡이를 짚고 어두운 집에서 나왔다. 골드리버의 물도 평소처럼 차갑지 않은 것 같았다. 세리오자는 항상 마을 중앙의 높은 단상에 앉아서 내게 루미나틱스를 알려주려고 했다. 시프는 내 곁에서 때로는 열심히 배우고, 때로는 내게 기대어 졸았다.\n세리오자는 밥을 먹은 후 마을을 돌아다니는 것을 좋아했다. 나와 시프는 세리오자의 뒤를 따라다녔다. 세리오자는 갑옷을 거의 벗지 않았고, 등에 메고 있는 방패와 검도 몸에서 떼어내는 일이 드물었다. 나는 뒤쫓아가서 무늬가 그려진 방패를 두드리며 이게 무엇이냐고 물었다.\n\"연 방패야\" 그가 말했다. \"백야성 기사단의 상징이지\"\n그 말로 나는 세리오자가 백야성 기사단에서 왔다는 것을 알았다.\n삼일 뒤, 상단이 마을을 떠났다. 세리오자도 우리에게 작별 인사를 했다.\n한 달 후, 마침내 내 손바닥에는 주먹만 한 물방울이 맺혔다.\n이때부터 나는 새로운 운명을 얻게 되었다.",
  str_dispatch_book_chaptercont_12000_5 = "세리오자가 떠난 지 석 달 만에 누군가 내 창문을 두드렸다.\n\"실례합니다. 여기가 미나 씨 집인가요?\"\n창문에는 벌겋게 달아오른 얼굴이 붙어 있었다. 백금발 머리를 양 갈래로 땋아서 뒷머리에 틀어 올린 그녀는 나를 보더니, 올리브 색 눈동자를 빠르게 두어 번 깜빡거리다가 또다시 고개를 가로저었다. 그리곤 뒤에 있는 배낭에서 갈색 가죽 표지의 소책자 한 권을 꺼냈다. 그녀의 등 뒤에는 초록색의 윤기가 나는 한 쌍의 날개가 태양 아래에서 빛나고 있었다. 그녀는 나를 향해 수첩을 들이밀고는 뾰족한 손가락으로 그 위에 걸려있는 휘장을 가리키더니 한 자 한 자 또박또박 말했다.\n\"쿠리어 길드입니다.\"\n쿠리어는 내가 자신이 찾는 사람이라는 것을 확인한 후, 방수 종이로 쌓인 소포를 쥐여주었다. 그리고는 두어 걸음 물러났다. 등 뒤의 날개가 갑자기 펴지더니 바람과 자갈들이 함께 휩쓸렸다. 그녀는 웃으며 나에게 손을 흔들었다. 날개를 가진 그녀는 공중에서 몇 바퀴를 돌더니 순식간에 나의 시야에서 사라져버렸다.\n소포를 열어보니 세리오자가 보낸 편지와 선물이 들어있었다. 편지는 아주 짧았는데, 나중에 글을 배우고 난 후에야 나는 그 편지의 글이 실수투성이였다는 것을 깨달았다. 선물은 민들레 표본이었다. 가느다란 줄기가 하얀 솜털을 받치고 있었고 육각형 기둥 모양의 투명한 나무 접착제에 둘러싸여 있었다. 나는 한참이 지난 후에 그 민들레가 머나먼 헤븐즈 밸리에서 왔다는 것을 알게 되었다.\n그 후로도, 세리오자는 계속해서 몇 개의 소포를 보내왔는데, 그 안에는 다양한 선물이 들어있었다. 북방의 소시지 구이와 베들레헴 여왕님의 모습으로 만든 작은 목조 조각상, 일루미나의 쌍성 로고가 새겨져 있는 총알, 호루라기 소리를 낼 수 있는 루미나 휘슬캔디, 그리고 이상한 맛의 우적우적 오일스틱도 들어있었다. 한번은 암귀의 눈알이 들어있기도 했었다.\n매번 편지를 보내오는 쿠리어는 달랐지만, 모두 예외 없이 날개와 사슴뿔, 표범 다리나 튀어나온 송곳니 등과 같은 아인족의 특징을 가지고 있었다. 그런 방문에 익숙해진 후로 나는 그들과 많은 대화를 시도했고, 심지어는 세리오자의 편지를 읽어달라고 부탁하기도 했다.\n어떻게 생겼든 간에 그들은 그동안 내가 가장 보고 싶은 사람들이었다.\n세리오자의 마지막 소포는 백야성에서 보내왔다. 열어보니 손으로 그린 그림이 한 장 떨어졌다. 그림에서 세리오자는 넓은 테라스에 서 있었고, 그 뒤로는 아득한 하늘이 펼쳐져 있었다. 나는 얼마지나지 않아 그림 속의 장소가 백야성이라는 것을 추측해냈다. 세리오자가 예전에 백야성은 아주라이트에 세워졌고, 그 아주라이트는 하늘에 떠 있으며, 오로리안들은 그 위에서 구름을 맞이하며 밝은 햇살 사이를 걸어 다닌다고 말했었으니까.\n그 후로 세리오자의 편지는 오지 않았다.\n(계속)",
  str_dispatch_book_chaptercont_12000_6 = "또다시 반년이 지난 후, 나는 아버지가 술 취한 틈을 타서 몰래 집을 나섰다. 가방에는 소량의 식량만 넣었고, 나머지 공간은 세리오자의 편지와 선물로 채웠다. 나는 쿠리어들이 설명해준 대로 쿠리어 센터를 찾았다.\n그곳에 머물러있던 일부 쿠리어들이 날 알아보았다. 나는 아버지의 안 좋은 행실에 적당히 거짓말을 섞어 이야기했고, 그들은 내가 센터에 머물 수 있게 해주었다. 나는 우편물을 분류하는 등의 허드렛일을 도와주면서 글자를 읽고 쓰는 법을 익혔고, 세리오자가 쓴 편지를 뒤적거리며 반복하고 또 반복해서 읽었다. 편지의 내용은 뒤죽박죽이었지만, 나는 어떻게든 그가 말하고자 하는 바를 이해할 수 있었다. 그는 자신의 여행 이야기를 하기보다는 어린 시절의 이야기를 하는 것을 좋아했다. 그는 비록 백야성에서 태어나긴 했지만, 자신도 어렸을 땐 나와 같이 굉장히 가난했다고 했다. 나는 그의 글 속에서 그가 날 위로하고 있다는 것을 알 수 있었다. 어쨌든 그는 백야성의 기사이니 어떤 고난이든지 결국은 자신을 단련하는 데 쓰였을 것이다. 그 후로 나도 세리오자에게 편지를 쓰기 시작했다. 나는 세리오자가 마지막으로 보냈던 주소로 편지를 보냈지만, 아쉽게도 답장은 없었다.\n성에 들어갔을 때 시프와 시프의 어머니를 우연히 만나게 되었다.\n시프는 내 손을 꼭 붙잡고 놓지 않았다. 한참을 울더니 그동안 계속 걱정했다며 더듬거리며 말했다. 시프가 펑펑 우는 모습을 보니 너무나 미안했다. 그러나 어떻게 사과를 해야 할지 몰라서 그저 시프의 흐르는 눈물만 닦아주었다.\n마침내, 시프는 소매로 코를 훔치며 코맹맹이 소리로 말했다.\n\"이것 봐\"\n말이 끝나자 시프는 눈을 감았다.\n이어서 시프의 온몸에 환하고 날카로운 번개가 퍼져 나가더니 순식간에 공기가 찢어졌다.",
  str_dispatch_book_chaptercont_12000_7 = "나는 한때 쿠리어 길드에 가입하고자 했었지만 거절당했었다.\n\"미나, 넌 너무 어려.\"\n\"넌 빨리 달리지 못하잖아. 네가 잘못됐다는 건 아니고, 그냥... 오로리안의 발만으로는 그렇게 빨리 뛰긴 어렵다는 거야.\"\n\"쿠리어는 너무 위험해. 잠깐만 방심해도 다칠 수 있다고.\"\n\"암귀랑 정면으로 마주친 적 있어? 난 그래 봤거든.\"\n\"월급도 적어\"\n\"맞아. 그게 가장 중요하지\"\n쿠리어라는 직업이 여러모로 좋지 않다고 하지만 그들은 항상 싱글벙글 웃으며 매일 편지를 보내러 나갔다.\n난 쿠리어들의 고집을 꺾을 수가 없었고, 그저 포기하고 계속해서 편지를 분류하면서 세리오자가 보낸 편지를 찾는 수밖에 없었다. 하지만 쿠리어 길드에 가입하는 것도 내게 온 편지를 찾는 것도 모두 성공하지 못했다.\n시프가 루미나틱스를 배운 후, 시프의 부모님은 시프 혼자서 성에 들어와 날 찾도록 허락했다. 우리와 쿠리어들은 항상 쿠리어 센터 앞에 있는 상수리나무 아래서 수다를 떨곤 했는데, 상수리 열매가 머리와 어깨에 떨어지곤 했다.\n나는 종종 쿠리어들에게 백야성, 특히 기사단에 대해서 물었지만 대답은 한 두 마디로 그치는 경우가 대부분이었다.\n\"기사단은 위엄이 있고, 루미나틱스 능력도 아주 굉장해.\"\n\"전에 기사단의 오로리안에게 편지를 전해준 적이 있는데, 편지를 뜯는 모습도 굉장히 우아했어.\"\n그리고는 서로 쳐다보며 물었다.\n\"또 다른 건 없어?\"\n\"사실 나도 그 사람들하고는 거의 교류를 안 해서 말이야.\"\n시프는 손으로 몸을 받히고 고개를 뒤로 젖혔다. 상수리나무 사이로 스며든 하늘의 빛이 시프의 얼굴에 쏟아졌다. \"직접 가보고 싶다.\" 시프가 말했다.\n그 순간인지 정확하지는 않지만 나는 결심했다. 백야성 외에도 헤븐즈 밸리, 일루미나 지하성, 레디젤 사막, 움브라톤, 비경까지 모두 직접 가보겠다고 말이다.\n(계속)",
  str_dispatch_book_chaptercont_12000_8 = "어쩌면 그저 이 지긋지긋한 땅을 벗어나기 위해서만은 아니었을지도 모른다. 내가 이곳을 떠나는 것은 손을 뻗으면 닿을 수 있는 생명의 의미처럼 더 많은 뜻이 담겨있었다. 난 세리오자처럼 태어날 때부터 단조로움과 괴로움을 견뎌야 했던 것은 아니었으니까.\n17살이 되었을 때, 나와 시프는 함께 길을 떠났다. 내 제안으로 첫 번째 목적지는 백야성이 되었다.\n우리는 골드리버를 거슬러 올라갔다. 나무배 위에서 흔들린 지 15일이 지나서야 백야성 근처의 강가에 도착할 수 있었다.\n\"아주라이트다!\"\n시프가 하늘을 가리켰다. 나는 손으로 햇볕을 가리며 시프가 가리키는 곳을 바라보았다. 그 부유섬은 원뿔에 둥근 모자를 씌운 것 같았다. 동쪽 황야에 떠 있는 백야성의 윤곽을 하얀 태양이 그려내서 마치 스스로 빛나는 것만 같았다.\n우리는 백야성에 가까이 다가갈수록 거대함과 위압감을 느낄 수 있었다. 그림자가 드리워진 곳으로 들어가자 으스스한 추위가 우리를 감쌌다. 오로리안에게 그늘은 너무 어둡고 너무 추웠다.\n셔틀허브는 유일하게 백야성으로 들어갈 수 있는 항구로, 그곳에 가려면 반드시 비공정을 이용해야 한다. 하지만 나와 시프는 비공정을 타지도 못하고 백야성을 떠나라는 소리만 들었다.\n\"모든 관광객은 외교부의 허가가 있어야만 백야성에 들어갈 수 있습니다!\"\n\"허가를 받으려면 얼마나 걸리나요?\" 시프가 물었다.\n\"보름에서 한 달 정도 걸립니다.\"\n이곳에 머물기엔 여비가 부족했고, 비공정을 타는 것도 우리에겐 너무나 큰 부담이었다. 하는 수 없이, 우리는 발걸음을 돌려야만 했다.\n우리는 다시 다음 목적지를 논의했다. 시프는 씩씩거리며 말했다. \"다음에 가는 곳은 '허가'가 필요 없는 곳으로 가자!\"\n그래서 다음 목적지는 북방이 되었다.\n그런데 북방으로 향하던 도중, 우린 우연히 공짜로 백야성에 들어갈 기회를 얻었다.",
  str_dispatch_book_chaptercont_12000_9 = "백야성을 출발해서 북쪽으로 100km쯤 갔을 때, 우리는 다친 쿠리어를 만났다. 그녀는 백야성으로 가던 길에 암귀를 만났다고 했다. 어둠의 위기 이후 내륙에는 종종 암귀가 돌아다녔다. 순록의 등에 엎드려 있는 그녀의 날개와 종아리에서 나온 피가 순록의 몸을 타고 뚝뚝 흘러내렸다.\n나와 시프는 근처의 쿠리어 센터로 데리고 갔고, 다른 쿠리어가 루미나틱스로 그녀의 상처를 치료했다. 그 쿠리어는 감사를 표하며 쿠리어 센터에 며칠간 쉬어갈 것을 권유했다. 그 후, 그녀는 우리가 백야성에 들어가지 못했던 이야기를 들었다.\n\"백야성은 화물과 관광객에 대한 심사가 매우 까다로워요. 하지만 쿠리어 길드는 화물을 운송하지도 않고, 관광객도 아니랍니다.\" 그녀가 웃으며 말했다.\n\"백야성의 특별 출입 허가증이 있으니, 경비병에게 신분증을 제시하기만 하면 돼요.\"\n그녀는 작은 책자를 하나 가지고 왔다. 그것은 내가 고향 근처의 쿠리어 센터에서 수도 없이 보아왔던, 쿠리어들이 사용하는 일정 기록 노트였다. 그 노트에는 유려한 깃털 펜이 새겨진 휘장이 2개 걸려있었다.\n그녀는 휘장을 꺼내어 나와 시프에게 하나씩 옷자락에 달아주었다. \"이것만 있으면 자유롭게 백야성을 다닐 수 있어요. 빌려주는 거니까 다른 사람에게는 절대로 말해선 안 돼요.\"\n우리는 백야성으로 향하는 쿠리어를 따라 쿠리어 길드 전용 비공정에 몸을 실었다.\n비공정은 땅에서 점점 멀어졌다. 나는 주머니 속에 있는 종이를 움켜쥐었다. 그것은 세리오자가 마지막으로 내게 보낸 물건이었다.\n(계속)",
  str_dispatch_book_chaptercont_12000_10 = "셔틀허브는 다운타운 구역과 연결되어 있었다. 그곳은 백야성에서 가장 혼란스럽고, 시끄러우며, 위험한 곳으로 묘사되어 왔다. 하지만 그곳에 처음 도착했을 때, 우린 그것이 잘못된 묘사라는 생각이 들었다. 다운타운 구역은 백야성에서 가장 번화하고, 자극적이며, 활기찬 곳이었다.\n셔틀허브 안에는 다양한 술집, 카페, 보석 가게가 우리를 맞이하고 있었다. 공기 중에는 향신료, 맥주, 코코아의 냄새가 가득했고, 시프는 심하게 재채기를 했다. 오로리안들이 거리를 걷자 길에 깔린 돌판과 구두가 맞닿으며 끊임없이 소리가 울려 퍼졌다. 가게 앞에서 호객행위를 하는 점원들의 옷차림도 산뜻하고, 태도가 여유로웠다. 손가락에 끼고 행인들을 향해 내민 손수건에서는 좋은 향기가 가득했다.\n이곳이 세리오자의 고향이구나.\n시프가 쇼윈도에 얼굴을 대고 인형 목에 걸려있는 바로크 양식의 목걸이를 바라보고 있을 때, 나는 앉아서 맥주를 마시고 있는 오로리안에게 세리오자가 내게 남겼던 주소에 대해 물었다.\n\"거긴 빈민가야.\" 약간 술에 취한 오로리안은 수염에 하얀 거품을 묻힌 채 나를 훑어보았다. \"꼬마 아가씨, 거긴 뭐 하러 가려고?\"\n나는 한 기사를 찾고 있다고 말했다.\n\"기사?\" 그가 고개를 저으며 비웃었다. \"그런 허름한 곳에서 기사가 나올 리가 있겠어?\"\n순간 얼굴이 굳어지는 것이 느껴졌다. 하지만 불안한 마음을 억누르고 반박했다. \"연 방패를 가지고 있었어요. 그건 기사들의 장비잖아요!\"\n\"연 방패?\" 그가 반문했고, 나는 그가 또다시 부정적인 말을 꺼낼까 두려웠다. \"그건 확실히 기사단의 장비지. 꼬마 아가씨, 그자를 어디서 만났지?\"\n나는 어렴풋이 이 대화를 더는 이어나가면 안 될 것 같다는 느낌이 들었다. 하지만 그의 오만한 태도가 싫었던 나는 세리오자가 어떤 차림이었고, 상단을 어떻게 호송했고, 루미나틱스를 보여줬는지를 일일이 들려주었다.\n\"상단 호송?\" 그 오로리안은 갑자기 웃음을 터트렸다. \"자기 몸값을 낮춰서 상단이나 호송하고 다니는 기사가 세상에 어디 있어!\"",
  str_dispatch_book_chaptercont_12000_11 = "어떻게 셔틀허브 근처를 떠났는지는 기억이 나지 않는다. 정신을 차려보니 시프가 자신의 손을 잡고 있는 내 팔을 치며 불만 어린 표정으로 나를 부르고 있었다. \"미나! 아프다니까!\"\n\"미안\" 나는 황급히 손을 놓았다.\n시프는 팔을 문지르며 산 위에 줄지어 늘어선 하얀 벽돌집을 바라보며 물었다. \"제대로 가고 있는 것 맞아?\"\n몇 걸음 떨어진 곳에 세워진 이정표를 살펴보니, 틀림없이 이곳이 세리오자가 편지에 남겨놓은 주소였다.\n민가가 복잡하게 늘어선 골목에 들어서자마자 우린 길을 잃어버렸다. 골목 옆의 집 외벽에는 발자국과 낙서가 가득했다. 발아래의 길도 더는 돌이 깔린 길이 아닌, 울퉁불퉁한 진흙 길이었다. 그림자 속에서 낯설고 경계하는 눈빛이 우리를 향했다. 시프가 내 팔을 잡더니 물었다. \"왜 사람들에게 주소를 안 물어보는 거야?\"\n불안감이 맴돌았다. 다른 사람에게 입을 열면 모든 비밀이 쏟아져 나올까 봐 무서웠다.\n하지만 시프는 그런 내 마음은 신경 쓰지 않고 덩치가 있는 수수한 부인에게 다가가 세리오자를 아는지 물었다.\n\"그놈을 찾아서 뭐 하려고?\" 그녀의 입술이 삐죽거렸고, 얼굴의 모든 주름 하나하나에는 경멸이 가득 담겨 있었다. \"너희들이 그놈 대신 빚을 갚아줄 거야? 그렇다면 어디 있는지 알려줄 수 있지.\"\n시프는 이해가 되지 않았다. \"설마 여기에 또 다른 세리오자가 있는 건가?\" 그리곤 열성적으로 세리오자의 모습을 부인에게 설명했다.\n\"꼬마 아가씨, 하나가 빠졌네.\" 담 모퉁이에 앉아있는 노숙자가 시프를 향해 지저분한 손가락을 세우더니 깨져서 온전하지 않은 누런 이를 드러냈다. \"하나 더 추가해야지. 왼쪽 다리를 못 쓴다고 말이야.\"\n나는 시프를 끌고 갔다.\n조금 더 앞으로 나아간 후 다시 길가에 있는 오로리안에게 세리오자에 대해서 물었지만, 그들의 묘사는 대부분 비슷했다. 도박으로 빚을 지고, 백야성 기사단의 장비를 몰래 팔다가 치안대에게 걸려서 병사들과 싸우고, 장애인이 되었다는 것이었다...\n\"한번은 술에 취해서 큰 이득을 얻었다고 허풍을 떨더라니까! 그게 뭔가 했더니 기사단의 연 방패와 판금 갑옷이더라고! 그거 골치 아프게 될 일 아니겠어?\"\n\"젊었을 때는 기사단에 가입하고 싶다는 망상을 하곤 했지. 근데 입단이 그렇게나 까다로운 기사단인데 가능할 리가 있겠어?\"\n......\n\"내리막길 끝에 술집이 하나 있는데 거기서 자주 봤어.\"\n마침내, 누군가 세리오자의 행방을 알려주었다.\"\n(계속)",
  str_dispatch_book_chaptercont_12000_12 = "\"찾아갈 거야?\" 시프가 물었다.\n나는 굳은 얼굴로 끄덕였다. \"다들 다른 사람이랑 착각한 걸 수도 있잖아.\"\n비탈길을 따라가니 그 끝에 무너진 술집이 보였다. 키가 크고 작은 남자들 몇 명이 술집 외벽에 기대어 있었다. 그들의 허리에는 다양한 공구들이 걸려 있었고, 소매는 팔꿈치까지 걷어 올린 채, 맥주를 들고는 큰 소리로 떠들고 있었다.\n남루한 옷차림의 남자가 담벼락 옆에서 책상다리하고 앉아있었다. 그의 갈색 머리는 아무렇게나 헝클어져 있었고 수염은 얼굴 대부분을 덮고 있었다. 남자는 손으로 땅을 짚고 몸을 앞으로 기울여 다른 사람에게 웃었다. \"어이, 윌, 맥주 좀 나눠 마시자고!\"\n검은 머리의 건장한 남자가 그의 다리를 차며 비웃었다. \"절름발인 주제에 술은 마시고 싶어?\"\n갈색 머리의 남자는 괴성을 지르더니 거의 감각이 사라진 듯한 다리를 두 손으로 움직여 벽에 기대어 앉았다. 하지만 그 더러운 얼굴에 웃음은 여전히 머물러 있었다. 그는 마른 입술을 혀로 핥으며 계속해서 남의 손에 들려 있는 술잔을 바라보기만 했다.\n\"세리오자가 보여? 난 모습이 기억나지 않아서 말이야.\" 시프가 물었다.\n난 세리오자를 알아볼 수 있었다.\n하지만 말할 수 없었다.\n태양은 머리 위에 있고, 북 치는 소리가 또다시 가까워지기 시작했다. 내 몸에 골드리버의 비린 물이 가득 차더니 흘러넘치는 것 같은 느낌이 들었다. 입과 코가 잠기고, 눈까지 가득 차오르려고 했다.\n\"아니.\" 난 스스로에게 말했다. \"우리 그냥 돌아...\" 이어지는 말이 목에 메여 나오지 않았다. 계속해봤자 거짓말이 될 테니까. 하지만 시프는 내가 찾는 것을 포기하겠다는 소리를 듣자, 매우 기뻐하며 내 손을 끌어당겼다. 시프는 길을 돌아가며 자신이 셔틀허브에서 보았던 신기한 것들을 하나하나 세기 시작했다.\n결국 우리는 그날 백야성을 떠났다.\n그 후로 내가 그 공중에 떠 있는 땅을 다시 밟는 일은 거의 없었다.",
  str_dispatch_book_chaptercont_13000_1 = "마을 입구에는 주춧돌 2개가 있다. 그것은 산에 있는 암석을 벽돌 모양으로 자른 후 하나하나 쌓아 올린 것이었다. 소나무가 그 양 끝을 이어, 주춧돌과 함께 외로운 문 하나를 이루고 있다. 깔끔하게 다듬어지지 않은 소나무 가지에는 오색 빛깔의 비단이 묶여있어 찬 바람이 불면 펄럭펄럭 소리가 났다. 멀리서 온 여행객은 그 문을 보고 앞에 마을이 있다는 것을 알 수 있었다. 주춧돌에는 항상 마을 아이들이 기어 올라가곤 했다. 아이들은 발을 돌 틈새에 집어넣고, 손으로 비단을 묶은 나뭇가지를 붙잡고 올라가, 몸을 앞으로 내밀고 길의 먼 끝자락을 바라보았다. 그러나 추위로 주춧돌이 얼어붙었고 이로 인해 몇몇 아이들이 다치자, 마을 장로는 그 위에 올라가지 못하도록 금지령을 내렸다.\n어젯밤에는 눈이 많이 내렸다. 문을 나서보니 무릎까지 쌓이진 않았다. 장로는 도로시와 크루즈를 불러서 삽을 주더니 다른 주민들과 함께 길의 눈을 치우라고 했다. 일부 주민들은 루미나틱스를 다룰 줄 알았고, 도로 위의 눈은 대부분 마을 숲에 던져졌다. 도로시도 루미나틱스를 다룰 줄 알지만, 눈을 치우는 데 적합하지는 않았다. 도로시와 동생 크루즈는 다른 주민들의 뒤를 따라가며 삽으로 천천히 돌길의 얼음 조각을 긁어냈다. 삽을 장로에게 돌려주었을 때는 이미 저녁 무렵이었다. 장로는 예전처럼 청어 통조림을 많이 가져왔다. 그리고는 집에 먹을 것이 얼마나 남았냐고 물어보더니 크루즈의 손에 젤리를 쥐여주었다. 크루즈가 젤리를 주머니에 넣자, 젤리가 주머니의 뚫린 구멍으로 떨어졌다. 크루즈는 부끄러워하며 주머니를 가렸고, 도로시는 동생을 대신해서 젤리를 주웠다. 그 후, 장로는 마을 남동쪽에 살고 있는 부인 이야기를 했다.\n\"그 사람들이 아이들을 들였으면 한다는구나. 너희는 어리고, 돌봐줄 어른도 없으니 그 사람들과 같이 가족이 되는 건 어떻겠니?\"\n도로시는 장로에게 대답하지 않고 동생의 주머니에 난 구멍을 잡으며 작은 소리로 말했다. \"다음부턴 옷이 찢어지면 내게 말해. 내가 꿰맬 수 없는 것도 아니잖아.\"\n장로는 한숨을 내쉬고는 둘에게 손을 내저었다. 도로시 남매는 감사의 인사를 하고선 손을 잡고 천천히 집으로 향했다.",
  str_dispatch_book_chaptercont_13000_2 = "집으로 돌아오자 하늘에서 또다시 눈이 내리기 시작했다. 사방은 이미 어두워졌고, 마을에는 드문드문 노란 등불이 켜져 있었다. 집에 멀지 않은 것을 보고 몇 걸음 달려 나가던 크루즈의 발밑에 뭔가가 걸렸다. 고개를 숙여 보니 눈밭에 누군가가 쓰러져 있는 것이 보였다. 동생의 외침을 들은 도로시는 급히 앞으로 달려갔다. 그 사람은 기침을 하더니 일어나려고 애쓰는 것처럼 보였다. 도로시는 그 모습을 자세하게 훑어보았고, 그 사람이 낯선 오로리안이라는 것을 확신한 후, 동생을 불러 둘이서 함께 부축했다. 주변을 둘러보니 길가에 때마침 장작이 쌓여 있는 초가집이 보였다. 남매는 오로리안을 처마 밑까지 부축했다. 오로리안은 감사 인사를 하고는 벽에 기대어 더는 아무런 소리도 내지 않았다. 멀지 않은 곳의 등불의 빛으로 도로시는 모자 속에서 몇 가닥 흘러내린 금발이 그녀의 호흡에 따라 오르락내리락하는 것을 볼 수 있었다.\n낮선 오로리안을 도왔던 크지도 작지도 않았던 일은 도로시와 크루즈에게 금세 잊혀졌고 그다음 날 마을에 외지인이 마을에 정착했다는 이야기가 퍼졌다. 도로시 남매는 눈을 치우기 위해 집을 나섰다. 집 옆의 낡고 오래된 집의 문과 창문은 닫혀 있었지만, 굴뚝에서 흰 연기가 새파란 하늘로 올라가는 것을 볼 수 있었다.\n크루즈는 지붕에 생긴 큰 구멍을 가리키며 물었다. \"이런 집에도 사람이 살 수 있는 거야?\"\n도로시는 크루즈의 옷깃을 잡고 오래된 집에서 끌고 나갔다.\n밤에도 여전히 눈보라가 몰아쳤다. 남매는 이불 속에 웅크린 채, 숲에서 들려오는 날카로운 바람 소리와 무언가 갈라지는 소리를 들으며 잠자리에 들었다. 갑자기 문밖에서 굉음이 들려오더니 이어서 우당탕 쿵쾅하는 소리가 들려왔다. 무언가 무너져 내린 듯했다. 크루즈는 꿈속에서 오들오들 떨었고 도로시는 깜짝 놀라서 깨어났다. 고개를 들고 경계를 늦추지 않으며 바라보았다.\n오래지 않아 문밖은 점차 조용해졌고, 창틈으로 나지막한 바람 소리만 들려왔다. 도로시는 눈을 비비고는 또다시 베개에 머리를 뉘였다. 어렴풋이 잠든 지 얼마 지나지 않아 도로시가 다시 잠에서 깬 것은 누군가 집의 나무문을 똑똑하고 두드렸기 때문이었다. 도로시는 다시 잠에서 깼다. 그녀는 동생을 깨우지 않기 위해서 조심스럽게 이부자리를 들치고 침대에서 내려왔다. 등유등을 밝힌 도로시는 창문가로 올라간 후 틈새를 약간 열어 문밖의 상황을 살펴보았다. 문밖에는 곱슬머리가 찬바람에 엉망이 된 채로 얇은 담요를 두르고 웅크린 누군가가 기다리고 있었다.\n도로시는 한눈에 누구인지 알아차렸다. 하지만 문을 열지 않고 등불을 든 채로 머리를 차가운 공기에 들이밀며 물었다. \"무슨 일 있어?\"\n금발의 오로리안은 오래된 집의 방향을 가리키며 말했다. \"집이 부서져서 말이야. 하룻밤만 재워줄 수 있을까?\"\n도로시는 한참을 망설이며 어둠 속을 바라보다가 말했다. \"장로님을 찾아가는 게 좋지 않을까?\"\n오로리안은 고개를 끄덕였다. 담요를 꽉 쥐고 몸을 돌려 떠날 준비를 하는 순간 도로시는 그 오로리안이 맨발인 것을 알아차렸다. 발자국이 눈밭에 하나하나 찍히기 시작했다. 도로시는 이를 악물고 망설이다가 결국 달려가 문을 열었다. 그리곤 낮은 목소리로 떠나는 오로리안을 불렀다. \"저기... 됐으니까 일단 들어와!\"",
  str_dispatch_book_chaptercont_13000_3 = "도로시는 오로리안의 이름이 마사라는 것을 알게 되었다. 마사는 담요를 두른 채 벽난로 옆에서 하룻밤을 잤다. 날이 밝자 도로시와 크루즈는 집을 나섰다. 오래된 집은 반쪽만 남아있었다. 지붕은 통째로 젖혀져 있었고, 기둥은 곧 쓰러질 것만 같았으며, 벽돌은 사방에 흩어져 있었다.\n마사는 폐허 속을 뒤졌다. 먼저 벽돌 속에서 장화를 꺼내어 속에 들어간 눈과 나무 부스러기를 쏟아부었다. 신발을 신은 그녀는 끊어진 나무 기둥을 치우고 그 안에서 검은색 천으로 싸인 무언가를 끄집어냈다.\n\"먹을래? 초콜릿이야.\" 마사가 배낭 안에서 은종이에 쌓인 사탕을 꺼냈다. 크루즈가 손을 내밀려고 하자 도로시가 막아섰다. 마사는 아랑곳하지 않고 초콜릿을 가방에 넣은 뒤 진공 포장된 빵을 따로 꺼내어 눈과 함께 입에 밀어 넣고는 빠르게 씹어 삼켰다.\n마사는 폐허에 앉아 음식을 먹으며 무너진 집을 훑어보았다. 그리고는 약속하듯이 말했다. \"최대한 빨리 집을 수리할게.\"\n도로시는 고개를 끄덕이고는 동생을 끌고 갔다.\n그 이야기를 들은 장로는 마사에게 당분간 도로시 집에 머물다가 집이 다 고쳐지면 집을 옮길 것을 권유했다. 도로시는 내키진 않았지만 장로가 큼지막한 삭힌 상어고기를 줘서 거절할 수 없었다.\n마사는 장로 집에서 말을 빌려 매일 숲에서 돌과 목재를 가지고 와 무너진 옛집 뒤에 쌓았다. 대낮에는 마사를 거의 볼 수 없었다. 마사는 점심과 저녁에만 주방이나 벽난로 곁에 나타나 밥을 짓거나 잠을 잤다.\n처음에 마사는 도로시 남매와 함께 밥을 먹지 않았다. 난로 근처에서 책상다리를 한 채 멍한 표정으로 소리 없이 빵을 뜯어 먹었고, 이따금 구운 고기와 생선 스튜를 곁들였다. 도로시는 누가 먼저 시작했는지 기억이 나지 않았다. 아마 마사가 신선한 토끼 고기를 먼저 나눠줬을 수도 있고, 크루즈가 마사와 함께 난로 곁에서 책상다리를 하고는 젤리와 초콜릿을 함께 나눴을지도 모르겠다. 어쨌든 결국 세 사람은 한 테이블에 앉아 함께 밥을 먹게 되었다.",
  str_dispatch_book_chaptercont_13000_4 = "마사는 더는 마을 옆에 있는 숲에서 시간을 보내지 않았고, 요리를 하는데 더 많은 신경을 썼다. 마사는 차가운 청어 통조림과 상어고기를 그 상태로 먹는 것을 좋아하지 않았다. 그래서 도로시 남매의 식탁에는 야채 수프, 부야베스, 꼬치구이와 으깬 감자가 올라왔다. 도로시는 마사가 요리하는 것을 원치 않았는데, 그건 마사가 전혀 손님으로 보이지 않게 만들기 때문이었다. 하지만 크루즈는 도로시의 서투른 요리보다 마사가 만든 음식을 훨씬 더 좋아했다. 그래서 도로시는 마사를 따라다니며 최대한 세탁과 허드렛일을 도와주었고, 마사가 요리할 때 사용하는 재료와 순서를 몰래 기록했다.\n마사의 음식에 대한 야망은 단순히 배불리 먹는 것이 전부가 아니었다. 그녀는 국자를 쥐고 맛을 본 후 말했다. \"소금이 좀 필요할 것 같아.\"\n\"소금?\" 도로시는 한참을 생각하다가 눈 알갱이 같은 조미료가 생각났다. \"그건 구하기 힘들어.\"\n그 말을 들은 마사는 생각나는 것이 있다는 듯이 고개를 끄덕였다.\n그다음 날, 도로시가 장로의 허드렛일을 돕고 돌아왔을 때 크루즈가 소매를 잡아당겨 주방으로 끌고 갔다. 그리고는 구석에 있는 작은 마대 자루를 가리키며 큰 소리로 말했다. \"소금이야!\"\n도로시는 쭈그리고 앉아 검지로 새하얀 알갱이를 찍어서 입에 넣었다. 짠맛이 입안에 퍼졌다.\n\"어디서 난 거야?\"\n\"마사, 마사가 가지고 왔어!\" 크루즈는 도로시 뒤에 멧돼지 다리를 들고 주방으로 향하고 있는 마사를 가리켰다.\n도로시가 쭈뼛거리며 물었다. \"소금... 엄청 비싸지 않아?\"\n마사는 잠시 어리둥절해 하더니 말했다. \"사 온 게 아니야.\"\n\"그럼 어디서 가지고 온 거야?\"\n마사는 웃으며 말했다. \"근처에 있는 함수호에서 가지고 왔어\"\n도로시 남매의 추궁 끝에 마사는 소금을 얻는 방법을 상세하게 알려주었다. 마사가 얼마 전에 사냥감을 따라가다가 함수호를 찾았다고 한다. 물을 퍼고 호수를 얼린 후에 얼지 않은 간수를 집으로 가지고 왔고, 그 간수를 난롯불에 끓여 소금을 분리한 다음 여러 번 걸러서 먹을 수 있는 소금을 얻었다고 했다... 도로시와 크루즈는 이야기에 푹 빠졌다. 마사가 돼지고기를 소금에 절이려고 할 때도 끊임없이 물었다.\n\"마사는 어떻게 그런 걸 알아?\" 도로시는 마사가 소금을 돼지고기 위에 바르는 것을 배웠다.\n\"아는 건 어렵지 않아.\" 마사는 엉뚱한 대답을 했다.\n도로시는 고개를 끄덕이며 마음속으로 하는 것도 어렵지 않다고 생각했다.",
  str_dispatch_book_chaptercont_13000_5 = "평범한 하루였다. 장로는 도로시에게 눈을 치우는 일 외에, 마을의 양을 숲으로 몰고 가서 풀을 먹이는 새로운 일을 찾아주었다. 마사는 새로운 목재와 돌을 운반한 후 집으로 돌아와 저녁을 준비했다. 창문에 엎드린 크루즈는 머리를 내밀어 오래된 집에 새로 놓인 얼음 뼈대를 살펴보았다. 그리곤 결국 큰 소리로 부엌에 있는 마사에게 물었다. \"마사, 이제 이사 갈 거야?\"\n\"아직 한, 두 주는 더 걸릴걸?\" 마사는 껍질 벗긴 당근을 하나씩 솥에 넣었다.\n부엌으로 달려간 크루즈는 마사 옆에 앉아 두 손으로 턱을 괸 채 가만히 앉아있다가 말했다. \"마사가 가는 거 싫어\" 약간의 간격을 두고 한마디를 또 보탰다. \"누나한테는 말하지 마.\"\n\"왜 말하면 안 되는데?\" 마사는 국자로 솥을 두어 번 휘저었다.\n\"누나는 어른한테 기대면 안 된다고 그랬어... 결국 우릴 버리고 간다고...\"\n소리 없이 국을 젓다가 국자가 간혹 솥에 부딪혀 쨍하는 소리가 났다.\n\"어른은 항상 해야 할 일이 많아요. 항상 그렇듯이 그건 우리를 돌보는 것보다 더 중요한 것이라고 누나가 그랬어요.\" 크루즈는 시선을 숙였고, 난롯불에 빰이 뜨거워지는 것도 신경 쓰지 않았다. \"하지만 마사는 우릴 버리지 않을 거잖아...\"\n\"너흰...\" 마사는 끝내 질문하지 못한 채 삼켜버리고는 주변을 둘러보며 물었다. \"도로시는 왜 아직도 안 돌아오는 거지?\"\n크루즈도 고개를 들어 창문 밖을 내다보았다. 하늘이 컴컴해지며 방안으로 스며들었다. 눈발이 날리며 창문을 툭툭 건드리고, 찬 바람이 쌩쌩 불어왔다.\n크루즈가 당황하기 시작했다. \"누...누난 왜 아직도 안 오는 거야?\"",
  str_dispatch_book_chaptercont_13000_6 = "광풍에 발이 묶인 채, 도로시는 벌벌 떨며 눈 속을 걸었지만, 휘몰아치는 눈보라 때문에 앞길은 거의 알아볼 수가 없었다. 도로시는 오늘의 모든 선택을 후회하기 시작했다. '양을 마을로 돌려보내고 집으로 돌아가서, 난롯가에서 쪼그리고 앉아서 졸았어야 했어. 중간쯤 왔을 때 길이 생각보다 멀다는 걸 알아채고 최대한 빨리 되돌아가야 했어. 아무리 호수를 찾았어도 호수가 얼기를 기다릴 게 아니라 하늘을 올려다 봤어야 했는데...' 눈보라가 휘몰아치는 데다가 더욱 최악인 것은 날이 점점 어두워지고 있다는 것이었다. 도로시는 주변을 둘러보며 최악의 경우 눈 덮인 야외에서 잠을 자야 할지도 모른다고 생각했다.\n그런 생각을 하며 그녀는 눈보라를 피할 수 있는 틈을 찾아 바위 더미를 탐색했다. 다행히도 피할 만한 곳을 찾았다. 바위 2개가 조금 낮은 동굴 형태로 만들어져 있었다. 그 사이에 쪼그리고 앉으니 딱이었다. 뒤통수를 바위벽에 튀어나온 곳에 기댄 채, 도로시는 천천히 한숨을 내쉬었다.\n그녀는 크루즈가 걱정되어 참을 수가 없었다. '놀라서 울고 있는 거 아냐? 아니면 눈보라를 뚫고 장로님한테 가서 날 찾아달라고 이야기했을까? 이런 나쁜 날씨에 내가 실종됐다는 소식을 들으면 장로님이 사람을 보낼까? 마사는 내가 집에 돌아오지 않아서 초조해할까? 아니면 난롯가에 앉아서 그저 멍하니 있을까?'\n도로시는 크루즈의 눈빛을 알아차렸다. 동생은 마사가 단순히 집에 묵는 손님이 아닌 가족으로 남기를 바랬다. 그러나 그들은 마사가 어디서 왔는지조차도 알지 못했다. 마사의 과거는 텅 빈 종이 같았고, 그녀는 단 한 번도 그것에 대해 이야기해준 적이 없었다.\n도로시는 마사가 난로 앞에 있던 모습을 떠올렸다. 마사는 머리를 숙이고 금발을 늘어뜨린 채 평온해하기도, 피곤해하기도, 지겨워하기도 했다. 마사는 식탁 앞에서만 웃었다. 그건 과거를 잊어버려야만 나올 수 있는 가벼운 즐거움이었다. 도로시는 이런 사람은 믿을 수 없고 좋은 '가족'이 될 수도 없다고 생각했다. 비밀을 가지고 있으니 비밀 때문에 떠날 것이다. 잃어버리는 건 이미 충분했다.\n다행히 마사의 집은 곧 수리가 끝날 것이다.\n정신을 차리고 보니 눈보라 소리가 멈춘 것 같았다. 도로시는 쪼그리고 앉아서 저린 다리를 문지르며 동굴 속을 빠져나왔다. 그리곤 어둠 속의 길을 구분하려고 애를 썼다. 갑자기 미세한 소리가 들렸다. 소리가 나는 곳을 바라보자 그녀는 온몸의 피가 얼어붙는 느낌이 들었다. 어둠 속에서 희미한 초록색 빛이 천천히 도로시를 향해 몰려들고 있었다.\n약해지는 바람 속에서 도로시는 그것들의 숨소리를 들은 것만 같았다.\n다른 생물일리가 없었다. 늑대였다.",
  str_dispatch_book_chaptercont_13000_7 = "\"퍽!\"\n또 한 마리 늑대가 도로시 앞의 흩날리는 눈보라에 부딪혔다. 도로시는 자신이 루미나틱스로 얼마나 많은 늑대 무리의 공격을 막아냈는지 기억이 나지 않았다.\n부모님이 돌아가신 후로 우연히 자신이 공기를 응결시킬 수 있다는 것을 깨달았다. 처음에는 손바닥만 한 벽돌 크기로 수십초만 유지할 수 있을 뿐이었다. 이후 응결 범위가 점점 넓어지고 유지할 수 있는 시간도 점차 길어졌다. 컨디션이 좋을 때는 문짝 하나의 크기만큼의 공기를 2분간 응결시킬 수 있었다.\n하지만 밤에는 컨디션이 좋았을 때만큼 힘을 끌어올릴 수 없었다. 물어뜯으려는 늑대는 점차 더 가까워졌고 마사는 그것들의 침 냄새까지 맡을 수 있는 지경이었다. 갑자기 다리가 걸려서 아래를 내려다보자 늑대 한 마리가 바짓가랑이를 물고 엎드린 채 뒤로 잡아당기고 있었다. 도로시는 비명을 지르곤 얼린 공기 벽으로 늑대의 머리를 후려쳤다. 늑대는 아파서 소리를 지르며 도로시의 바짓가랑이를 반쯤 찢어버렸다. 한쪽만 신경 쓰고 있을 때 기회를 노리는 더 많은 늑대들이 으르렁거리며 달려들었다.\n\"퍽!\" 이가 떨리고 식은땀이 이마에서 떨어졌다. 또다시 아슬아슬하게 공격을 막아냈다.\n이대론 안 돼. 공포가 도로시의 몸을 둔하게 만들었고, 공기 벽을 응결하는 속도도 점점 느려졌다. '이대론 안 돼' 귓가에 또렷하게 목소리가 들리는 것만 같았다. '넌 저것들을 막을 수 없어. 밤은 아직도 길어. 넌 절대로 막을 수 없을 거야.'\n찬바람이 도로시의 드러난 종아리를 베었다. 한참이 지나서야 그녀는 자신이 사시나무 떨듯이 떨고 있는 것을 깨달았다. 공포를 의식한 순간, 절망은 홍수와 같이 물밀 듯이 쏟아져 왔다.\n공기는 눈보라 속으로 흩어져 다시는 응결되지 못했다. 멀지 않은 곳에서 늑대의 초록색 눈동자가 매섭게 반짝였다.\n다음 늑대가 덤벼들자 도로시는 팔을 들어 얼굴을 가렸다.\n하지만 통증은 느껴지지 않았다. 빠지직빠지직하며 얼음 어는 소리가 들렸다. 한기가 얼굴을 스치고 무엇인가 한순간에 얼어붙어 버렸다. 팔을 내리자 깜짝 놀랄 광경이 펼쳐져 있었다. 달려드는 늑대가 우스꽝스러운 자세로 반쯤 공중에서 멈춰있었다. 그다음 순간 푸른 빛이 번쩍이자 늑대의 머리가 공중을 돌아 눈밭에 굴러갔다. 늑대의 몸에서는 피도 나지 않았다. 전부 얼어버린 것이었다. 도로시는 비명을 지르고 싶었지만, 소리가 나오지 않았다.\n누군가의 발길질에 늑대의 몸이 날아갔다. 온 사람은 방향을 돌려 도로시를 자신의 뒤로 감췄다. 후드를 벗자 곱슬거리는 금발이 도로시의 빰을 부드럽게 쓸어내렸다. 그녀의 양손에 쥐어진 양날 비수는 이 어두운 밤 속에서도 날카로운 빛을 발하고 있었다.\n도로시는 자신의 얼굴에 뜨거운 액체가 흐르는 것을 느껴졌다. 얼마 지나지 않아 그녀는 그것이 눈물이라는 것을 깨달았다.",
  str_dispatch_book_chaptercont_13000_8 = "위험천만했던 눈 내리던 밤은 이미 지나간 지 오래였다. 도로시는 자신이 어떻게 마사에게 업혀 돌아왔는지 다시는 생각하지 않으려 했다. 발밑에 모여서 킁킁거리며 냄새를 맡던 늑대들, 무겁게 한숨을 내쉬던 장로, 펑펑 울던 크루즈도 더는 생각하지 않기로 했다. 지금 도로시는 손에 있는 얼음등을 잘 조각해 복도에 놓는 것만 생각했다.\n곧 새해가 다가온다.\n마사의 집은 수리가 끝났다. 하지만 장로가 그 집을 손님을 만나고 접대하는 장소로 사용하겠다고 했다. 이를 위해 족히 한 통은 되어 보이는 삭힌 상어고기를 지불했다.\n도로시는 일찍이 마사에게 그 양날 비수의 출처를 물어본 적이 있었다. 마사가 금속 손잡이 위에 있는 스위치를 돌리자 양 끝의 비수는 손잡이 안으로 들어갔다. 그리고는 그것을 도로시에게 건네며 앞으로 다시는 사용할 일이 없을 거라고 말했다. 이제 비수는 도로시의 것이 되었다. 도로시는 마사의 뜻이 무엇인지 빠르게 알아차렸다. 비수를 거두었다는 것은 과거의 걱정은 이제 뒤로 넘기겠다는 뜻이리라.\n마사는 말했다. 자신은 과거를 내려놓았고, 영원히 자신들을 떠나지 않겠다고.\n얼음등이 하나둘씩 켜졌다. 마을 중앙 공터에는 모닥불이 피어오르고 장로는 종을 쳤다. 마을 사람들은 각자의 집에서 다양한 음식을 들고나왔다. 치즈, 벌꿀 빵, 소시지구이, 고기 스튜, 과일 파이, 아이스 스노우 와인... 뽀송뽀송한 흰 로브를 입은 도로시와 크루즈는 꼬치구이를 들고 주머니에는 젤리를 가득 채운 채 싱글벙글 웃으며 밖으로 나왔다.\n마사는 벌써 모닥불 옆에 서 있었고, 장로는 소매에 손을 넣은 채 그녀와 이야기를 하고 있었다. 도로시 남매가 나오자 마사는 평소처럼 부드럽게 웃으며 손짓했다.\n마을 사람들은 연이어서 모닥불과 장로 곁에 모여 지난 일 년간 있었던 일을 이야기하며 서로의 음식을 나눠 먹었다. 얼마 지나지 않아 한 젊은 아가씨가 먼저 노래를 부르기 시작하자, 마을 사람들은 그 청량한 목소리를 따라 함께 오래된 노래를 부르기 시작했다. 또 다른 아가씨는 춤을 추기 시작했다. 가장자리에 털을 두른 치맛자락이 빙빙 돌고, 독특한 루미나틱스로 만든 불꽃이 주위를 날아다녔다.\n도로시는 마사 옆에 앉아 장단을 맞추며 노래를 흥얼거렸다. 그녀의 눈동자에 비치는 불빛은 마지 멀리서 반짝이는 별빛 같았다.\n노랫소리가 점점 줄어들었다. 도로시는 미소를 지으며 눈을 감고 두 손을 모으고 고개를 숙였다. 마사가 주변을 둘러보니 마을 사람들 대부분 도로시처럼 고개를 숙이고 눈을 감았다. 마치 나지막한 소리로 기도하는 것 같았다.\n도로시가 눈을 뜨자 마사는 웃고 있었다. 마치 새해에 무슨 소원을 빌었는지 묻는 것 같았다. 그러나 그다음 순간 마사의 표정이 굳었다. 그녀의 시선은 모닥불의 밝지 않은 곳을 향해 있었다.\n도로시는 마사의 시선이 향하는 곳으로 고개를 돌려 보았지만, 텅 빈 고요한 암흑만 보일 뿐이었다.",
  str_dispatch_book_chaptercont_13000_9 = "마을에 새로운 손님이 왔다. 도로시는 마을 사람들을 도와 장작을 옮기다가 깨달았다. 검은 머리의 낯선 오로리안이 장로의 집에서 나와 수리한 옛집으로 들어갔다. 도로시가 나갈 때 마사는 평소와 다르게 난롯가에 앉아서 크루즈의 옷을 기워주고 있었다. 평소의 이맘때라면 사냥하러 갔을 시간이었다. 도로시가 집에 돌아와 보니 난롯가 옆은 비어있었다. 크루즈에게 마사가 어디 갔냐고 묻자 옆에 있는 옛집을 가리켰다.\n검은 머리의 오로리안은 마사 때문에 온 것이 틀림없다고 도로시는 확신했다.\n점심을 차려놓은 후, 도로시는 검은 머리의 오로리안에 대해서 물어보기로 했다. 하지만 도로시는 마사의 저항을 너무 쉽게 생각했다.\n처음에 마사는 오래도록 침묵했다. 하지만 도로시의 거듭되는 추궁에 작은 소리로 그가 자신의 '친구'임을 인정했다.\n도로시는 그 대답이 마음에 들지 않았다. 도로시는 상대방의 정체와 목적, 그리고 도로시에게 줄 영향을 알고 싶었다.\n\"그냥 친구야.\" 마사는 일방적으로 도로시의 질문을 끝내버렸다.\n실망한 도로시는 더 이상 질문하기를 포기했다.\n세 사람은 문밖에서 경고의 종소리가 울릴 때까지 조용히 음식을 먹었다.\n마사가 먼저 듣고 식탁에서 일어나 문을 열었다.\n멀리 바라보니 마을 중앙 공터에는 마을 사람들로 가득 차 있었다. 어떤 사람은 큰소리로 욕하고, 어떤 사람은 얼굴을 가리고 흐느끼고, 어떤 사람은 귓속말을 했다. 도로시도 인기척을 느끼고 마사를 따라 나와 두리번거렸다.\n차츰차츰 마을 사람들이 무엇을 이야기하는지 깨달은 도로시의 안색이 변했다.\n암귀였다. 마을 사람들 말로는 근처에 암귀의 흔적이 있었다고 했다.",
  str_dispatch_book_chaptercont_13000_10 = "장로는 마을의 모든 성인 남자를 모아 다섯 명씩 짝을 지어 수색대를 만들고, 마을 근처의 암귀가 활동한 흔적을 조사하도록 했다.\n수색대가 마을을 나갈 때 아이들은 마을 어귀에 있는 주춧돌에 올라 가족들에게 손을 흔들며 작별 인사를 했다. 도로시는 사람들 틈에 섞여 옷 안에 숨겨둔 양날 비수를 꼭 쥐었다. 장로는 자신이 수색대에 합류하는 것을 허락하지 않겠지만, 그녀는 자신이 반드시 가야만 한다는 것을 알고 있었다.\n수색대는 연이어서 출발했고, 사람들도 점차 흩어졌다. 사람들이 자신을 신경 쓰지 않는다는 것을 느낀 도로시는 고개를 숙이고 마지막 팀을 따라잡는 시간을 계산하며 빠른 걸음으로 마을을 떠났다.\n그 순간, 누군가 도로시의 팔을 잡았다.\n\"도로시, 뭘 하려는 거야?\" 마사의 목소리였다.\n도로시는 무의식적으로 팔을 휘저으며 벗어나려고 했다. \"이거 놔!\"\n마사는 도로시의 옷 아래쪽이 평소와 다르다는 것을 한 눈에 알아차렸고, 손을 뻗어 단번에 양날 비수를 가져갔다. \"수색대를 따라 암귀를 찾을 작정이야?\"\n\"너랑 상관없는 일이잖아.\" 도로시는 비수를 빼앗으려 했지만 마사는 가볍게 피했다. \"돌려줘!\"\n\"나랑 돌아가자.\" 마사가 부드럽게 달랬다. \"돌아가면 돌려줄 테니까. 응?\"\n도로시가 이를 악 물자 '찌익'하는 소리와 함께 소매가 찢어졌다. 그리곤 비틀거리며 마사의 손에서 벗어나려고 했다. 도망치려는 순간 마사가 허리를 잡고 다시 잡아당겼다.\n\"암귀가 무슨 장난감인 줄 알아?!\"\n도로시는 당황했다. 마사는 도로시가 어떤 무례한 행동을 해도 혼을 낸 적이 단 한 번도 없었다. 무심코 마사의 표정을 보니 분노로 떨고 있었다. 전에 없던 낯선 표정이었다.\n\"날 가르치려 하지 마.\" 도로시는 재빨리 정신을 차렸다. 표정도 냉랭하게 변했다. \"네가 뭐라고 나한테 그러는데?\"\n허리를 꽉 잡았던 손이 풀렸다. 도로시는 마사를 뿌리치고, 고개도 돌리지 않은 채 빠른 걸음으로 달려갔다.\n\"도로시, 동생도 이렇게 내버려 두고 갈 셈이냐?\"\n장로의 성난 목소리가 뒤에서 들려왔다. 도로시는 괴로워하며 발걸음을 멈추고 눈을 감았다.",
  str_dispatch_book_chaptercont_13000_11 = "마사가 문을 열자 집안은 고요한 물처럼 잠잠했다. 도로시 남매의 방은 굳게 닫혀 있었다. 그녀는 다가가 문을 두드리려고 했지만 손만 허공에 든 채 두드리지 못했다.\n\"5년 전, 마을이 암귀의 습격을 받았지. 도로시와 크루즈의 아버지는 수색대에 들어갔고, 그 수색대는 다시 돌아오지 못했네. 그 후에 두 사람의 어머니가 아버지의 종적을 쫓았지만, 도중에 암귀를 만나 중상을 입고 돌아왔다네. 그리곤 얼마 지나지 않아 세상을 떠났지.\" 장로의 말이 마사의 귓가에 여전히 울리는 것만 같았다. \"너무 엄하게 굴지 말게. 사람마다 잊을 수 없는 과거라는 것이 있는 법이니.\"\n주저하던 마사는 끝내 방문을 두드리지 못했다. 그리고 말없이 돌아서서 문밖을 바라보았다.\n\"마사.\" 검은 머리의 오로리안이 현관에서 기다리고 있었다. \"떠나기로 결심했나?\"\n\"가자.\" 마사의 대답은 나지막한 한숨 소리 같았다.\n갑자기 '삐걱'거리는 소리와 함께 문이 열렸다. 마사의 옷을 누군가가 붙잡았다. 고개를 돌려보니 크루즈가 문 앞에 서 있었다. \"마사, 들어오면 안 돼?\"\n방안에는 도로시가 묵묵히 침대에 앉아있었다. 마사가 들어가자 그제서야 고개를 돌리고 물었다. \"이제 갈 거야?\"\n마사가 입을 열기도 전에 물었다. \"나 때문이야?\"\n\"...오늘 일은 미안해.\" 도로시의 입술이 떨렸다. \"내가 너무 무모했어. 그런 말도 하면 안 되는 거였는데...\"\n\"아니야\" 마사는 웅크리고 앉아 곧 눈물이 떨어질 것 같은 도로시의 눈을 똑바로 바라보았다. \"난 어쩔 수 없이 가야 해.\"\n\"왜?\"\n\"난... 탈영병이거든.\" 마사는 잠시 멈추었다가 말을 이었다. \"난 일루미나 연방에서 왔어.\"\n도로시는 '일루미나 연방'에서 왔다는 의미를 이해할 순 없었지만, '탈영병'이 무엇인지는 알고 있었다.\n\"난... 암귀들과 싸울 수가 없었어. 전우들은 하나도 살아남지 못했고, 난 암귀와 계속해서 싸워야 하는 걸 견딜 수 없어서... 북방까지 도망쳐 왔던 거야.\" 마사는 시선을 아래로 향한 채, \"옛 동료가 찾아왔어. 이제 돌아가지 않으면...\"\n\"돌아가지 않아도 돼.\" 도로시가 다급하게 말했다. \"전우들한테는 내가 말해줄게. 여기 있는 게 즐겁다고 하면 그 사람들도 이해해주지 않을까? ...그리고 장로님한테 부탁하면 도와줄 거야....\"\n\"우릴 떠나지 않겠다고 했잖아... 응?\"\n\"도로시.\" 마사는 손으로 눈물을 훔쳤다. \"부모님의 이야기를 들었어... 정말 미안해.\"\n\"난 너희 곁에 있을 수 없어... 미안해...\"\n도로시는 이가 떨리는 게 느껴졌다. \"그래서.... 매번 그렇게 도망치는 거야?\"\n방안에는 숨 막히는 정적만이 맴돌았다. 마사는 더는 자신을 변호할 이유를 찾지 못했다. 그녀는 탈영병이라는 신분으로 자신을 꾸미는 데 익숙했고, 그 치졸한 연기는 모든 사람이 그녀의 본질을 꿰뚫어 보게 만들었다.\n그것은 사람들을 실망하게 만드는 본질이었다.\n\"가.\" 도로시는 낙담한 듯했다. 몸을 움츠리는 모습은 마치 마사를 피하려는 것처럼 보였다.\n마사는 일어나서 벽 구석에 서 있는 크루즈를 보고는 머리를 쓰다듬으려 했지만, 크루즈는 그 손길을 피해버렸다. 마사는 쓴웃음을 짓고는 잠시 서 있다가 작은 목소리로 말했다. \"한동안 마을 밖으로 나가지 말고, 몸조심해.\"\n말을 마친 마사는 방문을 나섰고, 양날 비수를 거실의 테이블 위에 놓고 밖으로 향했다.",
  str_dispatch_book_chaptercont_13000_12 = "출발하려던 때는 이미 이튿날 아침이었다. 마사와 검은 머리의 오로리안은 마을을 나와 주춧돌을 지나쳤다. 소나무 가지에서 눈이 녹으며 떨어져 도로는 진흙탕이 되어 있었다.\n\"아이들에게 작별 인사는 안 할 건가?\"\n\"그럴 필요가 없어졌어.\" 마사는 후드를 쓰고 머리 위로 떨어지는 물을 피했다. \"날 보고 싶어 하지 않을 테니까.\"\n\"발각되지 않는 건 간단해.\" 검은 머리의 오로리안의 표정은 복잡했다. \"추적자의 인내심이 닳아 없어질 때까지, 계속 도망치기만 하면 돼. 일루미나에서 단 한 명의 탈주병을 위해서 그렇게 많은 시간과 비용을 쏟을 리가 없으니까.\"\n마사는 자조적으로 웃으며 말했다. \"지금 날 놓아줘도 되는데?\"\n검은 머리의 오로리안은 침묵했다.\n\"우리 모두 알고 있잖아. 그런 생활은 의미가 없다는 걸 말이야.\" 마사는 먼 곳에서 눈이 녹는 소리를 들으며 조용히 말했다. \"난 살고 싶어서 일루미나를 떠난 게 아니야. 난 그저... 무기가 되어 끝도 없이 싸워야 하는 것에 질렸을 뿐이야.\"\n\"그럼 왜 나와 같이 돌아가는 걸 선택한 거지?\"\n\"그건...\" 마사는 한참이 지나서야 말을 했다. \"내가 탈영병이라는 걸... 용서할 수 없어서야.\"\n\"앞뒤가 맞지 않는 이야기네.\"\n\"그런가?\" 마사가 쓰게 웃었다. \"한참을 도망쳤는데, 결국 도망칠 수 없다는 걸 깨달았거든.\"\n갑자기 검은 머리의 오로리안이 멈춰 섰다. \"이 모퉁이를 돌면 다시는 이 마을을 볼 수 없을 거야.\"\n마사는 입꼬리를 잡아당겨 웃더니 작은 목소리로 말했다. \"고마워.\"\n마사는 서 있는 곳에서 뒤돌아보았고, 아직 마을 초입의 주춧돌이 보였다. 소나무 가지에 매달린 비단은 눈을 가득 머금고 아무런 미동도 없이 늘어져 있었다. 더 안쪽을 바라보자 마을의 어두컴컴한 지붕이 보였다. 시간이 아직 일러서 모든 굴뚝이 고요했다.\n눈을 돌리려 한 순간, 그녀는 마을 입구 주춧돌 위에 머리가 하나 튀어나와 자신 쪽을 바라보고 있다는 것을 알아차렸고, 마사는 그게 크루즈라는 것을 알 수 있었다.\n마사는 입을 벌렸다. 찬바람에 금발이 휘날렸고, 뺨은 싸늘하게 얼어붙었다. 하지만 그런데도 눈시울은 뜨거워졌다.\n시선이 닿는 곳에 하얀 로브를 입은 여자아이가 쏜살같이 달려와 마사에게서 약간 떨어진 거리에서 걸음을 멈췄다.\n\"도로시?\"\n\"이거 받아.\" 도로시가 숨을 헐떡이며 손바닥을 펼쳤다. 손에 있는 건 양날 비수였다. \"난 필요 없어.\"\n\"네가 가지고 가. 이것도 피할 이유는 없잖아. 그걸로 사과하고 싶은 거라면 안 받을래. 별일 아니니까. 난 전혀 신경 안 써.\" 도로시는 양날 비수를 마사의 손에 쥐여주고는 고집스러운 눈빛과 함께 큰 소리로 말했다.\n\"내가 신경 쓰는 건 네가 언제 돌아올지뿐이야.\"\n말을 마친 도로시는 활짝 웃었다. \"반드시 돌아올 거잖아. 그렇지?\"\n마사는 목이 메었고, 양날 비수를 쥔 손이 떨렸다. 마사는 대답을 하지 못한 채 단지 가볍게 고개를 끄덕였다.\n\"약속한 거야.\" 도로시는 까치발로 가볍게 뒤로 물러나 손을 흔들었다. \"그럼, 마사, 잘 갔다 와.\"\n말을 마친 도로시는 마을로 달려갔고, 크루즈는 주춧돌에서 내려와 누나의 손을 잡았다. 두 아이들은 마을에 들어갔고 담벼락이 아이들의 그림자를 가렸다.\n마을의 굴뚝에서 드디어 밥 짓는 연기가 피어오르기 시작했고, 소나무 가지 위의 비단도 흔들렸다. 눈 녹는 소리는 숲에서 들판으로, 도로에서 마을로 울려 퍼졌다.\n누구나 알고 있다. 얼음이 녹고 나면, 주춧돌 위에 올라가 먼 곳을 내다보는 아이들이 있다는 사실을.",
  str_dispatch_book_chaptercont_14000_1 = "존경하는 맥스 씨와 미니 양에게,\n\n　안녕하세요. 저는 로사라고 해요. 지금은 레디젤 사막에 살고 있죠. 얼마 전 밀주 데킬라 상자에서 당신들 가게의 광고를 봤어요. 아, 광고지를 뭉쳐서 상자 안의 완충재로 사용했더군요. 팔고 있는 부품의 가격을 보니 어째서 이런 가게를 이제야 알게 된 건지 정말 아깝다는 생각이 드네요. 움브라톤으로 가는 상단을 찾아서 이 편지를 부탁했어요. 이 편지가 잘 전달되어 부디 우리의 거래가 성사되길 빌게요.\n　필요한 부품을 리스트에 작성했고, 뒷장에 스케치를 추가했어요. 편지지를 뒤집으면 볼 수 있을 거예요.\n　가게의 광고를 참고해서 대략적인 가격을 계산해 보았고, 계약금으로 총 1500나이티움을 보냈어요. 이 숫자를 기억해 주세요. 상단의 사람에게 꽤 많은 돈을 지급했지만, 그들이 몰래 가로챌지도 모르니까요. 만일 계약금의 금액이 맞지 않는다면, 믿을 만한 사람으로 바꿔서 물건을 보내주세요. 금액이 부족하면 추가로 지급할 테니 말해주세요.\n\n　편지가 잘 도착하길 빌며\n　- 로사\n　　　　　　건조한 오후에 씀\n\n\n존경하는 로사 씨에게,\n\n　거래를 하게 되어 정말 기쁩니다. 필요로 하는 부품을 분류하고 포장을 마쳤습니다. 상단의 중개인이 움브라톤에서 가지고 갈 겁니다(정확히 1500나이티움이 있더군요. 그 사람들을 믿어도 될 것 같습니다). 아, 그리고 초과 지급한 금액이 있어 21나이티움을 동봉했습니다. 부품이 빨리 배달되길 빌겠습니다.\n\n　즐거운 하루가 되시길\n　- M&M 부품가게\n　　　　　　우기의 끝에 씀\n\n\n추신:\n\n　안녕하세요. 로사. 전 미니예요. 전 「미니 양」이라고 불리는 걸 싫어해요. 뭔가 되게 대단한 사람처럼 들리잖아요. 하지만 아빠는 「씨」라고 불려서 매우 기뻐했어요. 어른들은 가식적인 존경을 정말 좋아한다니까요. 이번에 아빠가 「존경하는」이라고 서두에 쓴 것처럼 말이죠. 전에는 그런 식으로 편지를 쓴 적이 없었어요. 보통은 「망할」이라는 말로 시작하죠.\n　아빠를 도와서 주문한 부품을 골랐는데요. 대체 어디에 쓸 건지 상상이 되질 않아요. 하지만 필요로 하는 부품 대부분이 매우 특별한 거라서, 창고 가장 안쪽에서 겨우 찾아냈어요. 일반적인 개조에는 사용하지 않는 것들이니까요. 괜찮다면 뭘 만들고 있는 건지 알려주실 수 있나요? 정말 궁금해요!\n　그리고 절대로 제가 편지를 썼다는 걸 아빠한테 말하지 마세요. 일부러 편지를 뜯은 건 아니에요. 누가 저보고 소포를 부치라고 했거든요.",
  str_dispatch_book_chaptercont_14000_2 = "존경하는 맥스 씨와 친애하는 미니에게,\n\n　어제 겨우 부품을 받았네요. 아무래도 상단은 좋은 배달원이 되긴 틀린 것 같아요. 그들의 본 직업은 밖을 돌아다니면서 잘 모르는 현지인을 속이는 거니까요. 그래서 말인데요. 제대로 된 배달원을 찾았어요. 최근에 머무르고 있는 곳 근처에서 쿠리어 센터를 발견했거든요. 아침 차로 반나절 정도면 도착할 거예요. 그러니 그들에게 소포를 맡기는 게 가장 좋은 선택이 되겠죠. 움브라톤에서도 쿠리어 길드는 신용이 있다고 들었어요. 이렇게 되면 여러분도 상단을 상대할 필요가 없어지겠죠.\n　이번엔 특수한 금속이 필요해서 부탁을 드리려고 해요. 반드시 원재료일 필요는 없고, 그 금속을 포함한 부품이라면 무엇이든 보내주셔도 괜찮아요. 가격은 부품 자체의 가격으로 계산해 주시면 될 것 같아요. 필요한 부품은 리스트에 작성해두었으니 편지지 뒷장을 확인해 주세요.\n　편지에 1500나이티움을 동봉했어요. 이후로는 돈이 남는다면 반송하지 마시고, 그다음 거래에 계산해 주세요. 레디젤 사막에는 수리하고 다시 짜 맞춰야 하는 것들이 너무 많네요. 수리해도 언젠가 또 부서지거나 닳아버려서 말이죠.\n　참. 제가 수리하고 개조하려는 건 호버 트럭이에요. 어떤 아가씨가 이 소식에 관심이 많을 거거든요.\n\n　멋진 하루가 되길 빌며\n　- 로사\n　　　　　　점점 추워지는 저녁에 씀\n\n\n존경하는 로사 씨에게,\n\n　저예요. 미니. 먼저 말해두자면 처음에 쓰여 있는 호칭은 제가 쓴 게 아니에요. 전 절대 저런 구닥다리 인사말을 안 쓴다구요. 그리고 「미니 양」이라고 안 불러주셔서 정말 기쁘네요. 마지막으로, 편지 끝에 썼던 건 일부러 그러신 거죠? 아빠가 주문서를 받고는 의심의 눈초리로 절 바라봤다고요. 「편지 쓰는 게 그렇게 좋다면 로사 씨에게 회신하는 건 네가 해!」라고 하셔서 지금 이렇게 편지를 쓰고 있네요.\n　이제 로사가 가장 관심 있을 이야기를 할게요. 아빠라면 분명히 쓸데없이 「필요로 하신 특수한 부품을 준비했고, 쿠리어 길드가 가지고 레디젤 사막으로 출발했습니다.」 같은 말을 쓰겠죠. 이 편지를 받았을 때면 부품도 이미 도착했을 텐데, 그런 생각이 안 드나 봐요.\n　이번에 보내주신 1500나이티움으로는 금액이 조금 부족해요. 327나이티움이 더 필요해요. 앞으로는 「레디젤 사막 로사 씨 전용 계좌」를 개설해서 출금과 입금을 기록할 거예요. 아빠 말로는 자기가 생각해 낸 획기적인 비즈니스 아이템이라고 하더군요.\n　그리고 이번에 주문한 특수 금속은 모두 의족을 만드는 데 사용하는 기초 재료더군요. 부디 이걸 사용하는 사람이 로사가 아니길 바랄게요.\n\n　즐거운 하루가 되길\n　- 미니와 맥스\n　　　　　　새해 전날에 씀",
  str_dispatch_book_chaptercont_14000_3 = "친애하는 미니와 존경하는 맥스 씨에게,\n\n　지난번에 보내주신 금속 재료는 정말 큰 도움이 되었어요. 하지만 아쉽게도 그 재료는 제가 사용하는 게 맞아요. 몇 달 전, 주둔지가 암귀의 습격을 받았어요. 전투 중에 다리를 좀 다쳤죠. 다리를 절단해야 하는 정도는 아니지만, 여러 가지 이유로 상처가 좀처럼 낫질 않네요. 그래서 쿠리어 길드에서 소포를 전달해 주기 전까진 절뚝거리며 걸었고, 운전은 꿈도 꿀 수 없었죠. 이 금속이 있으면 지지대를 만들 수 있을 거예요.\n　레디젤 사막에 들어온 후 우리의 상황은 비경에 있을 때보다 그다지 좋아지지 않았어요. 말하는 걸 깜빡 잊었는데, 전 비경을 탐색하던 일루미나의 선발대 소속이었어요. 그때 제가 했던 일은 힘들지만 무척 영광스러운 것이었죠. 하지만 더는 그 각박하고 냉정한 상사를 언급하고 싶진 않네요. 레디젤 사막에서 얻을 수 있는 건 넘치는 자유뿐이에요. 사막은 굉장히 똑똑한 장사꾼이어서, 식량과 수면, 안정을 팔아야만 「자유」라는 입장권을 손에 넣을 수 있죠.\n　레디젤 사막에서 가장 골치 아픈 건 날씨예요. 오아시스나 사막 변두리에 살지 않는다면 낮에도 지하로 숨어야만 이 미칠듯한 더위를 피할 수 있죠. 밤이 되면 가장 두꺼운 옷을 입어야 뼛속까지 얼어붙을 것 같은 한기를 막아줘요. 우리가 사막에 왔을 그 당시에는 아무런 경험이 없었어요. 호버 트럭의 부품은 모두 망가져서, 결국 모든 것을 교체할 수밖에 없었죠. 그리고 사막의 사방팔방을 돌아다니는 암귀도 무척이나 성가신 존재예요. 캠프의 방어 시스템을 보강하려면 에너지 부품이 더 필요해요. 전과 마찬가지로 리스트는 편지지 뒷면에 작성해 두었어요. 그리고 호버 트럭의 개조 도면을 동봉했어요. 미니에게 힌트가 되었으면 좋겠네요.\n　그리고 정말로 죄송한 말씀이지만, 지금 우린 형편이 어려워서 당장은 돈을 지급하기가 힘들 것 같아요. 혹시 지급 기한을 조금 더 미뤄줄 수 있을까요? 충분한 돈이 모이면 곧바로 빚을 갚을게요.\n\n　즐거운 하루가 되길 빌며\n　- 로사\n　　　　　　시원한 새벽에 씀",
  str_dispatch_book_chaptercont_14000_4 = "존경하는 로사 씨에게,\n\n　지금 어떤 상황인지는 충분히 이해했습니다. 다음에 주문서를 보낼 때 남은 금액을 지급하셔도 괜찮습니다. 또한 보내주신 호버 트럭의 개조 도안은 잘 참고했습니다. 이것으로 일부 금액을 차감할 수 있을 겁니다.\n　부디 건강을 회복하고 모든 일이 순조롭길 바라겠습니다.\n\n　로사 씨의 건강을 빌며\n　- M&M 부품가게\n　　　　　　꽃피는 계절에 씀\n\n\n추신:\n\n　로사, 또 저예요. 미니. 이 편지를 받았을 땐 다리가 다 나았을지 모르겠네요. 휴, 전 정말 이런 겉치레 같은 인사가 싫어요. 말로만 관심 있는 것 같고, 진실하게 느껴지지 않잖아요. 하지만 전 정말로 로사의 부상이 하루빨리 낫기를 마음속으로 빌고 있어요.\n　지난 편지에서 로사가 일루미나에서 일했었다고 했었죠. 정말 깜짝 놀랄 이야기네요. 전에 전 아빠랑 같이 로사의 신분이 무엇일지 추측해본 적이 있었어요. 전에 저흰 레디젤 사막의 사람들을 만나봤었거든요. 그 사람들은 개조에 무척 관심이 많지만, 전문가인 로사에 비하면 이제 막 발을 들여놓은 초보자에 불과했어요. 드디어 수수께끼가 풀렸네요. 제 기분을 잘 표현하긴 어렵지만, 「역시 그랬어」라는 말만 나오더라고요. 우릴 믿어줘서 고마워요. 절대로 다른 사람에게 로사가 누구인지 말하거나 하지 않을게요.\n　보내준 개조 도면은 정말로 끝내줘요! 이건 호버 트럭이 공중에 뜰 때 안정성을 높이고, 모래와 자갈이 내부로 들어오지 않도록 하는 거죠? 그리고 나중에 엔진도 바꾸려는 거겠죠? 로사의 분해도를 기반으로 아빠와 복제를 해볼까 해요. 부품을 싣는 차에 설치하고 효과가 어떤지 확인해 볼게요. 어쩌면 조만간 굉장히 빠른 차를 가지게 될지도 모르겠네요!",
  str_dispatch_book_chaptercont_14000_5 = "친애하는 미니와 존경하는 맥스 씨에게,\n\n　이번에는 3000나이티움을 함께 보내요. 지난번에 부족했던 327나이티움을 지급하고, 나머지로는 측정 기구를 구매하고 싶어요. 평소와 동일하게 측정 기구 리스트를 편지지 뒷면에 작성해 두었어요.\n　미니의 마음은 잘 받았다고 전해 주세요. 진심이라는 걸 잘 느낄 수 있었어요. 편지를 받은 뒤로 발의 부상은 점차 호전됐고, 이제 조금만 더 있으면 금속 지지대를 떼어낼 수 있을 거예요. 진심에서 우러나온 말이 아니었다면 어떻게 이런 효과가 있을 수 있겠어요? 후훗, 여러분을 만난 건 정말 기적과도 같은 일이에요.\n　최근에는 여건이 좀 좋아졌는데, 한바탕 싸움이 있었거든요. 레디젤 사막에는 암귀 말고도 사방을 떠돌아다니는 강도 떼를 조심해야 해요. 사막에는 정말 깜짝 놀랄 정도로 강도들이 많아요. 대부분 삶에 지친 사람들이 약탈자가 되고, 그 외에도 암귀에게 집이 부서진 사람들도 종종 강도가 되는 길을 선택하죠. 우린 암귀와 싸우는 것을 제외하고, 때때로는 도망치는 강도와도 싸워야 해요. 그 이후로 갈 곳이 없는 일부 사람들이 우리 쪽에 합류했어요.\n　며칠 전에 한 여자애가 우리 캠프에 왔어요. 강도들이 살고 있던 마을을 약탈해서, 혼자서 겨우 도망쳐 나왔다고 하더군요. 무엇을 겪었는지는 자세히 설명하지 않을게요. 설명하는 건 제 장기도 아니고, 그런 이야기를 하는 건 그 아이도 원치 않을 테니까요. 처음에는 캠프에 받아달라고 하지 않고, 복수를 해달라고 하더군요. 그 보수로 어떤 물건을 내놓았는데, 증류수를 만들 수 있는 신기한 부품이었죠. 그건 진짜 고대 기술이었어요. 게다가 그 아이는 우리가 물건을 받기만 하고, 자길 도와주지 않을까 걱정하지도 않았어요. 그 애는 이런 물건이 어디에 더 있는지를 알고 있었고, 우리는 그 아이가 복수하려는 원수의 시체를 가지고 정보를 교환해야 했죠. 아, 깜빡했는데 그 아이의 이름은 서머예요. 이젠 우리 캠프의 일원이 되었죠.\n　한차례 싸움이 있고 난 뒤로, 강도의 캠프에서 나이티움이 가득한 상자와 지하실에 가득한 술, 창고에 가득한 총과 폭탄, 심지어 개조된 차량을 5대나 얻을 수 있었어요. 하지만 가장 중요한 건 그게 아니에요. 서머가 고대 기술로 만들어진 물건을 잔뜩 찾아줬거든요. 저는 지금 이걸 해체할 도구가 제일 먼저 필요해요. 혹시 모르죠. 다음에 편지를 쓸 때면 끊임없이 압생트가 흘러나오는 장치를 만들 수 있지 않겠어요?\n\n　좋은 하루가 되길 빌며\n　- 로사\n　　　　　　무더운 오후에 씀",
  str_dispatch_book_chaptercont_14000_6 = "존경하는 로사 씨에게,\n\n　다시 주문해 주셔서 감사합니다. 그리고 다리 부상이 완치되었다는 소식을 들어서 정말 기쁩니다. 다만 아쉬운 소식을 하나 전해야 할 것 같습니다. 요청하셨던 측정 기구는 몇 가지밖에 찾지 못했고, 나머지는 아는 사람이 거의 없었습니다. 일반 시장이나 고물상 구역에서는 찾기가 힘드니, 기한을 조금 더 연장해 주셨으면 합니다. 운이 좋다면 저희가 경매에서 로사 씨가 원하시는 물건을 찾아낼 수도 있을 겁니다.\n\n　좋은 하루 보내시길\n　- M&M 부품가게\n　　　　　　떠들썩한 오후에 씀\n\n\n추신:\n\n　로사, 안녕하세요! 다리 얘기는 안 할게요. 이 편지를 받을 때면 분명히 다 회복되었을 테니까요! 레디젤 사막의 생활은 정말 위험천만하네요. 다시는 다치지 않길 바랄게요.\n　최근에 있었던 일을 얼른 얘기하고 싶어요. 혹시 백야성의 기념일 축제 아세요? 이 편지를 쓰기 며칠 전에 아빠가 드디어 저 혼자 백야성에 놀러 가는 걸 허락해줬어요. 축제 날에는 셔틀허브의 보안 검색도 느슨해지고, 관광객도 사전에 외교부에 심사 서류를 제출하지 않아도 되거든요. 전 다운타운의 여관에서 3일간 머물렀고, 어제 모든 축제가 끝난 후에야 집에 돌아왔어요. 로사가 백야성에 갈 일이 있으면 제가 가이드해 줄게요. 며칠 동안 백야성의 상황을 훤히 다 알게 되었거든요. 어느 가게의 케이크가 가장 맛있고, 어느 가게의 과일이 가장 신선하고, 어디에서 하이가든의 신전을 볼 수 있는지... 전 모두 다 알고 있거든요. 축제 날에는 퍼레이드와 불꽃놀이도 볼 수 있고, 제일 중요한 건 다양하고 맛있는 음식을 무료로 맛볼 수 있다는 거예요. 평소 전 백야성의 오로리안은 오만해서 재수 없다고 생각했는데, 가보니까 모두 웃는 얼굴로 축제를 소개하고, 길가에 서서 친절하게 음식을 맛보라고 하더라고요. 평소의 재수 없는 모습은 찾아볼 수도 없었어요. 정말 하루하루가 「축제」였으면 좋겠어요.\n　참, 소포에 아빠가 찾은 측정 기구랑 같이 백야성 특산물을 넣어뒀어요. 유통기한이 긴 것만 골랐으니까 상하지 않았을 거예요. 그리고 빨간 모자를 쓴 나무 원숭이 인형이 있을 텐데, 그건 여관 주인의 아들이 선물해 준 거예요. 둘이서 반나절 동안 축제를 구경했거든요. 나무 원숭이 인형은 두 마리였는데, 한 마리는 제가 가지고 있어요. 나머지 한 마리를 로사한테 선물로 주는 거니까 소중하게 간직해 주세요.",
  str_dispatch_book_chaptercont_14000_7 = "친애하는 미니와 존경하는 맥스 씨에게,\n\n　보내주신 측정 기구는 잘 받았어요. 연구가 훨씬 더 편리해졌네요. 일부 측정 기구는 제가 일루미나에서 사용하던 거라서, 시장에 없을 거라고 예상은 하고 있었어요. 그래서 크게 신경 쓰진 않았어요. 만약 경매장에서 비싼 값을 지급해야만 낙찰받을 수 있다면 그냥 포기하는 게 좋을 것 같네요.\n　이번에는 낡은 기타와 오디오 찾는 것을 부탁하려고 편지를 써요. 우리 팀원 중 한 명이 레디젤 사막에 온 후로 록 음악에 푹 빠져버렸는데, 한 달 후에 그 친구 생일이거든요. 그래서 선물로 기타를 개조해 주려고 해요. 안 그러면 매번 제 와이어를 뜯어서 기타를 연주할 테니까요.\n　레디젤 사막에는 좋은 연주가가 적지 않지만, 우리 캠프에는 유난히 괴짜들이 많아요. 정말 생각지도 못한 것으로 음악을 만들더군요. 매번 캠프에 들어갈 때마다 쿵쿵쾅쾅하는 소리가 들려요. 술병을 치는 사람, 기름통을 치는 사람, 차 후드를 손톱으로 켜는 사람, 휘파람을 부는 사람... 정말 잠시도 조용할 날이 없어요. 이 사람들이 작사 작곡도 하다 보니 벽에는 스프레이 건으로 쓴 가사와 악보가 가득해요. 록 음악을 좋아하신다면 몇 곡을 녹음해 드릴 수도 있어요.\n　미니, 원숭이 인형은 잘 받았어요. 인형은 호버 트럭의 유리창 뒤에 쪼그리고 앉아 있어요. 정말 놀랐어요. 낯선 사람과 함께 구경을 했다고요? 미니답지 않은걸요. 그러고 보니 이제 남자친구를 사귈 나이가 되지 않았나요? 후훗, 농담이니까 화내지 말아요. 참, 그리고 잊어버릴 뻔했네요. 보내준 스콘과 잼을 서머가 정말 좋아했어요. 저는 건포도와 치즈가 더 좋았지만요. 레디젤 사막의 식습관에 적응하는 건 정말 힘든 일이에요. 제가 샌드버그 절임 때문에 그동안 몇 번이나 토했는지는 아무도 모를 거예요. 보내준 간식 덕분에 제 미각이 다시 살아난 기분이에요.\n\n　좋은 하루 보내길 빌며\n　- 로사\n　　　　　　배부른 식사 후 휴식 시간에 씀",
  str_dispatch_book_chaptercont_14000_8 = "친애하는 미니와 존경하는 맥스 씨에게,\n\n　이번엔 의족을 제작하는 재료가 대량으로 필요해요. 죄송해요. 진통제의 효과가 조금 전에 떨어져서 손 떨림이 멈추질 않네요. 편지지 뒷면에 쓴 글씨를 알아보기 힘들다면 3년 전에 보냈던 리스트를 참고해 주세요. 저는 그 사람들이 그런 일을 저지를지도, 제가 결국 그 일에 가담하게 될지도 전혀 생각하지 못했어요. 일루미나에 대한 감정을 명확하게 말할 순 없지만, 전 그곳에서 20여 년간 일했고 모든 부서에 친구와 동료가 있어요. 저는 자난성을 「어머니의 성」이라고 불렀어요. 비록 그들이 무기를 겨누며 냉담하게 절 쫓아내긴 했었지만, 제가 그 사람들에게 총을 겨누게 될 거라곤 정말 몰랐어요. 바보 같은 충성심이라고 생각할지도 모르겠죠. 탈주했을 때부터 이미 배신한 것이었는걸요. 하지만 배신한 딸이라곤 해도 어떻게 어머니에게 총을 겨눌 수 있겠어요? 움브라톤에 일루미나의 수배 전단지가 붙었을지는 모르겠지만, 소문을 들었다면 그건 사실이에요. 우린 일루미나 수송대를 약탈했고, 운전자 6명과 호위병 20명을 한 명도 남김없이 죽였어요. 우린 너무 무서웠어요. 「무섭다」는 단어를 쓰니 파렴치한 변명 같아서 정말 부끄럽네요. 당시의 느낌은 설명하기가 어렵네요. 마치 귀신에 씐 것처럼 무고한 사람의 얼굴을 향해 방아쇠를 당겼죠. 탄피는 물처럼 흘러내렸고, 모래밭에 끊임없이 떨어졌어요. 대체 왜 일이 이렇게 돼버린 걸까요.\n　우리 쪽에서 먼저 도발했다는 사실은 부정할 순 없어요. 하지만 모두가 이번 일이 이런 학살로 이어질 거라곤 생각지도 못했어요. 처음엔 못된 장난에 불과했으니까요. 처음 총성이 언제 울렸는지는 생각이 나질 않아요. 정신을 차리고 보니 피가 땅에 가득했고, 모래에 서서히 스며들고 있었어요. 오른팔은 큰 화상을 입었고, 왼쪽 허벅지는 루미나틱스에 완전히 타버렸어요. 오른쪽 무릎은 총에 맞아 산산조각이 났죠. 정신을 차렸을 땐 수술대 위였고, 오른쪽 다리는 허벅지 중간부터, 왼쪽 다리는 무릎 아래부터 잘려 나가고 없더군요. 이건 아마 벌이겠죠. 배신에 대한 벌, 살인에 대한 벌... 전 잘못을 저지른 대가를 치르고 있지만, 이로 인해 병상에 갇혀 있고 싶진 않아요. 용서해 주세요. 제가 의족을 만드는 걸 제가 치러야 할 대가에 대한 도피라고 생각해도 상관없어요.\n　편지는 여기까지 쓸게요. 통증 때문에 눈앞이 어지럽네요. 더 써도 당신들이 알아보지 못할 것 같아요.\n\n　- 로사",
  str_dispatch_book_chaptercont_14000_9 = "친애하는 로사에게,\n\n　몸은 좀 어때요? 몇 년이 지나고 나서야 겨우 말하는 거지만, 그때 로사의 편지를 받고 나서 이불 속에 숨어서 얼마나 울었는지 몰라요. 레디젤 사막을 떠나 움브라톤에 와서 살라고, 우리의 이웃이 되어 달라고 이야기할까도 고민했었죠. 그 후로 당신은 더는 그런 고통스러운 편지를 쓰지 않았고, 이전처럼 개조, 음악, 간식에 대한 이야기만을 했었죠. 전 그저 로사가 점점 좋아지고 있다고 믿었고, 「몸은 좀 어때요?」라고 묻는 것조차 조심스러워 피했어요. 오늘은 술을 많이 마셔서 그런지 헛소리가 멈추질 않네요. 제가 무슨 바보 같은 말을 썼더라도, 부디 놀리지 말아 주세요.\n　오늘 술을 마신 건 약혼 때문이에요. 전에 제가 백야성의 그 여관 주인 아들과 무슨 감정이 있는 거 아니냐고 로사가 그랬었죠. 그때 전 분명히 그런 게 아니라고 못 박아 말했고요. 비록 우린 서로 주소를 알고 있고, 움브라톤과 백야성 간에는 편지를 쉽게 보낼 수 있지만, 그래도 우린 한 번도 서로에게 편지를 써본 적은 없어요. 아무튼 그 사람 가지고 놀리는 건 그만해 줘요. 약혼자랑은 어렸을 적부터 알던 사이예요. 오랫동안 밖으로 유학을 다니면서 이상한 능력을 배웠더군요. 지금은 상회의 직원으로 일하고 있어요. 아버지는 그런대로 멀쩡한 사람 같다고 말하더군요.\n　연애소설도 많이 봤고, 제가 결혼하는 모습도 많이 상상해봤지만, 막상 결혼식을 올릴 때가 되니까 벽에 끼어 숨이 막힌 것처럼 불편한 기분이 들어요. 움브라톤에선 많은 사람들이 자신의 인생을 전혀 예측할 수 없어요. 오늘은 누더기 옷을 입고 골목에서 비를 피하다가도, 내일은 보석 반지를 잔뜩 끼고 금으로 장식된 의자에 앉을 수도 있죠. 하지만 저나 아버지 같은 사람들은 인생에서 예상 밖의 일이 일어나는 일이 무척 드물어요. 그저 밥을 먹고, 잠을 자고, 이야기를 나누고, 일하고, 결혼하고, 아이를 낳고 죽죠. 이제 또 예상했던 일을 하게 될 테고, 그렇게 정해진 궤도에서 한 걸음 더 나아가는 셈이 되겠죠.\n　아무래도 낙담하는 말을 너무 많이 쓴 것 같네요. 약혼을 할 건데 이렇게 시무룩하면 안 되는 거겠죠? 결혼식은 두 달 후에 올릴 거예요. 청첩장은 제가 디자인했고, 완성되자마자 가장 먼저 로사의 이름을 썼어요. 제 결혼식에 와줄 수 있나요?\n\n　당신을 걱정하며\n　- 미니\n　　　　　　고요한 해 질 무렵에 씀",
  str_dispatch_book_chaptercont_14000_10 = "친애하는 미니에게,\n\n　결혼한다는 소식을 들으니 마음이 좀 복잡하네요. 아, 미니의 결혼에 불만이 있는 건 절대 아니에요. 단지 조금 시원섭섭한 마음이 들어서 그래요. 미니는 편지에 결혼이 「정해진 궤도에서 한 걸음 나아가는 것」이라고 했죠? 저도 마찬가지예요. 단지 전 머나먼 곳에서 미니가 한 걸음 내딛는 걸 바라보는 사람이겠죠. 자난성에 있을 때 친구의 결혼식에 참석한 적이 있어요. 객석에 앉아서 둘이 강당 밖에서 꽃과 리본으로 장식된 곳으로 들어가는 걸 봤었죠. 새로운 삶의 문이 두 사람에게 열렸고 저는 뒤에 홀로 남겨졌어요. 그걸 보고 있으니 입맛이 참 씁쓸했었죠.\n　예전이라면 미니의 초대를 받는다면 반드시 갔을 거예요. 하지만 지금은... 정말 미안해요. 그동안 편지에 적진 않았지만, 운전을 편하게 하려고 제 의체를 호버 트럭에 연결해 놨거든요. 그래서 걸어 다니는 게 쉽지 않아요. 그리고 이런 모습을 보여주고 싶지도 않고요... 이기적이지만 부디 이해해 줬으면 좋겠어요.\n　대신 선물을 하나 만들었어요. 강철로 된 장미예요. 꽃향기 대신 레디젤 향이 날 거예요. 줄기를 비틀면 꽃잎이 천천히 벌어지거나 오므라들어요. 나이를 너무 많이 먹어서 그런지 낭만을 이해할 수가 없게 되었지만, 장미는 유행을 타지 않는다고 생각하거든요. 부디 이 시들지 않는 꽃이 마음에 들었으면 좋겠네요. 이어지는 인생도 이 장미처럼, 예상 밖의 일이 발생해도 비바람이 두렵지 않게 되길 빌어요.\n　디자인한 청첩장은 정말 예쁘네요. 뒷면의 도안도 무척 마음에 들어요. 전에 제가 보낸 개조 도안을 쓴 건가요?\n\n　행복하길 빌며\n　- 로사\n　　　　　　고요한 저녁 무렵에 씀",
  str_dispatch_book_chaptercont_14000_11 = "존경하는 맥스 씨, 미니 씨에게,\n\n　건강하게 잘 보내고 계시는지요? 저는 로사 씨의 조수 서머라고 해요. 이 편지를 쓴 것은 정말 안타깝지만, 전해드려야 할 불행한 소식이 있어서예요. 며칠 전 외출하던 차량이 암귀의 습격을 받았어요. 동료들을 보호하기 위해서 로사 씨는 호버 트럭을 폭파시켰고, 암귀의 공격을 막아냈어요. 하지만 그 대신 로사가 영원히 우리의 곁을 떠나게 되고 말았어요.\n　로사 씨가 두 다리를 잃은 후부터는 줄곧 제가 쿠리어 길드로부터 대신 편지를 받아 왔어요. 그래서 이 소식을 여러분께 알려야 한다고 생각했어요. 그리고 여러분과 의논했는지는 잘 모르겠지만, 로사 씨는 만약 자신에게 좋지 않은 일이 일어난다면, M&M 부품가게 계좌에 남아 있는 나이티움은 모두 미니 양에게 남기겠다고 제게 확실하게 당부해 두신 적이 있어요. 이와 관련해서 필요한 법률 서류가 있다면 최대한 빨리 준비해서 보내드릴게요.\n　로사 씨는 생전에 여러분의 이야기를 자주 하셨어요. 그리고 여러분이 보내주신 부품은 우리의 삶을 더 편리하게 만들어 주었죠. 호버 트럭의 개조, 팀원들의 악기, 로사의 의족... 캠프에는 여러분이 보내주신 부품이 가득해요. 대원들도 움브라톤에 있는 중고 부품가게가 믿을 만하고, 엔지니어 로사 씨와도 친분이 있다는 사실을 다들 잘 알고 있어요.\n　로사 씨를 잃은 건 정말 큰 충격이에요. 로사 씨는 항상 다른 사람들을 도와주었고, 언제나 약속을 잊지 않았어요. 게다가 천재적인 엔지니어였죠. 철판과 나사, 렌치만 있으면 못 만드는 게 없었어요. 저는 13살 때부터 로사 씨를 따라다니면서 분해와 개조 기술을 배웠어요. 로사 씨는 결혼을 하지 않아서 아이도 없었지만, 제게 로사 씨는 어머니와 같은 존재였어요. 여러분도 로사 씨와 오랫동안 교류했으니, 로사 씨가 조잡한 주문서만으로 이 우정을 끝맺기를 원치 않을 거라 믿어요. 그래서 실례인 줄 알지만 편지에 이 추신을 적게 되었어요. 부디 제 무례를 탓하지 않으셨으면 해요.\n\n　여러분의 앞날을 축복하며\n　- 서머\n　　　　　　모래바람이 다가오는 새벽에 씀",
  str_dispatch_book_chaptercont_14000_12 = "존경하는 서머 씨에게,\n\n　소식을 전해 주셔서 정말 감사해요.\n　로사가 우리의 곁을 떠났다는 소식을 듣고 너무나 슬펐어요. 저는 M&M 부품가게에 가지 않은 지 한참 돼서, 편지는 아버지가 먼저 받아 보셨어요. 사실 최근 M&M 부품가게는 망하기 직전이었어요. 그나마 로사의 주문 덕분에 그동안 버틸 수 있었죠. 지금은 중고 부품 판매로 생계를 유지하고 있진 않지만, 아버지는 가끔 주문서를 보내는 단골 때문에 여전히 가게를 지키고 계셔요.\n　시간이 너무 오래 지나서, 처음에 어떻게 연락을 시작했었는지 기억이 잘 나질 않네요. 아마 관심 있는 내용의 편지를 받고는 충동적으로 회신을 했었는데, 좋은 답장을 받았던 게 계기였던 것 같아요. 돌이켜 보면 전 정말 대단한 친구를 사귀었던 것 같아요. 로사는 제게 도면을 보내 주었고, 레디젤 사막에서 있었던 일을 이야기해 주기도 했고, 그 속에서 벌어진 즐거움과 괴로움을 알려줬어요. 저는 결혼한 뒤로 M&M 부품가게를 떠났고, 답장을 쓰는 일도 드물어졌어요. 결혼 전에 강철로 된 장미와 함께 보냈던 그 편지에서 로사는 결혼한 친구들이 새로운 삶의 문을 향해 나아가지만, 자신은 제자리에 남아 있다고 했었죠. 그땐 그게 원망인 줄 알았는데 지금에서야 그게 어떤 느낌이었는지 알 것 같아요. 로사는 제자리에 남는 게 아쉬웠던 거겠죠. 하지만 돌이켜보면 저도 항상 문 뒤에 갇혀 있었던걸요.\n　지금도 로사는 여전히 제 「대단한 친구」예요. 죽음을 목격했고, 새로운 삶을 맞이했지만, 로사는 항상 다른 사람을 향해 손을 내밀었죠. 여러분을 위해 자신을 희생하기로 한 것처럼, 항상 가장 용감하고 의외인 선택을 했었어요.\n　솔직히 전 오랫동안 로사라는 사람은 사실 세상에 없는 사람이고, 모든 건 제 상상으로 만들어 낸 것이 아닐까 하는 의심마저 하곤 했어요. 이렇게 오랜 세월을 알고 지냈지만 우리는 서로 만난 적이 없었고, 로사는 제 결혼식에도 참석하지 않았으니까요. 차라리 모든 게 제 상상이었다면 좋겠어요. 그렇다면 로사를 되살릴 수 있을 테니까요. 하지만 결국 소용없는 일이겠죠. 제 침대맡에는 로사가 줬던 강철 장미가 여전히 놓여 있고, 노트에는 로사가 그려준 도면이 끼워져 있으니까요.\n　이 편지를 쓰기 전에 이미 상단에 부탁해서 레디젤 사막으로 갈 때 함께 동행하기로 했어요. 이 편지를 받고 나면 얼마 지나지 않아 우리도 만날 수 있겠네요. 부디 이번 여정이 순조로웠으면 좋겠어요.\n\n　당신의 앞날을 축복하며\n　- 미니\n　　　　　　고요한 한밤중에 씀",
  str_dispatch_book_chaptercont_15000_1 = "　움브라톤에 가는 이상, 콜로세움 관전은 일종의 암묵적인 룰이었다. 무대 가장자리에 매달린 묵직한 쇠사슬이 팽팽히 늘어나면서 무대 위의 사람과 물건이 조명 속으로 떠올랐다. 무대를 중심으로 겹겹이 늘어선 관중석은 나란히 펼쳐진 채 높이 서 있었다. 귀족들은 투기장 격투가 양성에 열을 올리며, 정성껏 키운 격투가를 무대에 올리곤 했다. 하루 동안 목숨을 부지하고 가장 많이 승리한 격투가는 허리에 '밤의 제왕'이라는 벨트를 찰 수 있었다. 하지만 관례대로 낮에만 두를 수 있을 뿐, 콜로세움에 밤이 찾아오면 다시 돌려줘야 했다.\n\n　목숨을 건 승부가 치열하게 펼쳐질수록 환호성도 커졌다. 사람들이 무대 위로 던지는 금화 소리는 마치 소낙비처럼 요란하게 울려 퍼졌다. 날이 밝을 때까지 나는 그곳에 머물렀다. 분위기가 점점 가라앉자 구경꾼들이 지친 기색으로 뿔뿔이 흩어졌다. 콜로세움에서 무대를 치우기 시작하자, 물에 씻긴 돌계단 가장자리에 불그스름한 핏물이 고였다. 시종들은 무대에 쌓인 금화를 승자에게 가져다줬는데, 물로 핏물과 먼지를 깨끗이 닦아낸 금화를 양철 상자에 담아서 두 사람이 번갈아 실어 나르곤 했다.\n\n　3년 전에 본 대결을 나는 아직도 기억하고 있다. 개인적으로 가장 좋아했던 싸움이었다. 그중 한 명은 연승을 거둬 이례적으로 '밤의 제왕' 벨트를 두른 채 무대에 올랐다. 반질거리는 두 개의 놋쇠 뿔이 달린 이마, 터질 듯 팽팽하게 긴장된 거친 근육이 쉬지 않고 일렁거렸다. 그의 상대는 더러운 옷을 걸친 애송이였다. 시퍼런 멍이 온몸에 가득한 걸 보니 무대에 오르기 전에 큰 부상을 입은 것 같았다. 두 사람이 함께 무대에 오르자, 관중석에서 야유가 쏟아졌다. 하인들은 쟁반을 든 채 관객석을 오가며, 덩치에게 돈을 걸라며 사람들을 꼬드기고 있었다. 날 초대한 친구에게 시종이 쟁반을 내밀자, 친구는 덩치가 작은 애송이에게 가지고 있는 돈을 몽땅 걸었다. 내가 의아해하며 그 이유를 묻자, 망원경을 거꾸로 든 친구가 무대 위 애송이를 가리키며 녀석이 머큐리 부인의 부하라고 알려줬다.\n\n　움브라톤에 자주 오는 편은 아니지만 머큐리 부인에 관한 소문은 나도 알고 있었다. 움브라톤에는 밀수가 횡행했는데, 그중에서도 가장 거친 사업이 무기 밀수라고 들었다. 일이 잘 풀리면 돈이 하늘에서 떨어지겠지만, 그렇지 않으면 목이 떨어질 일이었으니 말이다. 밀수 거래, 비밀 경매, 그것도 아니면 대규모 인수에 이르기까지, 이들 사업 중 대부분이 한 상회의 지배하에 있었는데, 그 상회를 이끄는 사람이 바로 머큐리 부인이었다. 나는 무대 위 두 사람의 대결을 지켜봤다. 밤의 제왕이 주먹을 힘껏 휘두르자, 루미나틱스의 힘에 무대가 박살 나며 사방으로 파편이 튀었다. 애송이는 비틀거리며 공격을 피하려 했지만, 순식간에 날아오는 파편을 피하지 못하고 바닥에 주저앉았고, 제대로 일어나지도 못한 채 이리저리 굴러다니며 도망치기 급급했다.\n\n　“자기 부하가 목숨을 걸고 싸우는데 머큐리 부인은 관심도 없는 건가?”\n\n　내 질문에 친구는 고개를 젓더니, 어두운 구석을 잽싸게 쳐다보곤 나지막이 입을 열었다.\n\n　“부인은 지금 이 근처에서 지켜보고 있다고.”",
  str_dispatch_book_chaptercont_15000_2 = "　뜨겁고 건조한 새하얀 빛이 쏟아지는 무대, 그늘 속에 숨은 관중석, 터져나오는 환호성... 친구를 따라 어두운 구석을 힐끗 쳐다보던 나는 그곳의 어둠이 유난히 고요하다는 사실을 깨달았다. 검은 옷차림의 사람들이 심각한 표정으로 서 있는 가운데, 가장 안쪽에 한 사람이 앉아 있는 게 보였다. 하지만 진한 그림자 탓에 상대의 얼굴은 보이지 않았고, 그저 그곳의 어둠이 녹슨 것처럼 검붉게 느껴졌다. 무대 위 애송이가 기회를 놓치지 않고 상대의 옆구리를 향해 일격을 날리자, 무대가 삽시간에 달아올랐고, 애송이의 공격을 받은 밤의 제왕이 토한 괴성에 관객들의 환호성도 점점 열기를 띠었다. 격투가에게 돈을 건 사람이 툴툴거리는 소리가 뒤에서 들려왔지만, 어두운 구석은 여전히 고요했다.\n\n　나는 도무지 이해가 되지 않아 친구에게 또 질문을 던졌다.\n\n　“머큐리 부인은 왜 자기 부하를 무대에 올린 거지?”\n\n　움브라톤 사람들은 투기장 격투가를 키우는 일이 드물었다. 또한, 자기 부하를 장난감처럼 다루는 상회의 단장이 있다는 말은 더더욱 들어보지 못했다.\n\n　친구가 나지막이 입을 열었다.\n\n　“저자는 배신자야. 외부와 손을 잡고 상회의 물건을 훔치려 했다고.”\n\n　그 말에 멍해진 것도 잠시, 나는 문득 떠오른 생각에 또다시 친구에게 말을 걸었다.\n\n　“그럼 너 돈 잘못 건 거 아냐? 머큐리 부인은 배신자를 구해줄 생각이 없는 모양인데.”\n\n　그 말에 친구가 웃음을 터뜨리더니, 망원경을 집어 들고는 무대를 계속 살폈다.\n\n　애송이에게 일격을 당한 밤의 제왕은 화를 참지 못하곤 애송이에게 달려들었다. 사방에서 불꽃이 일어나는 일격을 가하느라, 애송이는 힘이 빠진 듯했다. 그는 상대의 공격을 힘겹게 피하며 무대 가장자리까지 밀려났다. 격투가는 그 기회를 놓치지 않고, 애송이의 가슴 한복판에 주먹을 내리꽂았다. 그 위력에 애송이는 무대 밖으로 나가떨어졌다. 환호성이 울려 퍼진 것도 잠시, 정신을 차리고 보니 애송이는 쇠사슬을 붙잡은 채 매달려 있었다. 격투가가 기세를 올려 다시 공격하려는 순간, 심판의 휘슬이 울렸다. 격투가가 아쉬운 표정으로 물러서자, 애송이는 쿨럭거리며 무대 위로 기어올랐다.\n\n　새하얀 빛이 단상을 떠나더니 가운데 관객석을 천천히 비추기 시작했다. 근처의 어둠이 일렁거린다고 느끼지는 순간, 피투성이가 된 포로가 끌려 나오는 것이 보였다. 고개를 푹 숙이고 손이 뒤로 묶인 포로는 빛과 어둠 사이의 경계에 비스듬히 꿇어앉았다. 그 모습에 소름이 끼친 것도 잠시, 무대 위에서 들리는 고함에 허겁지겁 다시 고개를 돌리자, 방금 전까지 바닥에서 숨을 헐떡거리던 애송이가 보였다. 심판과 시종들 때문에 피가 맺힌 그의 입가에서는 욕설이 드문드문 쏟아져 나오는 게 들렸다.",
  str_dispatch_book_chaptercont_15000_3 = "　휘슬이 울리며 휴식 시간이 끝나자, 조명이 무대 위로 돌아오며 대결이 다시 시작됐다. 나는 참지 못하고 관중석 사이에 꿇어앉은 포로를 곁눈질했다. 푹 숙인 고개, 머리카락에서 핏물과 땀방울이 뚝뚝 떨어지는 소리 외에 그는 아무런 소리도 내지 않았다. 다시 무대를 올려다보자, 전반전과는 전혀 다른 상황이 펼쳐지고 있었다.\n\n　애송이의 양팔이 불길로 뒤덮인 가운데, 내밀은 열 개의 손가락이 인두처럼 새빨갛게 달아올랐다. 그는 몸을 이끌고 천천히 상대에게 다가갔다. 무대 위에는 돌조각이 비처럼 쏟아져 내렸다. 그는 여전히 몸을 피해가며 움직였지만, 전처럼 목숨을 부지하려는 몸부림 대신 돌에 맞아 생긴 상처를 참으며 나아가고 있었다. 격투가는 애송이의 기세에 눌려 자신도 모르게 뒷걸음질 쳤지만, 결국 덜미를 잡히고 말았다. 그 순간, 갑자기 불길이 크게 일어나더니 눈부신 빛과 함께 애송이가 상대의 손목을 움켜쥐었다. 삽시간에 연기가 사방으로 치솟았고, 격투가는 고통스러운 비명을 질렀다. 이어서 애송이의 주먹이 갈고리처럼 튀어나오더니 상대의 복부를 정확하게 찔렀다. 환호성이 터져 나온 가운데, 내 뒤에 있던 사람은 자리를 박차고 일어나며 욕설을 내뱉었고, 시종들이 무대 위로 달려들어 애송이를 격투가에게서 떼어냈다.\n\n　배신자라던 애송이가 내 눈앞에 다시 모습을 드러냈을 때, 무대 위에는 새로운 도전자가 서 있었다. 예복 차림에 나비넥타이, 셔츠까지 갖춘 모습이었다. 셔츠는 새로 갈아입은 것 같았는데 얼마 못 가서 핏물이 베고 말았다. 그는 몸을 가볍게 떨고 있었고, 방금 전의 사투에서 미처 정신을 차리지 못한 것 같았다.\n\n　한편 어둠 속에서는 누군가 바닥에 꿇어앉은 포로를 발로 툭툭 찼고, 묵직하지만 부드러운 목소리로 왜소한 체구의 배신자에게 그의 이름을 아느냐고 물었다.\n\n　배신자는 손수건으로 입가의 핏자국을 닦으며 쉰 목소리로 한 별명을 내뱉었다. 그러나 그 말을 들은 여자는 나지막이 웃으며 또 다른 이름을 그에게 말해주었다.\n\n　“진짜 이름도 모르면서 그자의 말을 믿었던 건가?”\n\n　배신자는 힘겹게 말귀를 쥐어 짜냈다.\n\n　“부인, 제 동생은...”\n\n　“당신 여동생이 아직 살아 있다면, 그자의 거짓말이 이렇게 오랫동안 통할 수 있었을까?”\n\n　나지막한 상대의 말에 배신자는 잠시 멍한 표정을 지었고, 억눌린 듯한 울음이 그의 목구멍에서 흘러나왔다. 그는 천천히 무릎을 꿇더니 머리를 어둠 속에 파묻었다.\n\n　갑자기 가늘지만 서늘한 은빛의 빛줄기가 포로의 가슴에서 터져 나왔다가 이내 사라졌고, '윽' 하는 소리와 함께 포로가 바닥에 쓰러지면서 검붉은 피가 그의 몸에서 흘러나왔다. 울음이 잦아들더니 배신자는 몸을 일으키곤 자신의 발치에 있는 시신을 물끄러미 쳐다봤다. 의아한 듯, 혹은 원망스러운 표정이었다. 옷깃이 스치는 소리와 함께 어둠 속에 앉아있던 자는 마침내 얼굴을 드러냈다.\n\n　삽시간에 사방이 고요해졌다. 어깨와 팔뚝까지 흘러내린 그녀의 붉은 머리카락은 붉은 침묵의 강물처럼 보였다. 그녀는 자신의 발치에 꿇어앉은 배신자를 가만히 내려다봤다. 그녀는 다른 곳을 보지 않았지만, 그녀의 시선이 몹시도 추운 흐린 날의 뿌연 햇빛처럼 언제, 어디에나 존재한다는 것을 나는 느낄 수 있었다. 이에 그 눈을 다시 쳐다볼 엄두가 나지 않았고, 그녀의 옷깃에 꽂혀 있는 백합만 간신히 힐끔거릴 뿐이었다. 싱그럽고 연약한 백합은 꽃잎에 맺힌 이슬이 당장이라도 굴러떨어질 것 같았다.\n\n　그녀는 배신자를 향해 손을 내밀었다. 배신자는 결심한 듯 그녀의 손끝을 가볍게 쥐더니 자신의 이마에 손등을 가져다 댔다.\n\n　그것은 충성을 맹세하는 의식이었다.",
  str_dispatch_book_chaptercont_15000_4 = "　친구는 이번 경기로 돈을 잔뜩 땄고, 내게 한잔 사겠다고 했다. 우린 술을 마시며 머큐리 부인에 대해 이야기를 나눴다. 친구는 머큐리 부인의 상회와 여러 번 거래한 덕에 그곳 사람들에 대해 잘 알고 있었지만, 실제로 머큐리 부인을 본 것은 딱 한 번뿐이라고 했다. 이야기 도중에 친구는 웃으며 입을 열었다.\n\n　“부인은 눈에 띄는 타입이거든. 얼굴을 자주 보이면 괜한 소문이 돌기 마련이라고.”\n\n　그럼에도 불구하고 움브라톤에서 떠도는 머큐리 부인에 관한 소문은 결코 적지 않았다. 내가 들은 것만 해도 제법 되는데, 대부분이 황당하기 그지없는 이야기였다. 그러나 그중에서 머큐리 부인의 출신에 관한 이야기는 사실인 게 분명했다. 놀랍게도 부인은 백야성 출신이며, 본명은 '머큐리'가 아니라 끝에 '나'가 붙은 이름으로, 가장 표준적인 백야성 귀족의 이름이라고 했다. 백야성의 귀족이 움브라톤의 상회 단장이 된 사연은 한 마디로 미스터리였다.\n\n　“머큐리 부인은 움브라톤으로 시집을 온 거거든.”\n\n　친구가 확신에 찬 목소리로 내게 수군댔다.\n\n　“아무튼 참 기괴한 러브 스토리라니까. 어린 시절에 움브라톤의 무기 밀수 상인과 아는 사이였는데, 어떻게 된 건지 그 사람과 결혼을 결심했다고 하더라고. 집안의 반대에도 불구하고 머큐리 부인이 교회 사람에게 주례를 부탁하려고 하니까, 가문에서는 그녀를 쫓아내겠다고 했다지. 그런데도 머큐리 부인은 뜻을 꺾지 않았다더라고.”\n\n　“그때는 아직 어렸던 거겠지.”\n\n　“그런 결정을 하는 데 나이가 무슨 상관이야?”\n\n　“설사 어리다고 해도 원래의 삶을 버리고 불투명한 미래를 선택한 대가는 누구나 쉽게 감당할 수 있는 게 아냐.”\n\n　나는 고개를 저으며 한숨을 쉬었고, 다시 친구에게 물었다.\n\n　“그건 그렇고, 남편은 지금 어디 있는데?”\n\n　“죽었어.”\n\n　“죽었다고? 어쩌다가?”\n\n　“백야성의 귀족과 트러블이 있었다고 해. 하메스 가문이라고 알아? 아마 사업이나 뭔가 말할 수 없는 일이 있었던 거겠지... 그 잘난 귀족들이 무슨 짓을 했는지 누가 알겠어?”\n\n　친구는 비웃었다.\n\n　“그리고는 끌려가서 죽었다고 하더라고. 그 뒤로 머큐리 부인이 상회를 관리하기 시작한 거야.”\n\n　“부인은 남편의 복수를 하지 않는 건가?”\n\n　“하메스 가문이 얼마나 대단한지 너도 들어봤을 텐데. 머큐리 부인이 원래 속했던 가문조차 상대가 안 될 거라고.”\n\n　술기운이 올라오는 바람에 친구가 무슨 말을 더 했었는지는 기억이 나지 않았다. 다만 머릿속에서 머큐리 부인 같은 사람이라면 그냥 넘어가지는 않을 거라는 막연한 추측만이 떠오를 뿐이었다.",
  str_dispatch_book_chaptercont_15000_5 = "　그 일이 있고 나서 2년이 흘렀다. 한 자작이 내 소설을 무척 마음에 들어 했고, 친구들에게도 나눠주고 싶다며 백야성의 출판업자에게 탁본을 의뢰했다. 출판업자는 이번 일에 대해 상의하고 싶다며 내게 백야성으로 와 달라고 했다. 백야성을 둘러볼 좋은 기회라는 생각에 나는 약속한 시간보다 먼저 출입 허가서를 제출했고, 심사가 통과될 때가지 계속 중립 지구의 여관에 머물고 있었다.\n\n　그곳의 여관은 다양한 건축 양식을 사용했고, 움브라톤과 백야성의 스타일이 뒤섞여 있었다. 내가 묵은 여관은 백야성의 한 평민 가문에서 지은 것으로, 무려 100년의 역사를 자랑했다. 입지도 좋았고, 나란히 늘어선 객실에서 발코니로 나가면 신선한 새벽 햇살을 만끽할 수도 있었다. 나는 온종일 방에 틀어박혀 글을 썼고, 이따금 초저녁 때 홀에 나가 저녁을 먹거나, 불이 꺼질 때까지 신문이나 잡지를 읽기도 했다. 홀의 책장에는 내 소설도 꽂혀 있었다. 날마다 나와 가장 많이 이야기를 나눈 것은 가게의 하인들이었다. 그들은 전날 손님들이 갈아입은 옷을 헝겊 자루에 담고, 내 방으로 아침 식사를 가져다줬다. 옷을 세탁실에 전달하고 나면, 이튿날에 깨끗이 세탁한 옷을 아침 식사와 함께 들고 찾아왔다.\n\n　그날은 날씨가 흐린 탓에 하늘은 온종일 어둑어둑했다. 해가 질 무렵, 중립 지구에 자리 잡은 수많은 가옥의 벽과 난간 사이로는 찬 바람이 불었다. 우울했던 나는 기분 전환 삼아 홀에서 저녁 식사를 했다. 여관 안에는 손님이 많은 편이 아니었던 탓에, 꽤 오래 머물렀던 나는 여러 사람들과 얼굴을 익힐 수 있었다. 그런데 그날은 우연히 낯선 모습을 발견했던 것이다.\n\n　흔히 볼 수 있는 움브라톤 사람 특유의 옷차림, 가죽 부츠와 두툼한 코트, 섬세한 바느질이 돋보이는 검은 스카프, 구릿빛 두건 속에 숨겨진 머리... 상대는 카운터에 기댄 채 나지막한 말투로 여관 주인에게 뭔가를 재빠르게 묻고 있었다. 자세한 내용을 들을 순 없었지만, '출입', '심사'와 같은 단어만 드문드문 들렸다. 백야성에 대해 묻고 있는 게 틀림없었다. 익숙한 목소리에 그 사람이 돌아설 때까지, 나는 자신도 모르게 계속 그 사람을 힐끔거리고 있었다.\n\n　검은 스카프로 입과 코를 반쯤 가리고 있었지만 내 눈은 정확했다. 그 사람은 머큐리 부인이 틀림없었다.",
  str_dispatch_book_chaptercont_15000_6 = "　그녀는 카운터에 기댄 채 하인이 트렁크를 객실로 옮기는 것을 지켜보다가, 눈에 띄는 붉은 머리카락을 이따금 두건 안으로 밀어 넣었다. 나는 자리에서 꼼짝도 하지 못했고, 그저 태연한 척하며 홀을 둘러보며 인파 속에서 그녀의 시종이 따라왔는지 확인하려 했다. 아쉽게도 시종의 흔적은 전혀 보이지 않았다. 그녀는 스카프를 콧날까지 다시 끌어올린 뒤, 고개를 숙인 채 재빨리 방 안으로 사라졌다. 그 모습으로 나는 그녀가 몰래 이 여정에 올랐다는 사실을 알 수 있었다.\n\n　그녀의 발자국이 완전히 사라진 뒤에야 나는 천천히 한숨을 돌릴 수 있었다. 이런 엄청난 인물이 혼자 중립 지구의 여관에 모습을 드러냈다는 사실을 깨닫자, 왠지 불길한 예감에 사로잡힌 나는 조금이라도 빨리 방으로 돌아가려고 했다. 그러나 잠시 앉아있던 나는 무심결에 그녀가 떠난 방향을 멀뚱히 쳐다보고 있었다. 그러기를 여러 번, 그녀가 모습을 드러내기를 은근히 기대하는 내 모습을 깨닫고는 퍼뜩 정신이 들었다.여기까지 생각이 미치자, 어디서 용기가 났는지 나는 그녀가 나타날 때까지 무작정 홀에 앉아 기다리기로 했다.\n\n　웨이터에게 리필을 부탁한 맥주를 절반 정도 마셨을 무렵, 그녀가 객실 복도의 그림자 속에서 천천히 모습을 드러냈다. 이번에는 두건을 벗은 채, 페도라를 쓴 모습이었다. 길게 땋은 머리를 스카프와 코트에 숨긴 그녀는 주변의 시선을 피하려는 듯 어두컴컴한 곳으로 발걸음을 옮기다가 아무도 없는 구석에 앉았다. 그녀가 고른 테이블은 책장 근처에 있었는데, 마침 내게는 10시 방향인 곳이었다. 긴장되면서도 은근히 즐겁다는 생각도 들었다.\n\n　웨이터가 음식을 가지고 올 동안 그녀는 별생각 없이 책장에서 책을 한 권 골랐는데, 그것은 내가 몇 년 전에 쓴 소설인 게 분명했다. 나는 자신도 모르게 등을 떠밀린 듯 자리에서 일어나, 땀으로 젖은 손으로 맥주가 담긴 나무 잔을 쥔 채, 그녀를 향해 한 걸음 한 걸음 다가갔다.\n\n　나는 마침내 그녀의 앞에 섰고, 쭈뼛거릴 새도 없이 술잔을 쥔 채로 그녀가 손에 들고 있는 책을 가리키며, 상대를 전혀 모른다는 표정으로 입을 열었다.\n\n　“그 책이 마음에 드시나요?”\n\n　“책 제목이 마음에 드네요.”\n\n　그녀는 여유롭게 미소를 지은 채 날 올려다보며 손끝으로 도금된 제목을 매만졌다.\n\n　“멋진 걸 생각나게 해 주거든요.”\n\n　그녀의 아름다움에 압도된 나는 숨을 쉬는 것조차 곤란한 느낌이 들었다. 마치 얼음물 속에 얼굴을 담그거나 매서운 찬 바람을 고스란히 맞는 기분이었다. 이빨이 달달 떨릴 정도로 긴장했다는 것을 상대에게 들키지 않으려고 나는 힘겹게 숨을 골랐다.\n\n　“좋아해 주셔서 다행이군요. 제가 그 책의 작가거든요... 거기 쓰여 있는 게 바로 제 이름입니다.”",
  str_dispatch_book_chaptercont_15000_7 = "　그녀의 맞은편에 앉았을 때, 나는 셔츠의 등이 식은땀으로 축축해졌다는 것을 깨달았다. 그때 나는 소설에 대해 잠시 이야기를 했던 것 같지만, 지금 생각해 보면 무슨 말을 했는지 한 마디도 기억나지 않았다. 다만 유일하게 기억나는 것은 낯설다는 감정뿐이었다. 온몸이 호수 속에 푹 잠긴 듯한, 호수의 기슭에서 또 다른 세상의 모습을 지켜보는 듯한 무척 이질적인 기분이었다. 정신을 차렸을 땐 내가 그녀의 방에 있다는 것을 깨달았다. 나는 베란다에 앉아 작은 테이블을 사이에 두고 그녀와 마주 앉았다. 테이블에는 안주와 술잔이 놓여져 있었고, 테이블 한가운데에는 가는 목의 꽃병이 세워져 있었다. 꽃병에는 꽃받침이 푸르스름한 백합 한 송이가 꽂혀 있었다.\n\n　어둠이 완전히 깔리기 전이었지만, 짙은 구름 탓에 사방은 어둡고 음침했다. 점점 매서워지는 찬 바람에 나도 모르게 몸이 부르르 떨렸다. 그제서야 나는 홀에서 하인이 막 음식을 가져오던 때, 그녀의 갑작스러운 제안을 받고 그녀의 방에서 식사를 하게 됐던 것을 자각할 수 있었다. 그녀는 모자와 목도리를 벗은 후 창문을 통해 방 안으로 아무렇게나 던졌고, 코트와 부드러운 의자의 팔걸이가 그녀를 감싸 안았다. 시선을 피하지 않고 그녀를 똑바로 쳐다보는 게 민망해진 나는 시선을 돌렸고, 점점 느슨해지며 바람에 흩날리는 그녀의 머리카락만 쳐다볼 수밖에 없었다.\n\n　“당신처럼 저도 백야성에 가려는 참이에요.”\n\n　그녀는 웃으며, 젖은 휴지에 손가락을 쓱쓱 문질렀다. 그제야 나는 우리가 방금 전까지 각자의 여정에 대해 이야기하고 있었다는 사실이 떠올랐다.\n\n　“어렸을 때, 전 백야성에 살았어요. 그때 가지고 놀던 장난감도 전부 백야성에 남아 있죠.”\n\n　“그러다 나중엔 움브라톤으로 오게 됐는데, 모든 게 마음에 들었어요. 다만 떠날 때 친구와 싸우긴 했지만요...”\n\n　“왜 싸운 거죠?”\n\n　그녀의 말에 나는 진지하게 귀를 기울였다.\n\n　“너무 오래전 일이라 기억이 나질 않네요. 당장이라도 터질 듯 두근거리는 심장이 느껴질 만큼 화가 났었다는 것 외엔 말이죠. 무슨 일 때문이었는지는 모르겠지만, 지금 돌이켜 보면 유치한 일이었을 것 같네요.”\n\n　그녀는 깨끗해진 손으로 머리카락을 천천히 빗어 넘겼고, 땋은 머리를 가볍게 풀어 헤쳤다.\n\n　“그런데 요즘 그 친구가 다시 생각이 나기 시작했어요. 꿈에서부터요.”\n\n　“꿈이요?”\n\n　“네, 꿈이요. 꿈속의 전 여전히 원래 살던 집에서 지내고 있었어요. 새하얀 벽, 갈색 문, 눈앞에는 예전에 썼던 화장대와 거울이 놓여 있었죠.”\n\n　“거울 속에는 제 머리를 빗겨주는 친구의 모습이 비치고 있었어요. 강물 같은 제 머리를 매만지는 친구의 눈빛은 저를 보는 것 같으면서, 다른 것을 생각하는 것 같기도 했죠.”\n\n　“친구는 전보다 훨씬 더 예뻐진 것 같았어요. 잠에서 깬 뒤로 전 며칠 동안 계속 친구가 보고 싶은 마음이 들더군요.”\n\n　“백야성에 가시려는 건 친구를 만나기 위해서인가요?”\n\n　“친구를 「만난다」기보다는...”\n\n　말을 멈춘 그녀는 한숨을 쉬었다.\n\n　“친구를 만날 수 있다면 물론 좋겠지만, 쉬운 일은 아니에요. 직접 만나지 못한다면 멀리서라도 볼 수 있으면 좋겠네요.”\n\n　중립 지구의 여관들이 하나둘 불을 밝히자, 축축하고 뿌연 안개 속에서 여러 크기의 불꽃이 반짝거렸다. 술잔을 들고 날 쳐다보는 그녀의 모습에 사라졌던 두려움이 또다시 슬금슬금 고개를 드는 게 느껴졌다. 그녀의 얼굴에는 표정이 서서히 사라지고, 고요하면서도 흐릿한 달처럼 숙명을 암시하는 듯한 부호만 남겨진 것 같았다. 어둠이 짙게 깔리자 그녀의 얼굴은 깃발처럼 긴 그녀의 머리카락과 함께 어둠 속으로 가라앉았고, 깊은 어둠은 또다시 서늘한 검붉은 빛으로 물들었다.",
  str_dispatch_book_chaptercont_15000_8 = "　정신을 차린 나는 안도의 한숨을 내쉬었다. 침대에 멀쩡하게 누워있는 내 모습에 나는 무거운 짐을 내려놓은 것만 같은 기분이 들었다. 숙취로 욱신거리는 머리를 달래며 나는 창밖을 보았고, 아직도 하늘이 어둑한 걸 보니 평소 일어나던 시간보다 이른 것 같았다. 하인들도 방문을 두드리지 않을 만큼 이른 시간이었다. 머리를 감싼 채 방문을 나선 나는 머큐리 부인이 있는 방을 바라봤지만, 방 안은 이미 텅 비어 있었다. 나는 낙담한 채 복도를 따라 홀까지 내려오다가, 여관 주인을 발견하고 발걸음을 멈췄다.\n\n　“저기... 혹시 그 부인은...”\n\n　목이 쉰 탓에 나는 뒤에 있는 빈방을 가리키며 가까스로 입을 열었다.\n\n　“...부인은 떠났나요?”\n\n　“새벽에 떠났습니다.”\n\n　주인은 하던 일을 멈추곤 흥미로운 표정으로 날 쳐다보며 말했다.\n\n　“백야성 사람들이 비공정을 보냈더군요. 제 사람 보는 눈은 틀리는 일이 없습니다. 그 사람, 귀족이죠?”\n\n　나는 어떻게 반응해야 할지 몰랐고, 왠지 모를 실망스러운 마음이 들 뿐이었다. 가게 주인은 한숨을 쉬며 입을 열었다.\n\n　“처음 왔을 때부터 평범한 사람은 아닌 것 같았습니다. 사람을 불안하게 만들 정도로 아름다운 분이었죠.”\n\n　말을 하던 가게 주인은 놀랍다는 표정으로 날 쳐다봤다.\n\n　“그런 분한테 선뜻 말을 걸다니 정말 대단하십니다.”\n그 말에 나는 고개를 저었다. 목구멍이 갑갑해진 느낌이 든 나는 오던 길로 천천히 돌아갔고, 방으로 돌아와 책상에 앉았다. 잠시 뒤 하인이 아침 식사와 세탁한 옷을 가져왔다. 창밖의 햇살이 눈부시게 빛날 때까지 나는 책상 앞에 오래도록 앉아 있다가 자리에서 일어났다.\n\n　평소처럼 깨끗이 세탁된 옷을 옷장에 넣으려고 침대에서 옷을 개기 시작했지만, 마음은 이미 다른 곳에 가 있었다. 그렇게 멍하니 옷을 집고 몇 번 털었을 때, 갑자기 옷에서 얇은 무언가가 팔랑거리며 떨어졌다. 그것을 집어 든 나는 엄청난 선물을 받은 것처럼 흥분을 주체할 수 없었다.\n\n　그것은 책갈피처럼 납작하게 눌러서 말린 백합이었고, 백합은 그녀의 상징이었다.",
  str_dispatch_book_chaptercont_15000_9 = "　그 후 사나흘을 더 기다렸지만 예상과 달리 출입 심사는 여전히 감감무소식이었다. 이상하다는 생각이 들자 나는 초조한 기분에 사로잡혔다. 자작과 출판업자에게 약속했던 날이 눈앞까지 다가왔고, 나는 여관에서 나와 백야성의 소식에 대해 수소문할 수밖에 없었다. 아니면 약속 시간에 늦지 않도록 다른 방법을 찾아봐야 했다.\n\n　그러던 나는 최근 백야성에서 일어난 살인 사건에 대한 이야기를 듣게 되었다. 하메스 가문의 장남이 운 나쁘게도 숨을 거둔 탓에, 백야성의 경계가 삼엄해지면서 출입 심사가 지연되었던 것이었다. 불안을 가까스로 가라앉힌 채 여관으로 돌아온 나는 머큐리 부인이 들려줬던 이야기를 떠올렸고, 그 이야기 중에는 왠지 이번 죽음을 암시하는 듯한 사연이 담겨 있는 것 같았다. 자작과 만나기로 한 사실을 까맣게 잊을 만큼 나는 얼이 빠지고 말았다.\n\n　여관에서 빨래 일을 하는 사람들도 한 마디씩 거들 만큼 사건을 둘러싼 소문이 요란하게 들끓었지만, 왠지 모르게 나는 그 분위기에 휘말리지 않았다. 나는 사정을 알고 있는 사람이었고, 그리고 그 비밀을 지켜줘야 했기 때문이었다. 풍파가 가라앉기 전까지는 진실이 새어 나가선 안 된다. 며칠이 또 지난 뒤에야 출입 허가가 서서히 풀리기 시작했고, 심사 문서가 발급되면서 살인 사건의 결과도 알려지기 시작했다. 백야성은 이미 범인을 체포했으며, 곧 교수형에 처할 것이라고 했다.\n\n　불안한 기분에 휩싸인 채 나는 자작을 만나러 갔다. 책에 관한 상대의 감상을 끊고, 살인 사건에 대해 자세히 묻고 싶다는 충동을 여러 번 참아내야 했다. 즐거운 듯 이야기에 집중하는 상대의 모습에 나는 기묘한 기분이 들었다. 살고 있는 세상에서 두 사람의 목숨이 사라진, 그리고 사라지게 될 상황에 그는 전혀 개의치 않는 듯했고, 특히 나 같은 이방인에게는 설명할 가치조차 없다고 생각하는 것 같았다. 자작은 출판업자에게 나를 데리고 백야성을 둘러보라고 말한 뒤 자리를 떠났다.\n\n　자작이 떠난 것을 확인하자마자 나는 출판업자에게 형장을 돌아보고 싶다고 말했다. 그곳에 도착했을 때 시간은 이미 황혼 무렵이었다.\n\n　“교수형이 아직 집행되지 않은 겁니까?”\n\n　나는 희망을 품은 채 물었다.\n\n　출판업자는 잠시 생각에 잠기더니 내게 되물었다.\n\n　“하메스 가문의 사건 말입니까?”\n\n　“네, 맞아요.”\n\n　“이미 끝났답니다.”\n\n　이해할 수 없다는 내 표정을 확인한 출판업자가 몇 마디 덧붙였다.\n\n　“처형식은 이미 집행됐답니다. 바로 어제 말입니다.”\n\n　교수대는 평소에는 접근을 허용하지 않는 탓에, 나는 멀리서 지켜볼 수밖에 없었다. 형장 주변에는 인적이 드물었고, 통통하게 살이 오른 비둘기만 뒤뚱거리며 이리저리 돌아다니고 있었다.\n\n　“직접 보셨습니까?”\n\n　“물론이죠.”\n\n　“범인은 누구였습니까?”\n\n　“그게 궁금하시면 심판소에 가서 물어보시죠.”\n나는 점점 의구심이 들었다.\n\n　“범인은 어떻게 생긴 사람이었습니까?”\n\n　출판업자는 고개를 저었다.\n\n　“글쎄요, 죄수들은 전부 낡아빠진 죄수복을 입고 있어서 누구인지 알아볼 수 없습니다. 머리에도 천을 뒤집어써야 하죠. 중죄를 지었다면 눈만 보이는 철 가면을 써야 합니다. 교수형에 처하는 범인의 얼굴은 드러나면 안 되니 말이지요.”\n\n　“어째서죠?”\n\n　“끔찍하잖아요.”\n\n　출판업자는 웃으며 대답했다.\n\n　그 말에 나는 바닥으로 추락하는 기분이 들었다. 그리고는 억지 미소를 지었다.\n\n　“얼굴을 가렸다고 끔찍하지 않은 건 아닐 텐데요.”\n\n　“그래도 그 쪽이 더 재미있지 않습니까?”\n\n　출판업자는 여전히 웃으며 대답했다.",
  str_dispatch_book_chaptercont_15000_10 = "　나는 도망치듯 백야성을 떠났고. 움브라톤에 묵으라던 친구의 초대도 황급히 거절했다. 움브라톤을 다시 찾은 것은 그로부터 몇 개월이 지난 후의 일이었다.\n\n　친구는 평소처럼 날 술집으로 데려갔다. 술집은 사람들로 가득한 탓에 왁자지껄 떠드는 소리가 여기저기서 들려왔다. 술에 반쯤 취한 친구는 술잔을 뒤집더니 잔 바닥을 들곤 인파의 어딘가를 가리키며 말했다.\n\n　“저기 봐, 콜로세움의 배신자야.”\n\n　고개를 돌리고 검은 옷차림의 상대를 발견하고서야 나는 몇 년 전에 봤던 싸움이 기억났다. 그러자 머큐리 부인에 관한 기억도 절로 떠오르게 되었다. 만약 몇 달 전에 저 상대를 만났다면 난 분명히 서둘러 자리를 피했을 것이다. 하지만 시간이 지나면서 내 마음도 차분해져 있었는지, 나는 술잔을 든 채 상대에게 다가갔다.\n\n　나는 술기운을 빌어 그에게 말을 걸었다.\n\n　“당신, 기억이 나는군요. 전에 콜로세움에서 봤었죠.”\n\n　순간 그의 표정이 어두워졌고, 옆에 있던 동료와 눈빛을 교환했다. 진작에 두려움을 잊어버린 나는 그들의 흉악함도 잊은 채 그저 이야기를 꺼내 놓기에 바빴다.\n\n　“저는 여러분을 이끄는... 머큐리 부인과 만난 적이 있습니다.”\n\n　그 말에 그들의 표정이 마침내 부드러워졌다.\n\n　“안부 좀 전해주십시오. 중립 지구의 작가라고 하면 기억하실 겁니다.”\n\n　나는 내 추측이 맞는지 확인하기 위해 그들의 눈빛을 살피며 슬픔의 흔적을 찾아내려 했다. 하지만 오래전에 생긴 상처를 간직한 풋풋한 얼굴 위로는 그저 담담한, 뜻을 알 수 없는 표정이 떠올랐다.\n\n　“잘 지내고 계시죠?”\n\n　떠보는 듯한 내 질문에 그는 그렇다고 대답했다. 그리곤 시선을 서로 교환하더니 가볍게 한숨을 쉬었다.\n\n　“다만 더는 상회의 단장은 아니십니다.”\n\n　“그럼 단장이 없다는 얘깁니까?”\n\n　그 말에 그들은 웃음을 터뜨렸다.\n\n　“누군가 사라지면 또 누군가 그 자리를 채우는 법이죠. 상회에 어떻게 단장이 없을 수가 있겠어요?”\n\n　대화는 거기서 끝이 났다. 그 뒤로 나는 머큐리 부인을 더는 볼 수도 없었고, 그녀에 관한 소식도 더는 들을 수 없었다.\n\n　그러나 그 뒤로도 움브라톤과 백야성에서 그녀에 관한 소문은 끊이지 않았다. 사람들 사이에서 이런저런 이야기가 퍼진 탓에 나도 소문을 듣긴 했지만, 단편적인 이야기만으로는 그날 백야성으로 간 머큐리 부인이 원수에게 죽음의 서한을 보냈는지, 아니면 꿈속의 친구를 그저 멀리서 바라보았을 뿐인지는 알 수 없었다.",
  str_dispatch_book_chaptercont_15000_11 = "　독자 여러분, 이본 여사의 소설집을 통해 여러분께 인사드릴 수 있어서 영광스럽게 생각합니다. 저희는 이번 소설집의 제목을 《레드 머큐리》라고 정했습니다. 부디 여러분의 마음에 들었으면 좋겠습니다. 사실 《레드 머큐리》가 이본 여사 최고의 작품은 아닐지도 모릅니다. 아무래도 분량이 적은 단편 소설이니 말이지요. 하지만 그럼에도 불구하고 이 소설은 가장 뜨거운 논쟁이 예상되는 작품일 것입니다. 저도 이본 여사의 충성스러운 독자로서, 전설적인 인물에 관한 이야기를 읽고 난 뒤 실존하는 '머큐리 부인'을 찾아보고 싶다는 생각이 가장 먼저 들었습니다. 아마 여러분도 저와 같은 생각을 하셨으리라 생각합니다.\n\n　그래서 저는 움브라톤에서 무기 판매를 벌이는 상회도, 입장료가 1천 나이티움이나 되는 콜로세움도 직접 방문했습니다. 게다가 백야성 심판소의 서류를 열람하기도 했고, 하메스 가문의 하인들을 직접 만나 그해 떠들썩했던 살인 사건에 대해 물어보기도 했습니다. 이렇게 제가 발품을 팔아 확보한 증거와 결론을 독자 여러분께도 전해드리고자 합니다.\n\n　이본 여사의 소설은 '진실'을 담아내는 것으로 유명합니다. 여러분은 항상 '분명히 그런 일이 있었다'는 증거를 찾아내실 수 있을 것입니다. 예를 들면 움브라톤의 무기 판매상 같은 것이 되겠지요. 정확히 말하자면 움브라톤에는 무기를 판매하는 상회가 적지 않습니다. 하지만 일부 상회는 다른 물건도 취급하고 있지요. 10년 전에 쓰인 탓에 당시 움브라톤에 모든 무기 거래를 관리하는 상회가 있었는지를 입증하는 것은 쉽지 않았습니다. 움브라톤의 복잡한 상황은 의지만으로 밝힐 수 있는 게 아니니까요.\n\n　백야성 살인 사건이 기록으로 남을 수 있었던 것은 사건의 당사자가 백야성에서 유명한 하메스 가문의 장남이었기 때문입니다. 라치온 님의 큰아들이 살해된 데다, 흉기로 사용된 가늘고 긴 금속 무기는 머큐리 부인의 무기를 떠올리게 했습니다. 콜로세움에서 포로의 숨통을 끄는 '가늘고 날카로운 빛줄기'와 딱 맞아떨어지지 않습니까? 하지만 살인 사건의 범인에 관한 기록은 문서에 남아있지 않았습니다. 아마 범인은 극형에 처해졌을 것입니다. 백야성에서는 그 사건에 대해 쉬쉬한 것도 모자라, 범인의 얼굴도 공개하지 않았습니다. 그렇다고 속상해하진 않으셔도 됩니다. 그것은 백야성과 귀족들이 늘 쓰는 수법이니까요. 진실은 언제나 밝혀지기 마련입니다. 어쨌든 죽지 않는 사람이란 존재할 수 없으니까요. 그렇지 않습니까?",
  str_dispatch_book_chaptercont_15000_12 = "　독자 여러분이 가장 궁금해 하시는 것은 '머큐리 부인은 대체 누구인가?'겠지요. 하지만 제 고증에 따르면 머큐리 부인은 허구의 인물에 불과합니다. 그녀의 미모에 관한 과장된 이야기가 바로 그 증거라 할 수 있습니다. 10년 전, 로맨스 소설이 한창 인기를 끌었을 때(물론 지금도 여전히 잘 팔리고 있지만), 당시 여주인공들은 대부분 믿기 어려운 미모를 지니고 있었습니다. 이본 여사가 머큐리 부인에게 '두려울 정도로 빼어난 미모'를 부여한 것은 순전히 당시 유행을 따른 결과입니다. 사랑을 위해 귀족 신분도 버렸다는 이야기 역시 풍자임이 분명합니다. 신분의 벽을 뛰어넘어 하나가 된 연인은 로맨스 소설의 흔한 클리셰니 말입니다.\n\n　그렇다면 이야기 속에서 이본 여사는 머큐리 부인에게 어떤 운명을 선사했을까요? 에필로그에 나온 것처럼 머큐리 부인이 백야성에 간 것은 복수 때문일까요, 아니면 친구를 만나기 위해서였을까요? 상당수의 귀족이 사형을 당했거나 추방(그 이유조차 우리는 알 수 없지만)됐다는 백야성의 유언비어를 떠올리면, 이본 여사의 설정 속 사랑은 그저 허울에 불과하다는 사실을 추측할 수 있습니다. 머큐리 부인이 움브라톤으로 시집간 진짜 이유는 사실 피난 때문이었을 것입니다. 이본 여사의 글짓기 습관을 잘 아시는 독자라면 '말할 수 없는 일'을 거짓말로 교묘히 덮는 그분의 실력도 아실 겁니다.\n\n　그렇다고 머큐리 부인이 그저 친구를 만나기 위해서 백야성에 간 것이라고 단정 지을 수 있을까요? 아니요, 그렇지도 않습니다. 여관에서의 만남이라는 챕터에서 이본 여사는 진실하고, 효과적인 정보를 전달하는 데 인색한 모습을 보이고 있습니다. 자신의 눈앞에 흐르는 강물에서 물을 손으로 뜨는 것처럼 말이지요. 그것만으로는 강 전체를 정의할 수는 없습니다. 이야기 속에서 불쌍한 희생자는 그녀가 벼르던 원수이거나, 그저 그리운 어릴 적 친구일지도 모릅니다. 어쩌면 두 가지 모두 그녀의 목적일 수도 있겠지요. 그중 일부만 '나'라는 작중 인물에게 알려준 것일지도 모릅니다.\n\n　독자 여러분, 어쩌면 제 결론에 실망하셨을지도 모르지만, 《레드 머큐리》는 탐정 소설이 아닙니다. 이본 여사도 '진실'에 관한 책을 쓰려던 게 아니고, 그저 우리에게 '진실'의 단초를 보여주고 싶었을 뿐입니다. 전설에 의해 가려진, 진실한 생명에 관한 이야기 말입니다. 이본 여사가 싱그러운 백합, 예리한 검, 경탄이 절로 나올 만큼 빼어난 외모를 머큐리 부인에게 선사한 것은, 어쩌면 인물과 만나는 순간, 찰나의 '진실'을 놓치지 않도록 우리에게 정신 똑바로 차리라고 말해주려던 게 아닐까요? 진실은 손바닥에 담긴 한 움큼의 물에 불과하지만, 그 어떤 대단한 전설을 더한 것보다 귀중한 것이니 말입니다.",
  str_dispatch_book_chapter_get_des = "파견이 끝난 후 일정 확률로 해당 서적이 발견됩니다.",
  str_dispatch_book_chapter_get_des1 = "콜로서스 데이터베이스에서 획득"
}
return config
